        if (StringUtility.stringHasValue(customizedNextVersion) && StringUtility.isTrue(customizedNextVersion)) {
            this.customizedNextVersion = true;
        } else {
            this.customizedNextVersion = false;
        }

        super.initialized(introspectedTable);
    }

