public static Color randomColor(int min, int max) {
        if (min > 255) {
            min = 255;
        }
        if (min < 0) {
            min = 0;
        }
        if (max > 255) {
            max = 255;
        }
        if (max < 0) {
            max = 0;
        }
        return new Color(min + R.random(0, max - min),
                         min + R.random(0, max - min),
                         min + R.random(0, max - min));
    }

public static int[] getRGB(BufferedImage srcIm, int x, int y) {
