public static List<String> getParamNames(Method method) {
        try {
            int size = method.getParameterTypes().length;
            if (size == 0)
                return new ArrayList<String>(0);
            List<String> list = ClassMetaReader.getParamNames(method.getDeclaringClass()).get(ClassMetaReader.getKey(method));
            if (list == null)
                return null;
            if (list.size() == size)
                return list;
            if (list.size() > size)
                return list.subList(0, size);
            return null;
        } catch (Throwable e) {
            throw new RuntimeException(e);
        }
    }

public static List<String> getParamNames(Constructor<?> constructor) {
        try {
            int size = constructor.getParameterTypes().length;
            if (size == 0)
                return new ArrayList<String>(0);
            List<String> list =  ClassMetaReader.getParamNames(constructor.getDeclaringClass()).get(ClassMetaReader.getKey(constructor));
            if (list != null && list.size() != size)
                return list.subList(0, size);
            return list;
        } catch (Throwable e) {
            throw new RuntimeException(e);
        }
    }

public String readItem(char ... ends) throws IOException{
        StringBuilder sb = new StringBuilder();
        while(true){
            switch (peek()) {
            case ' ':
            case '\r':
            case '\n':
            case -1:
                return sb.toString();
            default:
                for(Character c : ends){
                    if(c.charValue() == peek()){
                        return sb.toString();
                    }
                }
                sb.append((char)poll());
            }
        }
    }

public String readLine() throws IOException{
        StringBuilder sb = new StringBuilder();
        for(;;){
            int v = peek();
            if(v == '\r' || v == '\n'){
                poll();
                v = peekNext();
                if(v == '\r' || v == '\n'){
                    poll();
                }
                break;
            }
            sb.append((char)poll());
        }
        return sb.toString();
    }

public int poll() throws IOException{
        peekindex = 0;
        int v = -1;
        if(cache.size() <= 0){
            v = is.read();
        } else {
            v = cache.poll();
        }
        if(v == -1){
            end = true;
        }
        if(v == '\n'){
            col = 0;
            row ++;
        } else {
            col ++;
        }
        return v;
    }

public int peek(int index) throws IOException{
        while(cache.size() <= index){
            cache.add(is.read());
        }
        return cache.get(index);
    }

public int peek() throws IOException{
        peekindex = 0;
        int v = peek(peekindex ++);
        if(v == -1){
            end = true;
        }
        return v;
    }

public long skip(long n) throws IOException {
        int s = cache.size();
        if(s > 0){
            if(s < n){
                n = n - s;
            } else {
                for(int i = 0; i < n; i ++){
                    cache.poll();
                }
                return n;
            }
        }
        return super.skip(n) + s;
    }

public boolean startWith(String start) throws IOException{
        char[] cs = start.toCharArray();
        int i = 0;
        for(;i < cs.length; i ++){
            if(peek(i) != cs[i]){
                return false;
            }
        }
        return true;
    }

protected boolean isExclusion(String matchUrl) throws IOException, ServletException {
    	if (ignorePtn != null && ignorePtn.matcher(matchUrl).find()) {
    		return true;
    	}
    	if (exclusionsSuffix != null) {
    		if (exclusionsSuffix.matcher(matchUrl).find()) {
	    		return true;
    		}
    	}
    	if (exclusionsPrefix != null) {
    		if (exclusionsPrefix.matcher(matchUrl).find()) {
	    		return true;
    		}
    	}
    	if (exclusionPaths != null && exclusionPaths.contains(matchUrl)) {
    		return true;
    	}
    	return false;
    }

