private void initFilePool() {
  		String home = config.get("pool-home").toString();
  		try {
  			home = Disks.normalize(home);
  			if (home == null)
  				home = config.get("pool-home").toString();
  			long max = config.containsKey("pool-max") ? ((Number) config.get("pool-max")).longValue() : 2000;
  			if (home.contains("${app.home}")) {
  				try {
  					// 这里引用了Mvcs类, 不太舒服,但应该还是有益处的
  					home = home.replace("${app.home}", Mvcs.getServletContext().getRealPath("/"));
  				} catch (Throwable e) {
  				}
  			}
  			try {
  				pool = NutFilePool.getOrCreatePool(home, max);
  			} catch (Exception e) {
  				// 看看是不是Mvc环境,尝试在WebContent下创建
  				if (!home.startsWith("~/") || Mvcs.getServletContext() == null)
  					throw e;
  				try {
  					String tmp = Mvcs.getServletContext().getRealPath("/") + home.substring(2);
  					pool = NutFilePool.getOrCreatePool(tmp, max);
  					log.info("had created filepool under webapp root path");
  				} catch (Exception e1) {
  					throw e; // 抛出原本的异常好了,哎...
  				}
  			}
  			pool = new SynchronizedFilePool(pool);
  		} catch (Throwable e) {
  			if (log.isWarnEnabled())
  				log.warnf("NutDao FilePool create fail!! Blob and Clob Support is DISABLE!! Home=" + home, e);
  		}
  		isInit = true;
  	}

public void setupEntityField(Connection conn, Entity<?> en) {
        List<MappingField> mfs = new ArrayList<MappingField>();
        for (MappingField mf : en.getMappingFields()) {
            if (mf.getTypeMirror().isEnum()) {
                mfs.add(mf);
            }
        }
        if (mfs.isEmpty())
            return;
        Statement stat = null;
        ResultSet rs = null;
        ResultSetMetaData rsmd = null;
        try {
            // 获取数据库元信息
            stat = conn.createStatement();
            rs = stat.executeQuery(createResultSetMetaSql(en));
            rsmd = rs.getMetaData();
            // 循环字段检查
            List<String> columnNames = new ArrayList<String>();
            List<String> columnLabels = new ArrayList<String>();
            int columnCount = rsmd.getColumnCount();
            for (int i = 1; i <= columnCount; i++) {
                columnNames.add(rsmd.getColumnName(i));
                columnLabels.add(rsmd.getColumnLabel(i));
            }
            for (MappingField mf : mfs) {
                try {
                    int ci = columnNames.indexOf(mf.getColumnName()) + 1;
                    if (ci == 0) {
                        log.debugf("Can not find @Column(%s) in table/view (%s), skip checking", mf.getColumnName(), rsmd.getTableName(1));
                        continue;
                    }
                    // 枚举类型在数据库中的值
                    if (Daos.isIntLikeColumn(rsmd, ci)) {
                        mf.setColumnType(ColType.INT);
                    } else {
                        mf.setColumnType(ColType.VARCHAR);
                    }
                }
                catch (Exception e) {
                }
            }
        }
        catch (Exception e) {
            if (log.isDebugEnabled())
                log.debugf("Table '%s' doesn't exist! class=%s", en.getViewName(), en.getType().getName());
        }
        // Close ResultSet and Statement
        finally {
            Daos.safeClose(stat, rs);
        }
    }

