            if (sp != null)
                conn.rollback(sp);
            else
                log.debug("Null Savepoint found, skip, id=" + id);
        }
        catch (Throwable e) {
        }
        return this;
    }

public void close() {
        if (debug)
            log.debugf("close id=%s", id);
        try {
            if (conn == null)
                return;
            if (_autoCommit)
                conn.setAutoCommit(true);
            conn.close();
            conn = null;
        }
        catch (Throwable e) {
        }
    }

