public long load() throws IOException {
        if (item.isStreamEnd)
            return readed;
        RingItem ri = item;
        while (!ri.isLoaded) {
            ri.load(ins);
            if (ri.max > 0)
                readed += ri.max;
            ri = ri.next;
        }
        return readed;
    }

