        }
        if(type == TYPE_LIST){
            // fix issue #1109, 列表的key需要重排
            List list = new ArrayList();
            List<Integer> keys = new ArrayList<Integer>();
            List<String> keys2 = new ArrayList<String>();

            for (String key : child.keySet()) {
                try {
