public Object mergeItems(Object... objs) {
        if (objs == null || objs.length == 0) {
            return null;
        }
        if (objs.length == 1) {
            return objs[0];
        }
        // @ TODO 这里要不要判断是否兼容呢?
        if (objs[0] instanceof Map) {
            return mergeMap(objs);
        }
        if (objs[0] instanceof List) {
            return mergeList(objs);
        }
        return mergeObj(objs);
    }

@SuppressWarnings({"rawtypes", "unchecked"})
    private static Object mergeObj(Object[] objs) {
        List list = new ArrayList();
        for (Object obj : objs) {
            if (list.contains(obj)) {
                continue;
            }
            list.add(obj);
        }
        return list;
    }

@SuppressWarnings({"rawtypes", "unchecked"})
    private static Object mergeList(Object... objs) {
        List list = new ArrayList();
        for (Object li : objs) {
            List src = (List) li;
            for (Object obj : src) {
                if (!list.contains(obj)) {
                    list.add(obj);
                }
            }
        }
        return list;
    }

@SuppressWarnings({"unchecked", "rawtypes"})
    private static Object mergeMap(Object... objs) {
        Map obj = new LinkedHashMap();
        for (int i = 0; i < objs.length; i++) {
            Map map = (Map) objs[i];
            for (Object key : map.keySet()) {
                Object objval = obj.get(key);
                Object val = map.get(key);
                if (objval != null && (val instanceof List || val instanceof Map)) {
                    val = merge(objval, val);
                }
                obj.put(key, val);
            }
        }
        return obj;
    }

final void set(ClassWriter cw, final int nLocal, final Object[] local,
            final int nStack, final Object[] stack) {
        int i = convert(cw, nLocal, local, inputLocals);
        while (i < local.length) {
            inputLocals[i++] = TOP;
        }
        int nStackTop = 0;
        for (int j = 0; j < nStack; ++j) {
            if (stack[j] == Opcodes.LONG || stack[j] == Opcodes.DOUBLE) {
                ++nStackTop;
            }
        }
        inputStack = new int[nStack + nStackTop];
        convert(cw, nStack, stack, inputStack);
        outputStackTop = 0;
        initializationCount = 0;
    }

private static int convert(ClassWriter cw, int nInput, Object[] input,
            int[] output) {
        int i = 0;
        for (int j = 0; j < nInput; ++j) {
            if (input[j] instanceof Integer) {
                output[i++] = BASE | ((Integer) input[j]).intValue();
                if (input[j] == Opcodes.LONG || input[j] == Opcodes.DOUBLE) {
                    output[i++] = TOP;
                }
            } else if (input[j] instanceof String) {
                output[i++] = type(cw, Type.getObjectType((String) input[j])
                        .getDescriptor());
            } else {
                output[i++] = UNINITIALIZED
                        | cw.addUninitializedType("",
                                ((Label) input[j]).position);
            }
        }
        return i;
    }

