public static boolean isExtension(String filename, String[] extensions) {
        if (filename == null) {
            return false;
        }
        if ((extensions == null) || (extensions.length == 0)) {
            return (indexOfExtension(filename) == -1);
        }
        String fileExt = getExtension(filename);
        for (int i = 0; i < extensions.length; i++) {
            if (fileExt.equals(extensions[i])) {
                return true;
            }
        }
        return false;
    }

public static boolean isExtension(String filename, Collection extensions) {
        if (filename == null) {
            return false;
        }
        if ((extensions == null) || extensions.isEmpty()) {
            return (indexOfExtension(filename) == -1);
        }
        String fileExt = getExtension(filename);
        for (Iterator it = extensions.iterator(); it.hasNext();) {
            if (fileExt.equals(it.next())) {
                return true;
            }
        }
        return false;
    }

public static boolean wildcardMatchOnSystem(String filename, String wildcardMatcher) {
        return wildcardMatch(filename, wildcardMatcher, IOCase.SYSTEM);
    }

public static boolean wildcardMatch(String filename, String wildcardMatcher, IOCase caseSensitivity) {
        if ((filename == null) && (wildcardMatcher == null)) {
            return true;
        }
        if ((filename == null) || (wildcardMatcher == null)) {
            return false;
        }
        if (caseSensitivity == null) {
            caseSensitivity = IOCase.SENSITIVE;
        }
        filename = caseSensitivity.convertCase(filename);
        wildcardMatcher = caseSensitivity.convertCase(wildcardMatcher);
        String[] wcs = splitOnTokens(wildcardMatcher);
        boolean anyChars = false;
        int textIdx = 0;
        int wcsIdx = 0;
        Stack backtrack = new Stack();

        // loop around a backtrack stack, to handle complex * matching
        do {
            if (!backtrack.isEmpty()) {
                int[] array = (int[]) backtrack.pop();
                wcsIdx = array[0];
                textIdx = array[1];
                anyChars = true;
            }

            // loop whilst tokens and text left to process
            label:
            while (wcsIdx < wcs.length) {

                switch (wcs[wcsIdx]) {
                    case "?":
                        // ? so move to next text char
                        textIdx++;
                        anyChars = false;

                        break;
                    case "*":
                        // set any chars status
                        anyChars = true;
                        if (wcsIdx == (wcs.length - 1)) {
                            textIdx = filename.length();
                        }

                        break;
                    default:
                        // matching text token
                        if (anyChars) {
                            // any chars then try to locate text token
                            textIdx = filename.indexOf(wcs[wcsIdx], textIdx);
                            if (textIdx == -1) {
                                // token not found
                                break label;
                            }
                            int repeat = filename.indexOf(wcs[wcsIdx], textIdx + 1);
                            if (repeat >= 0) {
                                backtrack.push(new int[]{wcsIdx, repeat});
                            }
                        } else {
                            // matching from current position
                            if (!filename.startsWith(wcs[wcsIdx], textIdx)) {
                                // couldnt match token
                                break label;
                            }
                        }

                        // matched text token, move text index to end of matched token
                        textIdx += wcs[wcsIdx].length();
                        anyChars = false;
                        break;
                }

                wcsIdx++;
            }

            // full match
            if ((wcsIdx == wcs.length) && (textIdx == filename.length())) {
                return true;
            }

        } while (!backtrack.isEmpty());

        return false;
    }

