public static RamlType valueOf(String name) {
    switch (name.toLowerCase()) {
      case "boolean":
        return BOOLEAN;
      case "byte":
      case "short":
      case "int":
      case "integer":
      case "long":
        return INTEGER;
      case "float":
      case "double":
        return NUMBER;
      case "char":
      case "character":
      case "string":
        return STRING;
      case "file":
      case "upload":
      case "path":
      case "binary":
        return FILE;
      case "date":
      case "datetime":
      case "localdatetime":
        return DATE_TIME;
    }
    return new RamlType("object", name);
  }

