        if (mail.getBodyHtml() == null || mail.getBodyHtml().equals("")) {

            multiPartEmail = new MultiPartEmail();
            multiPartEmail.setMsg(mail.getBodyText());

        } else if (mail.getBodyText() == null || mail.getBodyText().equals("")) {
