public void incrErrorCount() {
        long count = errorCount.incrementAndGet();
        // 如果节点是可用状态，同时当前连续失败的次数超过限制maxClientConnection次，那么把该节点标示为不可用
        if (count >= maxInvokeError && stat.get()) {
