private static int grabProcessOutput(
            @NonNull final Process process,
            @NonNull final ProcessOutput output ) throws InterruptedException
    {
        Thread threadErr = new Thread( "stderr" )
        {
            @Override
            public void run()
            {
                InputStream stderr = process.getErrorStream();
                OutputStream stream = output.getErrorOutput();
                try
                {
                    ByteStreams.copy( stderr, stream );
                    stream.flush();
                }
                catch ( IOException e )
                {
                    // ignore?
                }
                finally
                {
                    try
                    {
                        Closeables.close( stderr, true /* swallowIOException */ );
                    }
                    catch ( IOException e )
                    {
                        // cannot happen
                    }
                    try
                    {
                        Closeables.close( stream, true /* swallowIOException */ );
                    }
                    catch ( IOException e )
                    {
                        // cannot happen
                    }
                }
            }
        };
        Thread threadOut = new Thread( "stdout" )
        {
            @Override
            public void run()
            {
                InputStream stdout = process.getInputStream();
                OutputStream stream = output.getStandardOutput();
                try
                {
                    ByteStreams.copy( stdout, stream );
                    stream.flush();
                }
                catch ( IOException e )
                {
                    // ignore?
                }
                finally
                {
                    try
                    {
                        Closeables.close( stdout, true /* swallowIOException */ );
                    }
                    catch ( IOException e )
                    {
                        // cannot happen
                    }
                    try
                    {
                        Closeables.close( stream, true /* swallowIOException */ );
                    }
                    catch ( IOException e )
                    {
                        // cannot happen
                    }
                }
            }
        };
        threadErr.start();
        threadOut.start();
        // it looks like on windows process#waitFor() can return
        // before the thread have filled the arrays, so we wait for both threads and the
        // process itself.
        threadErr.join();
        threadOut.join();
        // get the return code from the process
        return process.waitFor();
    }

public static String encrypt(String data, String key) {
        try {
            Cipher c = Cipher.getInstance("DES/ECB/PKCS5Padding");
            c.init(Cipher.ENCRYPT_MODE, SecretKeyFactory.getInstance("DES").generateSecret(new DESKeySpec(key.getBytes())));
            return Hex.encodeHexString(c.doFinal(data.getBytes()));
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

public static String decrypt(String data, String key) {
        try {
            Cipher c = Cipher.getInstance("DES/ECB/PKCS5Padding");
            c.init(Cipher.DECRYPT_MODE, SecretKeyFactory.getInstance("DES").generateSecret(new DESKeySpec(key.getBytes())));
            return new String(c.doFinal(Hex.decodeHex(data.toCharArray())), Charset.defaultCharset());
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

private static String readName(DataInputStream dis, byte data[])
            throws IOException {
        int c = dis.readUnsignedByte();
        if ((c & 0xc0) == 0xc0) {
            c = ((c & 0x3f) << 8) + dis.readUnsignedByte();
            HashSet<Integer> jumps = new HashSet<Integer>();
            jumps.add(c);
            return readName(data, c, jumps);
        }
        if (c == 0) {
            return "";
        }
        byte b[] = new byte[c];
        dis.readFully(b);
        String s = IDN.toUnicode(new String(b));
        String t = readName(dis, data);
        if (t.length() > 0) {
            s = s + "." + t;
        }
        return s;
    }

private static String readName(
            byte data[],
            int offset,
            HashSet<Integer> jumps
    ) throws IOException {
        int c = data[offset] & 0xff;
        if ((c & 0xc0) == 0xc0) {
            c = ((c & 0x3f) << 8) + (data[offset + 1] & 0xff);
            if (jumps.contains(c)) {
                throw new DnsException("", "Cyclic offsets detected.");
            }
            jumps.add(c);
            return readName(data, c, jumps);
        }
        if (c == 0) {
            return "";
        }
        String s = new String(data, offset + 1, c);
        String t = readName(data, offset + 1 + c, jumps);
        if (t.length() > 0) {
            s = s + "." + t;
        }
        return s;
    }

protected static int toDigit(final char ch, final int index) throws HexDecodeException {
        final int digit = Character.digit(ch, 16);
        if (digit == -1) {
            throw new HexDecodeException("Illegal hexadecimal character " + ch + " at index " + index);
        }
        return digit;
    }

