String getRestMethod(JMethod method) throws UnableToCompleteException {
        String restMethod = null;

        Annotation[] annotations = method.getAnnotations();
        for (Annotation annotation : annotations) {
            HttpMethod httpMethod = annotation.annotationType().getAnnotation(HttpMethod.class);
            // Check is HttpMethod
            if (null != httpMethod) {
                if (null != restMethod) {
                    // Error, see description of HttpMethod
                    getLogger().log(ERROR,
                        "Invalid method. It is an error for a method to be annotated with more than one annotation " +
                            "that is annotated with HttpMethod: " + method.getReadableDeclaration());
                    throw new UnableToCompleteException();
                }
                restMethod = httpMethod.value();
            }
        }

        if (null != restMethod) {
            // Allow custom methods later?
            restMethod = restMethod.toLowerCase();
            if (!REST_METHODS.contains(restMethod)) {
                getLogger().log(ERROR, "Invalid rest method. It must have a javax rs method annotation: " +
                    method.getReadableDeclaration());
                throw new UnableToCompleteException();
            }
        } else if (null != getAnnotation(method, JSONP.class)) {
            restMethod = METHOD_JSONP;
        } else {
            restMethod = method.getName();
            if (!REST_METHODS.contains(restMethod)) {
                getLogger().log(ERROR,
                    "Invalid rest method. It must either have a lower case rest method name or have a javax rs method" +
                        " annotation: " + method.getReadableDeclaration());
                throw new UnableToCompleteException();
            }
        }

        return restMethod;
    }

@SuppressWarnings({ "unchecked", "rawtypes" })
    private List<AnnotationResolver> getAnnotationResolvers(GeneratorContext context, TreeLogger logger) {
        java.lang.reflect.Method m;
        ArrayList args = new ArrayList();
        ArrayList types = new ArrayList();

        types.add(GeneratorContext.class);
        args.add(context);
        types.add(TreeLogger.class);
        args.add(logger);

        Object[] argValues = args.toArray();
        Class[] argtypes = (Class[]) types.toArray(new Class[argValues.length]);

        try {
            m = BINDING_DEFAULTS.getMethod("getAnnotationResolvers", argtypes);
        } catch (SecurityException e) {
            throw new RuntimeException("could not call method `getAnnotationResolvers´ on " + BINDING_DEFAULTS, e);
        } catch (NoSuchMethodException e) {
            throw new RuntimeException("could not resolve method `getAnnotationResolvers´ on " + BINDING_DEFAULTS, e);
        }

        List<AnnotationResolver> l;
        try {
            l = (List<AnnotationResolver>) m.invoke(null, context, logger);
        } catch (IllegalArgumentException e) {
            throw new RuntimeException("could not call method `getAnnotationResolvers´ on " + BINDING_DEFAULTS, e);
        } catch (IllegalAccessException e) {
            throw new RuntimeException("could not call method `getAnnotationResolvers´ on " + BINDING_DEFAULTS, e);
        } catch (InvocationTargetException e) {
            throw new RuntimeException("could not call method `getAnnotationResolvers´ on " + BINDING_DEFAULTS, e);
        }

        return l;
    }

public static Annotation[] getAnnotationsInTypeHierarchy(JClassType classType) {
        Set<Annotation> resultAnnotations = new HashSet<Annotation>();

        // Cache to avoid loops
        Set<JClassType> alreadyCheckedTypes = new HashSet<JClassType>();

        // Work queue
        Queue<JClassType> typeQueue = new LinkedList<JClassType>();

        for (JClassType current = classType; current != null; current = typeQueue.poll()) {
            if (!alreadyCheckedTypes.add(current)) {
                continue;
            }

            // Get the annotations only from current, no inherited
            Annotation[] annotations = current.getDeclaredAnnotations();
            Collections.addAll(resultAnnotations, annotations);

            if (current.getSuperclass() != null) {
                // Add the superclass to the queue
                typeQueue.add(current.getSuperclass());
            }

            // Add the Superinterfaces to the queue
            Collections.addAll(typeQueue, current.getImplementedInterfaces());
        }

        return resultAnnotations.toArray(new Annotation[resultAnnotations.size()]);
    }

@Override
    public FilterawareRequestCallback createCallback(Method method) {
        FilterawareRequestCallback retryingCallback =
            new RetryingFilterawareRequestCallback(method, gracePeriodMillis, numberOfRetries);

        for (CallbackFilter filter : callbackFilters) {
            retryingCallback.addFilter(filter);
        }
        return retryingCallback;
    }

@Override
    public RequestCallback filter(Method method, Response response, RequestCallback callback) {
        int code = response.getStatusCode();

        final CacheKey ck = cacheKey(method.builder);
        final List<RequestCallback> removedCallbacks = cache.removeCallbacks(ck);

        if (removedCallbacks != null) {
            callback = new RequestCallback() {
                @Override
                public void onResponseReceived(Request request, Response response) {
                    if (GWT.isClient() && LogConfiguration.loggingIsEnabled()) {
                        Logger.getLogger(CachingCallbackFilter.class.getName())
                            .finer("call " + removedCallbacks.size() + " more queued callbacks for " + ck);
                    }

                    // call all callbacks found in cache
                    for (RequestCallback cb : removedCallbacks) {
                        cb.onResponseReceived(request, response);
                    }
                }

                @Override
                public void onError(Request request, Throwable exception) {
                    if (LogConfiguration.loggingIsEnabled()) {
                        Logger.getLogger(CachingCallbackFilter.class.getName()).severe(
                            "cannot call " + (removedCallbacks.size() + 1) + " callbacks for " + ck +
                                " due to error: " + exception.getMessage());
                    }

                    if (LogConfiguration.loggingIsEnabled()) {
                        Logger.getLogger(CachingCallbackFilter.class.getName())
                            .finer("call " + removedCallbacks.size() + " more queued callbacks for " + ck);
                    }

                    // and all the others, found in cache
                    for (RequestCallback cb : removedCallbacks) {
                        cb.onError(request, exception);
                    }
                }
            };
        } else {
            if (GWT.isClient() && LogConfiguration.loggingIsEnabled()) {
                Logger.getLogger(CachingCallbackFilter.class.getName())
                    .finer("removed one or no " + "callback for cachekey " + ck);
            }
        }

        if (isCachingStatusCode(code)) {
            cacheResult(method, response);
            return callback;
        }

        if (GWT.isClient() && LogConfiguration.loggingIsEnabled()) {
            Logger.getLogger(CachingCallbackFilter.class.getName())
                .info("cannot cache due to invalid response code: " + code);
        }
        return callback;
    }

protected String[] getCacheDomains(Method method) {
        if (null == method.getData().get(Domain.CACHE_DOMAIN_KEY)) {
            return null;
        }

        JSONValue jsonValue = JSONParser.parseStrict(method.getData().get(Domain.CACHE_DOMAIN_KEY));
        if (null == jsonValue) {
            return null;
        }

        JSONArray jsonArray = jsonValue.isArray();
        if (null != jsonArray) {
            String[] dd = new String[jsonArray.size()];
            for (int i = 0; i < jsonArray.size(); ++i) {
                dd[i] = jsonArray.get(i).isString().stringValue();
            }

            return dd;
        }
        return null;
    }

@SuppressWarnings("rawtypes")
    private String[] getAnnotationsAsStringArray(Class[] classes) {
        if (null == classes) {
            return null;
        }

        List<String> ret = new ArrayList<String>();

        for (Class c : classes) {
            ret.add(c.getName());
        }

        return ret.toArray(new String[ret.size()]);
    }

private static String encodeAnnotationValue(Object value) {
        // Values of annotation elements must not be "null"
        if (null != value) {
            if (value instanceof String) {
                return readStringValue(value);
            } else if (value instanceof Number) {
                return readNumberValue(value);
            } else if (value.getClass().isArray()) {
                // workaround for ClassCastException: [Ljava.lang.Object; cannot be cast to [I
                // ignore empty arrays, because it becomes Object[]
                if (Array.getLength(value) > 0) {
                    return readArrayValue(value);
                }
                return null;
            } else if (value instanceof Annotation) {
                return getAnnotationAsString((Annotation) value);
            } else if (value instanceof Boolean) {
                return readBooleanValue((Boolean) value);
            } else if (value instanceof Class) {
                return readClassValue((Class) value);
            }
        }

        throw new IllegalArgumentException("Unsupported value for encodeAnnotationValue: " + value);
    }

