@CacheEntryRemoved
    public void removeIndex( final CacheEntryRemovedEvent<IndexedStorePath, IndexedStorePath> e )
    {
        if ( e.isPre() )
        {
            IndexedStorePath isp = e.getValue();
            final StoreKey key =
                    new StoreKey( isp.getPackageType(), isp.getStoreType(), isp.getStoreName() );
            // Only care about group level, as remote repo nfc is handled by remote timeout handler(see galley DownloadHandler),
            // and hosted is handled by DownloadManager
            if ( key.getType() == StoreType.group )
            {
                try
                {
                    final ArtifactStore store = storeDataManager.getArtifactStore( key );
                    final ConcreteResource r = new ConcreteResource( LocationUtils.toLocation( store ), isp.getPath() );
                    logger.debug( "Add NFC of resource {} in store {}", r, store );
                    if ( StoreType.hosted != key.getType() )
                    {
                        nfc.addMissing( r );
                    }
                }
                catch ( IndyDataException ex )
                {
                    logger.error( String.format(
                            "When add nfc missing for indexed artifact of path %s in store %s, failed to lookup store. Reason: %s",
                            isp.getPath(), key, ex.getMessage() ), ex );
                }
            }
        }
    }

public void onExpirationEvent( @Observes final SchedulerEvent event )
    {
        if ( !(event instanceof SchedulerTriggerEvent) || !event.getJobType()
                                                                         .equals( ScheduleManager.CONTENT_JOB_TYPE ) )
        {
            return;
        }

        ContentExpiration expiration;
        try
        {
            expiration = objectMapper.readValue( event.getPayload(), ContentExpiration.class );
        }
        catch ( final IOException e )
        {
            logger.error( "Failed to read ContentExpiration from event payload.", e );
            return;
        }

        final StoreKey key = expiration.getKey();
        final String path = expiration.getPath();
        try
        {
            ArtifactStore store = storeManager.getArtifactStore( key );
            if ( store == null )
            {
                logger.warn( "Store: {} is no longer available. Nothing to do for path: {}", key, path );
            }

            boolean deleted = store == null || contentManager.delete( store, path );

            if ( !deleted )
            {
                logger.error("Failed to delete Transfer for: {} in: {} (for content timeout).", path, key );
            }
            else
            {
                deleteExpiration( key, path );
            }
        }
        catch ( IndyWorkflowException e )
        {
            logger.error(
                    String.format( "Failed to retrieve Transfer for: %s in: %s (for content timeout). Reason: %s", path,
                                   key, e ), e );
        }
        catch ( IndyDataException e )
        {
            scheduleManager.deleteJob( scheduleManager.groupName( key, ScheduleManager.CONTENT_JOB_TYPE ), path );
            logger.error(
                    String.format( "Failed to retrieve ArtifactStore for: %s (for content timeout). Reason: %s", key, e ), e );
        }
    }

public void updateImpliedStores( @Observes final ArtifactStorePreUpdateEvent event )
    {
        if ( !storeManager.isStarted() )
        {
            return;
        }

        if ( !config.isEnabled() )
        {
            logger.debug( "Implied-repository processing is not enabled." );
            return;
        }

        try
        {
            // TODO: Update for changes map.
            final Map<StoreKey, ArtifactStore> currentStores = mapStores( event );

            for ( final ArtifactStore store : event )
            {
                logger.debug( "Processing store: {} for implied repo metadata", store );
                processStore( store, currentStores );
            }
        }
        catch ( Throwable error )
        {
            Logger logger = LoggerFactory.getLogger( getClass() );
            logger.error( String.format( "Implied-repository maintenance failed: %s", error.getMessage() ), error );
        }
    }

public static X509Certificate generateX509Certificate( KeyPair pair, String dn, int days, String algorithm )
                    throws GeneralSecurityException, IOException
    {
        PrivateKey privateKey = pair.getPrivate();
        X509CertInfo info = new X509CertInfo();
        Date from = new Date();
        Date to = new Date( from.getTime() + TimeUnit.DAYS.toMillis( days ) );
        CertificateValidity interval = new CertificateValidity( from, to );
        BigInteger sn = new BigInteger( 64, new SecureRandom() );
        X500Name owner = new X500Name( dn );

        info.set( X509CertInfo.VALIDITY, interval );
        info.set( X509CertInfo.SERIAL_NUMBER, new CertificateSerialNumber( sn ) );
        info.set( X509CertInfo.SUBJECT, owner );
        info.set( X509CertInfo.ISSUER, owner );
        info.set( X509CertInfo.KEY, new CertificateX509Key( pair.getPublic() ) );
        info.set( X509CertInfo.VERSION, new CertificateVersion( CertificateVersion.V3 ) );

        AlgorithmId algo = new AlgorithmId( AlgorithmId.sha256WithRSAEncryption_oid );
        info.set( X509CertInfo.ALGORITHM_ID, new CertificateAlgorithmId( algo ) );

        // Sign the cert to identify the algorithm that's used.
        X509CertImpl cert = new X509CertImpl( info );
        cert.sign( privateKey, algorithm );

        // Update the algorithm, and resign.
        algo = (AlgorithmId) cert.get( X509CertImpl.SIG_ALG );
        info.set( CertificateAlgorithmId.NAME + "." + CertificateAlgorithmId.ALGORITHM, algo );
        cert = new X509CertImpl( info );
        cert.sign( privateKey, algorithm );
        return cert;
    }

