@Measure( timers = @MetricNamed( DEFAULT ) )
    public void onStoreEnablementChange( @Observes ArtifactStoreEnablementEvent event )
    {
        if ( event.isPreprocessing() )
        {
            return;
        }

        for ( ArtifactStore store : event )
        {
            if ( ! event.isDisabling() )
            {
                try
                {
                    cancelReEnablementTimeout( store.getKey() );
                }
                catch ( IndySchedulerException e )
                {
                    Logger logger = LoggerFactory.getLogger( getClass() );
                    logger.error( String.format( "Failed to delete re-enablement job for %s.", store.getKey() ), e );
                }
            }
        }
    }

@Measure( timers = @MetricNamed( DEFAULT ) )
    public void onStoreError( @Observes IndyStoreErrorEvent evt )
    {
        Logger logger = LoggerFactory.getLogger( getClass() );
        StoreKey key = evt.getStoreKey();
        Throwable error = evt.getError();
        try
        {
            ArtifactStore store = storeDataManager.getArtifactStore( key );
            if ( store == null )
            {
                logger.warn( "Attempt to disable missing repo! Skipping." );
                return;
            }

            store = store.copyOf();

            int disableTimeout = store.getDisableTimeout();
            if ( disableTimeout <= TIMEOUT_NEVER_DISABLE )
            {
                logger.debug( "Disable-timeout set to {}, will never disable the repo", disableTimeout );
                store.setDisabled( false );
            }
            else
            {
                store.setDisabled( true );
                final ChangeSummary changeSummary = new ChangeSummary( ChangeSummary.SYSTEM_USER, String.format(
                        "Disabling %s due to error: %s\n\nStack Trace:\n  %s", key, error,
                        StringUtils.join( error.getStackTrace(), "\n  " ) ) );

                storeDataManager.storeArtifactStore( store, changeSummary, false, true, new EventMetadata() );

                logger.warn( "{} has been disabled due to store-level error: {}\n Will re-enable in {} seconds.", key,
                             error, disableTimeout == TIMEOUT_USE_DEFAULT ? config.getStoreDisableTimeoutSeconds() : disableTimeout );

                // TODO: How is it this doesn't duplicate the event handler method onStoreUpdate()...we're updating the store just above here.
                setReEnablementTimeout( key );
            }
        }
        catch ( IndyDataException e )
        {
            logger.error( String.format( "Failed to disable %s on error: %s", key, error ), e);
        }
        catch ( IndySchedulerException e )
        {
            logger.error( String.format( "Failed to schedule re-enablement of %s for retry.", key ), e );
        }
    }

private boolean checkValidity( final StoreKey key )
            throws IndyDataException
    {
        if ( catalog.isValidationEnabled( key ) )
        {
            try
            {
                final RemoteRepository validationRepo = catalog.createValidationRemote( key );
                if ( validationRepo == null )
                {
                    logger.info( "No validation repository was created: assuming {} is valid.", key );
                    return true;
                }

                String path = catalog.getRemoteValidationPath( key );
                if ( path == null )
                {
                    path = PathUtils.ROOT;
                }

                logger.debug( "\n\n\n\n\n[AutoProx] Checking path: {} under remote URL: {}", path, validationRepo.getUrl() );
                boolean result = false;
                try
                {
                    result = transferManager.exists(
                            new ConcreteResource( LocationUtils.toLocation( validationRepo ), path ) );
                }
                catch ( final TransferException e )
                {
                    logger.warn( "[AutoProx] Cannot connect to target repository: '{}'. Reason: {}", validationRepo, e.getMessage() );
                    logger.debug( "[AutoProx] exception from validation attempt for: " + validationRepo, e );
                }

                logger.debug( "Validation result for: {} is: {}", validationRepo, result );

                return result;
            }
            catch ( final AutoProxRuleException e )
            {
                throw new IndyDataException(
                        "[AUTOPROX] Failed to create new group from factory matching: '%s'. Reason: %s", e, key,
                        e.getMessage() );
            }
        }

        return true;
    }

private ProxyCreationResult createRepo( String trackingId, URL url, String name )
                    throws IndyDataException
    {
        UrlInfo info = new UrlInfo( url.toExternalForm() );

        UserPass up = UserPass.parse( ApplicationHeader.authorization, httpRequest, url.getAuthority() );
        String baseUrl = getBaseUrl( url, false );

        logger.debug( ">>>> Create repo: trackingId=" + trackingId + ", name=" + name );
        ProxyCreationResult result = repoCreator.create( trackingId, name, baseUrl, info, up,
                                                         LoggerFactory.getLogger( repoCreator.getClass() ) );
        ChangeSummary changeSummary =
                        new ChangeSummary( ChangeSummary.SYSTEM_USER, "Creating HTTProx proxy for: " + info.getUrl() );

        RemoteRepository remote = result.getRemote();
        if ( remote != null )
        {
            storeManager.storeArtifactStore( remote, changeSummary, false, true, new EventMetadata() );
        }

        HostedRepository hosted = result.getHosted();
        if ( hosted != null )
        {
            storeManager.storeArtifactStore( hosted, changeSummary, false, true, new EventMetadata() );
        }

        Group group = result.getGroup();
        if ( group != null )
        {
            storeManager.storeArtifactStore( group, changeSummary, false, true, new EventMetadata() );
        }

        return result;
    }

private String getRemoteRepositoryName( URL url ) throws IndyDataException
    {
        final String name = repoCreator.formatId( url.getHost(), getPort( url ), 0, null, StoreType.remote );

        logger.debug( "Looking for remote repo starts with name: {}", name );

        AbstractProxyRepositoryCreator abstractProxyRepositoryCreator = null;
        if ( repoCreator instanceof AbstractProxyRepositoryCreator )
        {
            abstractProxyRepositoryCreator = (AbstractProxyRepositoryCreator) repoCreator;
        }

        if ( abstractProxyRepositoryCreator == null )
        {
            return name;
        }

        Predicate<ArtifactStore> filter = abstractProxyRepositoryCreator.getNameFilter( name );
        List<String> l = storeManager.query()
                                     .packageType( GENERIC_PKG_KEY )
                                     .storeType( RemoteRepository.class )
                                     .stream( filter )
                                     .map( repository -> repository.getName() )
                                     .collect( Collectors.toList() );

        if ( l.isEmpty() )
        {
            return name;
        }
        return abstractProxyRepositoryCreator.getNextName( l );
    }

public Predicate<ArtifactStore> getNameFilter( String name )
    {
        return store -> store.getName().startsWith( name );
    }

public String getNextName( List<String> names )
    {
        if ( names.isEmpty() )
        {
            return null;
        }
        String name0 = names.get( 0 );
        if ( names.size() == 1 )
        {
            return name0 + "_1";
        }
        Collections.sort( names );
        String last = names.get( names.size() - 1 );
        String index = last.substring( last.lastIndexOf( "_" ) + 1 );
        return name0 + "_" + ( Integer.parseInt( index ) + 1 );
    }

