private void clearStoreNFC( final Set<String> sourcePaths, ArtifactStore store )
            throws IndyDataException
    {
        Set<String> paths = sourcePaths.stream()
                                       .map( sp -> sp.startsWith( "/" ) && sp.length() > 1 ? sp.substring( 1 ) : sp )
                                       .collect( Collectors.toSet() );

        paths.forEach( path -> {
            ConcreteResource resource = new ConcreteResource( LocationUtils.toLocation( store ), path );

            logger.debug( "Clearing NFC path: {} from: {}\n\tResource: {}", path, store.getKey(), resource );
            nfc.clearMissing( resource );
        } );

        Set<Group> groups = storeManager.query().getGroupsAffectedBy( store.getKey() );
        if ( groups != null )
        {
            groups.forEach( group -> paths.forEach( path -> {
                ConcreteResource resource = new ConcreteResource( LocationUtils.toLocation( group ), path );

                logger.debug( "Clearing NFC path: {} from: {}\n\tResource: {}", path, group.getKey(), resource );
                nfc.clearMissing( resource );
            } ) );
        }
    }

public static boolean checkListingMask( final ArtifactStore store, final String path )
    {
        Set<String> maskPatterns = store.getPathMaskPatterns();

        logger.trace( "Checking mask in: {}", store.getKey() );
        logger.trace( "Mask patterns in {}: {}", store.getName(), maskPatterns );

        if (maskPatterns == null || maskPatterns.isEmpty())
        {
            logger.trace( "Checking mask in: {}, - NO PATTERNS", store.getName() );
            return true;
        }

        for ( String pattern : maskPatterns )
        {
            if ( isRegexPattern( pattern ) )
            {
                // if there is a regexp pattern we cannot check presence of directory listing, because we would have to
                // check only the beginning of the regexp and that's impossible, so we have to assume that the path is
                // present
                return true;
            }
        }

        for ( String pattern : maskPatterns )
        {
            if ( path.startsWith( pattern ) || pattern.startsWith( path ) )
            {
                logger.trace( "Checking mask in: {}, pattern: {} - MATCH", store.getName(), pattern );
                return true;
            }
        }

        logger.debug( "Listing for path {} not enabled by path mask {} of repo {}", path, maskPatterns, store.getKey() );

        return false;
    }

@Override
    public <T extends Location> List<Location> expand( final Collection<T> locations )
        throws TransferException
    {
        final List<Location> result = new ArrayList<Location>();
        for ( final Location location : locations )
        {
            if ( location instanceof GroupLocation )
            {
                final GroupLocation gl = (GroupLocation) location;
                try
                {
                    logger.debug( "Expanding group: {}", gl.getKey() );
                    final List<ArtifactStore> members =
                            data.query().packageType( gl.getKey().getPackageType() ).getOrderedConcreteStoresInGroup( gl.getKey().getName() );

                    if ( members != null )
                    {
                        for ( final ArtifactStore member : members )
                        {
                            if ( !result.contains( member ) )
                            {
                                logger.debug( "expansion += {}", member.getKey() );
                                result.add( LocationUtils.toLocation( member ) );
                            }
                        }
                        logger.debug( "Expanded group: {} to:\n  {}", gl.getKey(), new JoinString( "\n  ", result ) );
                    }
                }
                catch ( final IndyDataException e )
                {
                    throw new TransferException(
                                                 "Failed to lookup ordered concrete artifact stores contained in group: {}. Reason: {}",
                                                 e, gl, e.getMessage() );
                }
            }
            else if ( location instanceof CacheOnlyLocation && !( (CacheOnlyLocation) location ).isHostedRepository() )
            {
                final StoreKey key = ( (KeyedLocation) location ).getKey();
                try
                {
                    final ArtifactStore store = data.getArtifactStore( key );

                    if ( store == null )
                    {
                        throw new TransferException( "Cannot find ArtifactStore to match key: %s.", key );
                    }

                    logger.debug( "Adding single store: {} for location: {}", store, location );
                    result.add( LocationUtils.toLocation( store ) );
                }
                catch ( final IndyDataException e )
                {
                    throw new TransferException( "Failed to lookup store for key: {}. Reason: {}", e, key,
                                                 e.getMessage() );
                }
            }
            else
            {
                logger.debug( "No expansion available for location: {}", location );
                result.add( location );
            }
        }

        return result;
    }

@Override
    public VirtualResource expand( final Resource resource )
        throws TransferException
    {
        List<Location> locations;
        if ( resource instanceof VirtualResource )
        {
            final List<ConcreteResource> concrete = ( (VirtualResource) resource ).toConcreteResources();
            final List<ConcreteResource> result = new ArrayList<ConcreteResource>();
            for ( final ConcreteResource cr : concrete )
            {
                final List<Location> expanded = expand( cr.getLocation() );
                for ( final Location location : expanded )
                {
                    result.add( new ConcreteResource( location, cr.getPath() ) );
                }
            }

            return new VirtualResource( result );
        }
        else
        {
            final ConcreteResource cr = (ConcreteResource) resource;
            locations = expand( cr.getLocation() );

            return new VirtualResource( locations, cr.getPath() );
        }
    }

private Metadata generateGroupMetadata( final Group group, final List<ArtifactStore> members,
                                            final List<StoreKey> contributingMembers, final String path )
            throws IndyWorkflowException
    {

        if ( !canProcess( path ) )
        {
            logger.error( "The path is not a metadata file: {} ", path );
            return null;
        }

        String toMergePath = path;
        if ( !path.endsWith( MavenMetadataMerger.METADATA_NAME ) )
        {
            toMergePath = normalize( normalize( parentPath( toMergePath ) ), MavenMetadataMerger.METADATA_NAME );
        }

        Metadata meta = getMetaFromCache( group.getKey(), toMergePath );

        if ( meta != null )
        {
            return meta;
        }

        Metadata master = new Metadata();
        master.setVersioning( new Versioning() );

        MetadataIncrementalResult incrementalResult =
                new MetadataIncrementalResult( new HashSet<>( members ), Collections.emptySet(), master );

        incrementalResult = mergeMissing( group, incrementalResult, toMergePath, "cached", this::retrieveCached );

        contributingMembers.addAll( incrementalResult.merged );

        incrementalResult = mergeMissing( group, incrementalResult, toMergePath, "downloaded", this::downloadMissing );

        contributingMembers.addAll( incrementalResult.merged );

        incrementalResult = mergeMissing( group, incrementalResult, toMergePath, "generated", this::generateMissing );

        contributingMembers.addAll( incrementalResult.merged );

        if ( metadataProviders != null )
        {
            master = mergeProviderMetadata( group, incrementalResult.result, toMergePath );
        }
        else
        {
            master = incrementalResult.result;
        }

        if ( !incrementalResult.missing.isEmpty() )
        {
            logger.warn(
                    "After download and generation attempts, metadata is still missing from the following stores: {}",
                    incrementalResult.missing );
        }

        List<String> versions = master.getVersioning().getVersions();
        if ( versions != null && !versions.isEmpty() )
        {
            merger.sortVersions( master );
            return master;
        }

        List<Plugin> plugins = master.getPlugins();
        if ( plugins != null && !plugins.isEmpty() )
        {
            return master;
        }

        logger.error( "The group metadata generation is not successful for path: {} in group: {}", path, group );
        return null;
    }

