@Nonnull
  public PSSchema readSchema () throws SchematronReadException
  {
    // Resolve all includes as the first action
    final SAXReaderSettings aSettings = new SAXReaderSettings ().setEntityResolver (m_aEntityResolver);

    final IMicroDocument aDoc = SchematronHelper.getWithResolvedSchematronIncludes (m_aResource,
                                                                                    aSettings,
                                                                                    m_aErrorHandler);
    if (aDoc == null || aDoc.getDocumentElement () == null)
      throw new SchematronReadException (m_aResource,
                                         "Failed to resolve includes in Schematron resource " + m_aResource);

    if (SchematronDebug.isShowResolvedSourceSchematron ())
      LOGGER.info ("Resolved source Schematron:\n" + MicroWriter.getNodeAsString (aDoc));

    return readSchemaFromXML (aDoc.getDocumentElement ());
  }

@Nonnull
  public static TransformerFactory createTransformerFactorySaxonFirst (@Nullable final ClassLoader aClassLoader,
                                                                       @Nullable final ErrorListener aErrorListener,
                                                                       @Nullable final URIResolver aURIResolver)
  {
    TransformerFactory aFactory;
    try
    {
      // Try Saxon first
      final ClassLoader aEffectiveClassLoader = aClassLoader != null ? aClassLoader
                                                                     : ClassLoaderHelper.getContextClassLoader ();
      aFactory = TransformerFactory.newInstance (SAXON_TRANSFORMER_FACTORY_CLASS, aEffectiveClassLoader);

      // Debug/testing only
      if (false)
        aFactory.setFeature (FeatureKeys.TRACE_OPTIMIZER_DECISIONS, true);
      if (false)
        aFactory.setFeature (FeatureKeys.COMPILE_WITH_TRACING, true);
      if (false)
        aFactory.setAttribute (FeatureKeys.XSLT_VERSION, "2.0");
    }
    catch (final TransformerFactoryConfigurationError | TransformerConfigurationException ex)
    {
      try
      {
        // Try default afterwards
        aFactory = TransformerFactory.newInstance ();
      }
      catch (final TransformerFactoryConfigurationError ex2)
      {
        throw new InitializationException ("Failed to create XML TransformerFactory", ex2);
      }
    }

    if (aErrorListener != null)
      aFactory.setErrorListener (aErrorListener);
    if (aURIResolver != null)
      aFactory.setURIResolver (aURIResolver);
    return aFactory;
  }

@Nonnull
  @ReturnsMutableCopy
  public static MapBasedNamespaceContext createNamespaceMapping (@Nonnull final PSSchema aSchema)
  {
    final MapBasedNamespaceContext ret = new MapBasedNamespaceContext ();
    ret.addDefaultNamespaceURI (CSchematron.NAMESPACE_SCHEMATRON);
    for (final PSNS aItem : aSchema.getAllNSs ())
      ret.addMapping (aItem.getPrefix (), aItem.getUri ());
    return ret;
  }

protected <C extends DeadboltHandler> DeadboltHandler getDeadboltHandler(final String handlerKey)
    {
        LOGGER.debug("Getting Deadbolt handler with key [{}]",
                     handlerKey);
        return handlerKey == null || Constants.DEFAULT_HANDLER_KEY.equals(handlerKey) ? handlerCache.get()
                                                                                       : handlerCache.apply(handlerKey);
    }

protected CompletionStage<Result> onAuthFailure(final DeadboltHandler deadboltHandler,
                                                    final Optional<String> content,
                                                    final Http.RequestHeader request)
    {
        LOGGER.info("Deadbolt: Access failure on [{}]",
                    request.uri());

        CompletionStage<Result> result;
        try
        {
            result = deadboltHandler.onAuthFailure(request,
                                                   content);
        }
        catch (Exception e)
        {
            LOGGER.warn("Deadbolt: Exception when invoking onAuthFailure",
                        e);
            result = CompletableFuture.completedFuture(Results.internalServerError());
        }
        return result;
    }

private Http.RequestHeader markAsAuthorised(final Http.RequestHeader request)
    {
        this.authorised = true;
        return request.addAttr(ACTION_AUTHORISED,
                     true);
    }

protected static boolean isAuthorised(final Http.RequestHeader request)
    {
        return request.attrs().getOptional(ACTION_AUTHORISED).orElse(false);
    }

protected Http.RequestHeader defer(final Http.RequestHeader request,
                         final AbstractDeadboltAction<T> action)
    {
        if (action != null)
        {
            LOGGER.info("Deferring action [{}]",
                        this.getClass().getName());
            return request.addAttr(ACTION_DEFERRED,
                         action);
        }
        return request;
    }

@SuppressWarnings("unchecked")
    public F.Tuple<AbstractDeadboltAction<?>, Http.RequestHeader> getDeferredAction(final Http.RequestHeader request)
    {
        return request.attrs().getOptional(ACTION_DEFERRED).map(action -> {
            action.delegate = this;
            return F.<AbstractDeadboltAction<?>, Http.RequestHeader>Tuple(action, request.removeAttr(ACTION_DEFERRED).addAttr(IGNORE_DEFERRED_FLAG, true));
        }).orElseGet(() -> F.Tuple(null, request));
    }

protected CompletionStage<Result> authorizeAndExecute(final Http.RequestHeader request)
    {
        if(constraintAnnotationMode != ConstraintAnnotationMode.AND)
        {
            // In AND mode we don't mark an action as authorised because we want ALL (remaining) constraints to be evaluated as well!
            return delegate.call((Http.Request)markAsAuthorised(request));
        }
        return delegate.call((Http.Request)request);
    }

protected CompletionStage<Result> unauthorizeAndFail(final Http.RequestHeader request,
                                                         final DeadboltHandler handler,
                                                         final Optional<String> content)
    {
        if(constraintAnnotationMode == ConstraintAnnotationMode.OR && deadboltActionLeftInActionChain(this))
        {
            // In OR mode we don't fail immediately but also check remaining constraints (it there is any left). Maybe one of these next ones authorizes...
            return delegate.call((Http.Request)request);
        }

        return onAuthFailure(handler,
                             content,
                             request);
    }

private static boolean deadboltActionLeftInActionChain(final Action<?> action) {
        if(action != null) {
            if(action.delegate instanceof AbstractDeadboltAction) {
                return true; // yes, there is at least one deadbolt action remaining
            }
            // action.delegate wasn't a deadbolt action, let's check the next one in the chain
            return deadboltActionLeftInActionChain(action.delegate);
        }
        return false;
    }

private static boolean isConstraintInActionChain(final Action<?> action, final Function<Action<?>, Action<?>> nextAction) {
        if(action != null) {
            if(action instanceof AbstractDeadboltAction &&
                    !(action instanceof BeforeAccessAction) &&
                    !(action instanceof DeferredDeadboltAction)) {
                return true;
            }
            // that wasn't a deadbolt constraint, let's go and check the next action in the chain
            return isConstraintInActionChain(nextAction.apply(action), nextAction);
        }
        return false;
    }

@Override
    public CompletionStage<Result> apply(final Function<Http.RequestHeader, CompletionStage<Result>> next,
                                         final Http.RequestHeader requestHeader)
    {
        final Optional<AuthorizedRoute> maybeAuthRoute = authorizedRoutes.apply(requestHeader.method(),
                                                                                requestHeader.attrs().get(Router.Attrs.HANDLER_DEF).path());
        return maybeAuthRoute.map(authRoute -> authRoute.constraint().apply(requestHeader,
                                                                            authRoute.handler().orElse(handler),
                                                                            next)
        ).orElseGet(() -> next.apply(requestHeader));
    }

public List<String> getRoleNames(final Optional<? extends Subject> subjectOption)
    {
        final List<String> roleNames = new ArrayList<>();
        subjectOption.ifPresent(subject ->
                                {
                                    final List<? extends Role> roles = subject.getRoles();
                                    if (roles != null)
                                    {
                                        roleNames.addAll(roles.stream()
                                                              .filter(Objects::nonNull)
                                                              .map(Role::getName)
                                                              .collect(Collectors.toList()));
                                    }
                                });

        return roleNames;
    }

public boolean hasRole(final Optional<? extends Subject> subjectOption,
                           final String roleName)
    {
        return getRoleNames(subjectOption).contains(roleName);
    }

public boolean hasAllRoles(final Optional<? extends Subject> subjectOption,
                               final String[] roleNames)
    {
        final List<String> heldRoles = getRoleNames(subjectOption);

        boolean roleCheckResult = roleNames != null && roleNames.length > 0;
        for (int i = 0; roleCheckResult && i < roleNames.length; i++)
        {
            boolean invert = false;
            String roleName = roleNames[i];
            if (roleName.startsWith("!"))
            {
                invert = true;
                roleName = roleName.substring(1);
            }
            roleCheckResult = heldRoles.contains(roleName);

            if (invert)
            {
                roleCheckResult = !roleCheckResult;
            }
        }
        return roleCheckResult;
    }

@Override
    public CompletionStage<Result> apply(final Function<Http.RequestHeader, CompletionStage<Result>> next,
                                         final Http.RequestHeader requestHeader)
    {
        final HandlerDef handlerDef = requestHeader.attrs().get(Router.Attrs.HANDLER_DEF);
        final List<String> deadboltModifierTags = handlerDef.getModifiers().stream().filter(mt -> mt != null && mt.startsWith("deadbolt:")).collect(Collectors.toList());
        return processModifierTags(deadboltModifierTags, 0, requestHeader, next);
    }

public FilterFunction subjectPresent(final Optional<String> content)
    {
        return (Http.RequestHeader requestHeader,
                DeadboltHandler handler,
                Function<Http.RequestHeader, CompletionStage<Result>> next) ->
                beforeAuthCheckCache.apply(handler, requestHeader, content)
                       .thenCompose(maybePreAuth -> maybePreAuth._1.map(preAuthResult -> (CompletionStage<Result>) CompletableFuture.completedFuture(preAuthResult))
                                                                .orElseGet(() -> constraintLogic.subjectPresent(maybePreAuth._2,
                                                                                                                handler,
                                                                                                                content,
                                                                                                                (rh, hdlr, cntent) -> next.apply(rh),
                                                                                                                (rh, hdlr, cntent) -> hdlr.onAuthFailure(rh,
                                                                                                                                                          cntent),
                                                                                                                ConstraintPoint.FILTER)));
    }

public FilterFunction pattern(final String value,
                                  final PatternType patternType)
    {
        return pattern(value,
                       patternType,
                       Optional.empty());
    }

public FilterFunction pattern(final String value,
                                  final PatternType patternType,
                                  final Optional<String> meta)
    {
        return pattern(value,
                       patternType,
                       meta,
                       false,
                       Optional.empty());
    }

public FilterFunction dynamic(final String name,
                                  final Optional<String> meta)
