public static <T> Collector<T, List<T>, T> singletonCollector() {
        return Collector.of(
                ArrayList::new,
                List::add,
                (left, right) -> {
                    left.addAll(right);
                    return left;
                },
                list -> {
                    if (list.size() == 0) {
                        return null;
                    }
                    if (list.size() > 1) {
                        throw new IllegalStateException();
                    }
                    return list.get(0);
                }
        );
    }

public static <T> Collector<Collection<T>, List<T>, List<T>> toFlatList() {
        return Collector.of(
                ArrayList::new,
                List::addAll,
                (left, right) -> {
                    left.addAll(right);
                    return left;
                });
    }

