public static String generateTimestamp(boolean generationEnabled, Date dateInstant) {
        if(!generationEnabled)
            return null;

        Calendar instant = new Calendar.Builder().
                setInstant(dateInstant)
                .setTimeZone(TimeZone.getTimeZone("UTC"))
                .build();


        return String.format("t%d%02d%02d-%02d%02d%02d-%03d", instant.get(Calendar.YEAR), instant.get(Calendar.MONTH) + 1,
                instant.get(Calendar.DAY_OF_MONTH), instant.get(Calendar.HOUR_OF_DAY), instant.get(Calendar.MINUTE),
                instant.get(Calendar.SECOND), instant.get(Calendar.MILLISECOND));
    }

public synchronized boolean addReadyTask(BuildTask task) {
        if (!task.readyToBuild()) {
            throw new IllegalArgumentException("a not ready task added to the queue: " + task);
        }
        unfinishedTasks.add(task);
        log.debug("adding task: {}", task);
        readyTasks.add(task);
        return true;
    }

public synchronized void addWaitingTask(BuildTask task, Runnable taskReadyCallback) {
        unfinishedTasks.add(task);
        log.debug("adding waiting task: {}", task);
        waitingTasksWithCallbacks.put(task, taskReadyCallback);
    }

public synchronized void removeTask(BuildTask task) {
        log.debug("removing task: {}", task);
        if (tasksInProgress.remove(task)) {
            availableBuildSlots.release();
        }
        if (readyTasks.remove(task)) {
            log.debug("The task {} has been removed from readyTasks.", task);
        }

        if (waitingTasksWithCallbacks.remove(task) != null) {
            log.debug("The task {} has been removed from waitingTasks.", task);
        }

        if (unfinishedTasks.remove(task)) {
            log.debug("The task {} has been removed from unfinishedTasks.", task);
        }
    }

public synchronized void executeNewReadyTasks() {
        List<BuildTask> newReadyTasks = extractReadyTasks();
        log.debug("starting new ready tasks. New ready tasks: {}", newReadyTasks);
        readyTasks.addAll(newReadyTasks);
    }

public synchronized Optional<BuildTask> getTask(BuildConfigurationAudited buildConfigAudited) {
        Optional<BuildTask> ready = readyTasks.stream().filter(bt -> bt.getBuildConfigurationAudited().equals(buildConfigAudited)).findAny();
        Optional<BuildTask> waiting = waitingTasksWithCallbacks.keySet().stream().filter(bt -> bt.getBuildConfigurationAudited().equals(buildConfigAudited)).findAny();
        Optional<BuildTask> inProgress = tasksInProgress.stream().filter(bt -> bt.getBuildConfigurationAudited().equals(buildConfigAudited)).findAny();
        return ready.isPresent() ? ready : waiting.isPresent() ? waiting : inProgress;
    }

static boolean isTrusted(String artifactOriginUrl, TargetRepository targetRepository) {
        if (targetRepository.temporaryRepo) {
            return false;
        }
        if (artifactOriginUrl == null || artifactOriginUrl.isEmpty()) {
            return false;
        }
        for (String trustedRepoUrl : TRUSTED_REPOSITORY_URLS) {
            if (artifactOriginUrl.startsWith(trustedRepoUrl)) {
                return true;
            }
        }
        return false;
    }

public RunningTask monitor(Runnable onMonitorComplete, Consumer<Exception> onMonitorError, Supplier<Boolean> condition, int checkInterval, int timeout, TimeUnit timeUnit) {

        ObjectWrapper<RunningTask> runningTaskReference = new ObjectWrapper<>();
        Runnable monitor = () -> {
            RunningTask runningTask = runningTaskReference.get();

            if (runningTask == null) {
                /* There might be a situation where this runnable is called before runningTaskReference is set with the
                 * running task since this runnable is scheduled to run before runningTaskReference is set. In that
                 * case, we just skip this runnable and re-run on the next scheduled interval with the assumption that
                 * runningTaskReference will be set before the next re-run
                 */
                log.debug("runningTask not set yet inside the 'monitor' runnable! Skipping!");
                return;
            }
            try {
                // Check if given condition is satisfied
                if (condition.get()) {
                    runningTasks.remove(runningTask);
                    runningTask.cancel();
                    onMonitorComplete.run();
                }
            } catch (Exception e) {
                log.error("Exception in monitor runnable", e);
                runningTasks.remove(runningTask);
                runningTask.cancel();
                onMonitorError.accept(e);
            }
        };
        ScheduledFuture<?> future = executorService.scheduleWithFixedDelay(monitor, 0L, checkInterval, timeUnit);
        Consumer<RunningTask> onTimeout = (runningTask) -> {
            runningTasks.remove(runningTask);
            onMonitorError.accept(new MonitorException("Service was not ready in: " + timeout + " " + timeUnit.toString()));
        }

