static Date parse(String date, String pattern, String... patterns) {
		Set<String> set = new HashSet<>();
		set.add(pattern);
		if (patterns != null) {
			addAll(set, patterns);
		}

		for (String p : set) {
			try {
				return df(p).parse(date);
			}
			catch (ParseException ex) {
				// Skip pattern
			}
		}

		return null;
	}

