public synchronized boolean register(EventHandler handler)
	{
		boolean result = handlers.add(handler);
		handlersByEvent.clear();
		return result;
	}

@Override
	public void run()
	{
		System.out.println("Event monitor starting...");

		while(!shouldShutDown)
		{
			try
			{
				synchronized (eventQueue)
				{
					if (eventQueue.isEmpty())
					{
						eventQueue.wait(delay);		// Support wake-up via eventQueue.notify()
					}
				}
			}
			catch (InterruptedException e)
			{
				e.printStackTrace();
				System.err.println("Interrupted (use shutdown() to terminate).  Continuing...");
				continue;
			}

			Object event = null;

			while ((event = eventQueue.poll()) != null)
			{
				processEvent(event);
			}
		}

		System.out.println("Event monitor exiting...");
		clearAllHandlers();
	}

private void processEvent(final Object event)
    {
	    System.out.println("Processing event: " + event.toString());
	    for (final EventHandler handler : getConsumersFor(event.getClass()))
	    {
    		EVENT_EXECUTOR.execute(new Runnable(){
				@Override
                public void run()
                {
			    	try
			    	{
			    		handler.handle(event);
			    	}
			    	catch(Exception e)
			    	{
			    		e.printStackTrace();

			    		if (shouldReRaiseOnError)
			    		{
			    			System.out.println("Event handler failed. Re-publishing event: " + event.toString());
			    			eventQueue.publish(event);
			    		}
			    	}
                }
    		});
	    }
    }

private boolean addEventBus(String name, EventBus bus)
	{
		if (!eventBusses.containsKey(name))
		{
			eventBusses.put(name, bus);
			return true;
		}

		return false;
	}

private void publishEvent(Object event)
	{
		assert(hasEventBusses());

		for (EventBus eventBus : eventBusses.values())
		{
			eventBus.publish(event);
		}
	}

private void publishEvent(String name, Object event)
	{
		assert(hasEventBusses());
		EventBus eventBus = getEventBus(name);

		if (eventBus == null)
		{
			throw new RuntimeException("Unknown event bus name: " + name);
		}

		eventBus.publish(event);
	}

public void setPadding(final PaddingTop paddingTop,
            final PaddingRight paddingRight, final PaddingBottom paddingBottom,
            final PaddingLeft paddingLeft) {

        if (paddingTop != null && paddingRight != null && paddingBottom != null
                && paddingLeft != null) {

            if (PaddingTop.INITIAL.equals(paddingTop.getCssValue())
                    || PaddingTop.INHERIT.equals(paddingTop.getCssValue())
                    || PaddingRight.INITIAL.equals(paddingRight.getCssValue())
                    || PaddingRight.INHERIT.equals(paddingRight.getCssValue())
                    || PaddingBottom.INITIAL.equals(paddingBottom.getCssValue())
                    || PaddingBottom.INHERIT.equals(paddingBottom.getCssValue())
                    || PaddingLeft.INITIAL.equals(paddingLeft.getCssValue())
                    || PaddingLeft.INHERIT.equals(paddingLeft.getCssValue())) {
                throw new InvalidValueException(
                        "Any or all of the given arguments have initial/inherit constant value as its cssValue");
            }

            try {
                final PaddingTop paddingTopTemp;
                final PaddingRight paddingRightTemp;
                final PaddingBottom paddingBottomTemp;
                final PaddingLeft paddingLeftTemp;

                if (this.paddingTop != null) {
                    this.paddingTop.setAlreadyInUse(false);
                    this.paddingRight.setAlreadyInUse(false);
                    this.paddingBottom.setAlreadyInUse(false);
                    this.paddingLeft.setAlreadyInUse(false);
                }

                if (paddingTop.isAlreadyInUse()
                        && this.paddingTop != paddingTop) {
                    if (this.paddingTop != null) {
                        paddingTopTemp = this.paddingTop
                                .setCssValue(paddingTop.getCssValue());
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingTop is already used by another object so the existing object is used");
                        }
                    } else {
                        paddingTopTemp = paddingTop.clone();
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingTop is already used by another object so its clone is assigned");
                        }
                    }
                } else {
                    paddingTopTemp = paddingTop;
                }

                if (paddingRight.isAlreadyInUse()
                        && this.paddingRight != paddingRight) {
                    if (this.paddingRight != null) {
                        paddingRightTemp = this.paddingRight
                                .setCssValue(paddingTop.getCssValue());
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingRight is already used by another object so the existing object is used");
                        }
                    } else {
                        paddingRightTemp = paddingRight.clone();
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingRight is already used by another object so its clone is assigned");
                        }
                    }

                } else {
                    paddingRightTemp = paddingRight;
                }

                if (paddingBottom.isAlreadyInUse()
                        && this.paddingBottom != paddingBottom) {
                    if (this.paddingBottom != null) {
                        paddingBottomTemp = this.paddingBottom
                                .setCssValue(paddingTop.getCssValue());
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingBottom is already used by another object so the existing object is used");
                        }
                    } else {
                        paddingBottomTemp = paddingBottom.clone();
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingBottom is already used by another object so its clone is assigned");
                        }
                    }

                } else {
                    paddingBottomTemp = paddingBottom;
                }

                if (paddingLeft.isAlreadyInUse()
                        && this.paddingLeft != paddingLeft) {
                    if (this.paddingLeft != null) {
                        paddingLeftTemp = this.paddingLeft
                                .setCssValue(paddingTop.getCssValue());
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingLeft is already used by another object so the existing object is used");
                        }
                    } else {
                        paddingLeftTemp = paddingLeft.clone();
                        if (LOGGER.isLoggable(Level.WARNING)) {
                            LOGGER.warning(
                                    "the given paddingLeft is already used by another object so its clone is assigned");
                        }
                    }

                } else {
                    paddingLeftTemp = paddingLeft;
                }

                paddingTopTemp.setAlreadyInUse(true);
                paddingTopTemp.setStateChangeInformer(this);

                paddingRightTemp.setAlreadyInUse(true);
                paddingRightTemp.setStateChangeInformer(this);

                paddingBottomTemp.setAlreadyInUse(true);
                paddingBottomTemp.setStateChangeInformer(this);

                paddingLeftTemp.setAlreadyInUse(true);
                paddingLeftTemp.setStateChangeInformer(this);

                assignProducedCssValue(paddingTop, paddingRight, paddingBottom,
                        paddingLeft);

                this.paddingTop = paddingTopTemp;
                this.paddingRight = paddingRightTemp;
                this.paddingBottom = paddingBottomTemp;
                this.paddingLeft = paddingLeftTemp;

            } catch (final CloneNotSupportedException e) {
                throw new InvalidValueException(e);
            } catch (final Exception e) {
                throw new InvalidValueException(e);
            }

        } else {
            throw new NullValueException("cannot accept null arguments");
        }

    }

@Override
    public void stateChanged(final CssProperty stateChangedObject) {

        if (stateChangedObject instanceof PaddingTop) {
            final PaddingTop paddingTop = (PaddingTop) stateChangedObject;
            if (PaddingTop.INITIAL.equals(paddingTop.getCssValue())
                    || PaddingTop.INHERIT.equals(paddingTop.getCssValue())) {
                throw new InvalidValueException(
                        "paddingTop cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof PaddingRight) {
            final PaddingRight paddingRight = (PaddingRight) stateChangedObject;
            if (PaddingRight.INITIAL.equals(paddingRight.getCssValue())
                    || PaddingRight.INHERIT
                            .equals(paddingRight.getCssValue())) {
                throw new InvalidValueException(
                        "paddingRight cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof PaddingBottom) {
            final PaddingBottom paddingBottom = (PaddingBottom) stateChangedObject;
            if (PaddingBottom.INITIAL.equals(paddingBottom.getCssValue())
                    || PaddingBottom.INHERIT
                            .equals(paddingBottom.getCssValue())) {
                throw new InvalidValueException(
                        "paddingBottom cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof PaddingLeft) {
            final PaddingLeft paddingLeft = (PaddingLeft) stateChangedObject;
            if (PaddingLeft.INITIAL.equals(paddingLeft.getCssValue())
                    || PaddingLeft.INHERIT.equals(paddingLeft.getCssValue())) {
                throw new InvalidValueException(
                        "paddingLeft cannot have initial/inherit as its cssValue");
            }
        }

        assignProducedCssValue(paddingTop, paddingRight, paddingBottom,
                paddingLeft);

    }

public static List<String> split(final String cssValue) {
        try {

            final Map<Integer, int[]> startAndEndIndexes = new TreeMap<>();

            for (final Entry<String, String> entry : CSS_VALUE_PART_START_END_VALUES
                    .entrySet()) {

                final int[][] rgbStartAndEndIndexesOf = StringUtil
                        .startAndEndIndexesOf(cssValue, entry.getKey(),
                                entry.getValue());
                for (final int[] each : rgbStartAndEndIndexesOf) {
                    startAndEndIndexes.put(each[0], each);
                }
            }

            if (startAndEndIndexes.size() == 0) {
                return Arrays.asList(StringUtil.splitBySpace(
                        StringUtil.convertToSingleSpace(cssValue)));
            }

            final List<String> cssValueParts = new ArrayList<>();

            int count = 0;
            final int startAndEndIndexesSize = startAndEndIndexes.size();

            int[] previousStartEndIndex = null;

            for (final Entry<Integer, int[]> entry : startAndEndIndexes
                    .entrySet()) {

                count++;

                final int[] currentStartEndIndex = entry.getValue();

                final int zerothSlotCurrent = currentStartEndIndex[0];
                final int firstSlotCurrent = currentStartEndIndex[1];

                if (previousStartEndIndex != null) {

                    final int firstSlotOfPrevious = previousStartEndIndex[1];

                    // the difference should be more than two, 1 for at least
                    // one char (css value having length one) + one for space
                    // char.
                    if ((zerothSlotCurrent - firstSlotOfPrevious) > 2) {

                        final String cssValuePart2 = cssValue.substring(
                                firstSlotOfPrevious + 1, zerothSlotCurrent);

                        final String trimmedCssValuePart2 = StringUtil
                                .strip(cssValuePart2);

                        if (StringUtil.startsWithWhitespace(cssValuePart2)
                                && StringUtil
                                        .endsWithWhitespace(cssValuePart2)) {
                            if (!trimmedCssValuePart2.isEmpty()) {
                                for (final String each : StringUtil
                                        .splitBySpace(trimmedCssValuePart2)) {
                                    final String trimmed;
                                    if (!(trimmed = StringUtil.strip(each))
                                            .isEmpty()) {
                                        cssValueParts.add(trimmed);
                                    }
                                }
                            }
                        } else {
                            throw new InvalidValueException(
                                    "there must be a space between each part of cssValue, a space is expected before and/or after '"
                                            + cssValuePart2 + "'");
                        }

                    } else if ((zerothSlotCurrent - firstSlotOfPrevious) == 1) {
                        throw new InvalidValueException(
                                "there must be a space between each part of cssValue, a space is expected before '"
                                        + cssValue.substring(zerothSlotCurrent)
                                        + "'");
                    }

                    cssValueParts
                            .add(cssValue.substring(currentStartEndIndex[0],
                                    currentStartEndIndex[1] + 1));

                } else {

                    // to check whether the starting cssValue part has at least
                    // two chars, 1 for at least one char (css value having
                    // length one) + one for space char.
                    // greater than 1 is enough since zerothSlotCurrent is an
                    // index number.

                    if ((zerothSlotCurrent) > 1) {
                        final String cssValuePart2 = cssValue.substring(0,
                                zerothSlotCurrent);

                        final String trimmedCssValuePart2 = StringUtil
                                .strip(cssValuePart2);

                        if (StringUtil.endsWithWhitespace(cssValuePart2)) {
                            for (final String each : StringUtil
                                    .splitBySpace(trimmedCssValuePart2)) {
                                final String trimmed;
                                if (!(trimmed = StringUtil.strip(each))
                                        .isEmpty()) {
                                    cssValueParts.add(trimmed);
                                }
                            }

                        } else {
                            throw new InvalidValueException(
                                    "there must be a space between each part of cssValue, a space is expected after '"
                                            + cssValuePart2 + "'");
                        }

                    }

                    cssValueParts
                            .add(cssValue.substring(currentStartEndIndex[0],
                                    currentStartEndIndex[1] + 1));

                }

                final int cssValueLength = cssValue.length();
                if (count == startAndEndIndexesSize
                        && (firstSlotCurrent < (cssValueLength - 1))) {

                    final String cssValuePart2 = cssValue
                            .substring(firstSlotCurrent + 1);

                    final String trimmedCssValuePart2 = StringUtil
                            .strip(cssValuePart2);

                    if (StringUtil.startsWithWhitespace(cssValuePart2)) {
                        for (final String each : StringUtil
                                .splitBySpace(trimmedCssValuePart2)) {
                            if (!each.isEmpty()) {
                                cssValueParts.add(each);
                            }
                        }

                    } else {
                        throw new InvalidValueException(
                                "there must be a space between each part of cssValue, a space is expected before '"
                                        + cssValuePart2 + "'");
                    }
                }

                previousStartEndIndex = currentStartEndIndex;

            }

            return cssValueParts;
        } catch (final RuntimeException e) {
            throw new InvalidValueException(e);
        }
    }

