            final AbstractAttribute... attributes) {

        boolean listenerInvoked = false;
        final Lock lock = sharedObject.getLock(ACCESS_OBJECT).writeLock();
        try {
            lock.lock();
            listenerInvoked = addAttributesLockless(updateClient, attributes);
        } finally {
            lock.unlock();
        }

        if (listenerInvoked) {
