protected final void setNonceForWffScript(final String value) {

        if (autoremoveWffScript) {
            throw new InvalidUsageException(
                    "Cannot remove while autoremoveWffScript is set as true. Please do setAutoremoveWffScript(false)");
        }

        if (value != null) {
            if (nonceForWffScriptTag == null) {
                nonceForWffScriptTag = new Nonce(value);
                if (wffScriptTagId != null) {
                    final AbstractHtml[] ownerTags = wffScriptTagId
                            .getOwnerTags();
                    if (ownerTags.length > 0) {
                        final AbstractHtml wffScript = ownerTags[0];
                        wffScript.addAttributes(nonceForWffScriptTag);
                    }
                }
            } else {
                nonceForWffScriptTag.setValue(value);
            }
        } else {
            if (wffScriptTagId != null && nonceForWffScriptTag != null) {
                final AbstractHtml[] ownerTags = wffScriptTagId.getOwnerTags();
                if (ownerTags.length > 0) {
                    final AbstractHtml wffScript = ownerTags[0];
                    wffScript.removeAttributes(nonceForWffScriptTag);
                }
            }
            nonceForWffScriptTag = null;
        }

    }

public static boolean isValid(final String cssValue) {
        // TODO modify to make a strict validation
        final String trimmedCssValue;
        if (cssValue == null
                || (trimmedCssValue = StringUtil.strip(cssValue)).isEmpty()) {
            return false;
        }

        if (INITIAL.equals(trimmedCssValue)
                || INHERIT.equals(trimmedCssValue)) {
            return true;
        }

        final List<String> cssValueParts = CssValueUtil.split(trimmedCssValue);

        if (cssValueParts.size() > 1 && (trimmedCssValue.contains(INITIAL)
                || trimmedCssValue.contains(INHERIT))) {
            return false;
        }

        BorderTopWidth width = null;
        BorderStyle borderStyle = null;
        BorderColorCssValues borderColorCssValues = null;

        for (final String eachPart : cssValueParts) {
            boolean invalid = true;
            if (width == null && BorderTopWidth.isValid(eachPart)) {
                width = new BorderTopWidth(eachPart);
                invalid = false;
            } else if (borderStyle == null && BorderStyle.isValid(eachPart)) {
                borderStyle = BorderStyle.getThis(eachPart);
                invalid = false;
            } else if (borderColorCssValues == null
                    && BorderColorCssValues.isValid(eachPart)) {
                borderColorCssValues = new BorderColorCssValues(eachPart);
                invalid = false;
            }
            if (invalid) {
                return false;
            }
        }

        return true;
    }

