public static int slice(final ByteBuffer data, final int maxSliceSize,
            final Slice<ByteBuffer> slice) {

        ByteBuffer d = data;

        int remaining = 0;
        int sliceCount = 0;
        while ((remaining = d.remaining()) > 0) {
            sliceCount++;
            final byte[] bytes = new byte[maxSliceSize < remaining
                    ? maxSliceSize
                    : remaining];

            final boolean goOn = slice.each(ByteBuffer.wrap(bytes),
                    d.get(bytes).remaining() == 0);

            if (!goOn) {
                break;
            }

            d = d.slice();
        }

        return sliceCount;
    }

public static ByteBuffer merge(final ByteBuffer... dataArray) {
        int totalCapacity = 0;
        for (final ByteBuffer data : dataArray) {
            totalCapacity += data.capacity();
        }
        final ByteBuffer wholeData = ByteBuffer.allocate(totalCapacity);
        for (final ByteBuffer data : dataArray) {
            wholeData.put(data);
        }
        wholeData.flip();

        return wholeData;
    }

