public static boolean isValid(final String cssValue) {
        // TODO modify to make a strict validation
        if (cssValue == null || StringUtil.isBlank(cssValue)) {
            return false;
        }

        final List<String> cssValueParts = CssValueUtil.split(cssValue);

        BorderLeftWidth borderLeftWidth = null;
        BorderLeftStyle borderLeftStyle = null;
        BorderLeftColor borderLeftColor = null;

        for (final String eachPart : cssValueParts) {

            boolean invalid = true;
            if (borderLeftWidth == null && BorderLeftWidth.isValid(eachPart)) {
                borderLeftWidth = new BorderLeftWidth(eachPart);
                invalid = false;
            } else if (borderLeftStyle == null
                    && BorderLeftStyle.isValid(eachPart)) {
                borderLeftStyle = BorderLeftStyle.getThis(eachPart);
                invalid = false;
            } else if (borderLeftColor == null
                    && BorderLeftColor.isValid(eachPart)) {
                borderLeftColor = new BorderLeftColor(eachPart);
                invalid = false;
            }
            if (invalid) {
                return false;
            }
        }

        return borderLeftWidth != null || borderLeftStyle != null
                || borderLeftColor != null;
    }

public static boolean contains(final String cssValue,
            final Collection<String> cssValues, final int lowestLength,
            final int highestLength) {
        if (cssValue == null || cssValue.length() < lowestLength
                || cssValue.length() > highestLength) {
            return false;
        }
        final boolean contains = cssValues
                .contains(TagStringUtil.toUpperCase(cssValue));
        return contains;
    }

public static boolean isValid(final String cssValue) {
        String trimmedCssValue = null;
        if (cssValue == null) {
            return false;
        } else if ((trimmedCssValue = StringUtil.strip(cssValue))
                .equalsIgnoreCase(INITIAL)
                || trimmedCssValue.equalsIgnoreCase(INHERIT)
                || trimmedCssValue.equalsIgnoreCase(NONE)) {
            return true;
        } else if (trimmedCssValue.toLowerCase().startsWith("url(")
                && trimmedCssValue.endsWith(")")) {
            return true;
        }
        return false;
    }

public void setChildText(final String text) {
        if (text == null || text.isEmpty()) {
            removeAllChildren();
        } else {
            addInnerHtml(new NoTag(null, text));
        }
    }

public void setChildText(final boolean updateClient, final String text) {
        if (text == null || text.isEmpty()) {
            removeAllChildren();
        } else {
            addInnerHtmls(updateClient, new NoTag(null, text));
        }
    }

public String getChildText() {
        final List<AbstractHtml> children = getChildren();
        if (children.size() > 0) {
            final StringBuilder builder = new StringBuilder();
            for (final AbstractHtml child : children) {
                builder.append(child.toHtmlString());
            }
            return builder.toString();
        }
        return "";
    }

@Override
    public void stateChanged(final CssProperty stateChangedObject) {

        if (stateChangedObject instanceof BorderTopColor) {
            final BorderTopColor borderTopColor = (BorderTopColor) stateChangedObject;
            if (BorderTopColor.INITIAL.equals(borderTopColor.getCssValue())
                    || BorderTopColor.INHERIT
                            .equals(borderTopColor.getCssValue())) {
                throw new InvalidValueException(
                        "borderTopColor cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof BorderRightColor) {
            final BorderRightColor borderRightColor = (BorderRightColor) stateChangedObject;
            if (BorderRightColor.INITIAL.equals(borderRightColor.getCssValue())
                    || BorderRightColor.INHERIT
                            .equals(borderRightColor.getCssValue())) {
                throw new InvalidValueException(
                        "borderRightColor cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof BorderBottomColor) {
            final BorderBottomColor borderBottomColor = (BorderBottomColor) stateChangedObject;
            if (BorderBottomColor.INITIAL
                    .equals(borderBottomColor.getCssValue())
                    || BorderBottomColor.INHERIT
                            .equals(borderBottomColor.getCssValue())) {
                throw new InvalidValueException(
                        "borderBottomColor cannot have initial/inherit as its cssValue");
            }
        } else if (stateChangedObject instanceof BorderLeftColor) {
            final BorderLeftColor borderLeftColor = (BorderLeftColor) stateChangedObject;
            if (BorderLeftColor.INITIAL.equals(borderLeftColor.getCssValue())
                    || BorderLeftColor.INHERIT
                            .equals(borderLeftColor.getCssValue())) {
                throw new InvalidValueException(
                        "borderLeftColor cannot have initial/inherit as its cssValue");
            }
        }

        assignProducedCssValue(borderTopColor, borderRightColor,
                borderBottomColor, borderLeftColor);

    }

