private static final int find(boolean skipBlocks, String s, char toFind, int from) {
		int open = 0;
		boolean escaping = false;
		for (int i = from; i < s.length(); i++) {
			if (escaping) {
				escaping = false;
				continue;
			}
			char c = s.charAt(i);
			if (c == '\\') {
				escaping = true;
				continue;
			}
			if ((open == 0) && (c == toFind)) {
				return i;
			} else if (skipBlocks && (c == '{')) {
				open++;
			} else if (skipBlocks && (c == '}')) {
				open--;
			}
		}
		return -1;
	}

@Override
	public void received(ByteBuffer deflated) {
		if (ended) {
			throw new IllegalStateException();
		}

		if (deflated.remaining() >= FOOTER_LENGTH) {
			for (ByteBuffer b : previewFooter) {
				if (!read(b)) {
					return;
				}
			}
			previewFooter.clear();
			currentPreviewFooterLength = 0;

			ByteBuffer deflatedKeepingFooter = deflated.duplicate();
			deflatedKeepingFooter.limit(deflatedKeepingFooter.limit() - FOOTER_LENGTH);
			deflated.position(deflated.position() + deflatedKeepingFooter.remaining());
			if (!read(deflatedKeepingFooter)) {
				return;
			}

			currentPreviewFooterLength += deflated.remaining();
			previewFooter.addLast(deflated.duplicate());
			deflated.position(deflated.position() + deflated.remaining());
			return;
		} else {
			currentPreviewFooterLength += deflated.remaining();
			previewFooter.addLast(deflated.duplicate());
			deflated.position(deflated.position() + deflated.remaining());

			int toFlush = FOOTER_LENGTH - currentPreviewFooterLength;
			while (toFlush > 0) {
				ByteBuffer b = previewFooter.getFirst();

				ByteBuffer d = b.duplicate();
				d.limit(Math.min(d.limit(), toFlush));
				b.position(b.position() + d.remaining());
				toFlush -= d.remaining();
				if (!read(d)) {
					return;
				}
				if (!b.hasRemaining()) {
					previewFooter.removeFirst();
				}
			}
		}
	}

@Override
    public int read(final byte[] output, final int offset, final int length) throws TTransportException {
        int read = 0;
        int index = offset;
        int space = length - offset;
        while (space > 0) {
            byte aByte = readAsynchrously();
            output[index] = aByte;
            space--;
            index++;
            read++;
        }
        return read;
    }

@Override
    public void flush() throws TTransportException {
        ChannelBuffer flush = ChannelBuffers.dynamicBuffer();
        flush.writeBytes(output);
        channel.write(flush).awaitUninterruptibly();
    }

public WebSocketClient newClient(final URI url, final WebSocketCallback callback) {
        ClientBootstrap bootstrap = new ClientBootstrap(socketChannelFactory);

        String protocol = url.getScheme();
        if (!protocol.equals("ws") && !protocol.equals("wss")) {
            throw new IllegalArgumentException("Unsupported protocol: " + protocol);
        }

        final WebSocketClientHandler clientHandler = new WebSocketClientHandler(bootstrap, url, callback);

        bootstrap.setPipelineFactory(new ChannelPipelineFactory() {
            public ChannelPipeline getPipeline() throws Exception {
                ChannelPipeline pipeline = Channels.pipeline();
                pipeline.addLast("decoder", new HttpResponseDecoder());
                pipeline.addLast("encoder", new HttpRequestEncoder());
                pipeline.addLast("ws-handler", clientHandler);
                return pipeline;
            }
        });

        return clientHandler;
    }

