private Set<Tuple> getBinaryTupledSet() {
        List<byte[]> membersWithScores = client.getBinaryMultiBulkReply();
        Set<Tuple> set = new LinkedHashSet<Tuple>();
        if (membersWithScores == null) {
            return set;
        }

        Iterator<byte[]> iterator = membersWithScores.iterator();
        if (iterator == null) {
            return set;
        }

        while (iterator.hasNext()) {
            set.add(new Tuple(iterator.next(), Double.valueOf(SafeEncoder.encode(iterator.next()))));
        }
        return set;
    }

public void sendCommand(final Command cmd, final byte[]... args) {
        log.trace("[RedisConnectionSync] Command={} {}", cmd.name(), toStringArgs(args));
        connect();
        RedisProtocol.sendCommand(outputStream, cmd, args);
        this.pipelinedCommands++;
    }

public void connect() {
        if (!isConnected()) {
            try {
                socket = new Socket();
                // ->@wjw_add
                socket.setReuseAddress(true);
                socket.setKeepAlive(true); // Will monitor the TCP connection is
                // valid
                socket.setTcpNoDelay(true); // Socket buffer Whetherclosed, to
                // ensure timely delivery of data
                socket.setSoLinger(true, 0); // Control calls close () method,
                // the underlying socket is
                // closed immediately
                // <-@wjw_add

                socket.connect(new InetSocketAddress(host, port), timeout);
                socket.setSoTimeout(timeout);
                outputStream = new RedisOutputStream(socket.getOutputStream());
                inputStream = new RedisInputStream(socket.getInputStream());
                connectedTime = System.currentTimeMillis();
                log.trace("[RedisConnectionSync] Connected {}", toString());
            } catch (IOException ex) {
                throw new JedisConnectionException(ex);
            }
        }
    }

public void disconnect() {
        if (isConnected()) {
            try {
                inputStream.close();
                outputStream.close();
                if (!socket.isClosed()) {
                    socket.close();
                }
                disconnectedTime = System.currentTimeMillis();
                log.trace("[RedisConnectionSync] Disconnected {}", toString());
            } catch (IOException ex) {
                throw new JedisConnectionException(ex);
            }
        }
    }

