public void run() {
        for (final GatewayServer server : this.serverData.getServers()) {
            if (!server.isExist()) {
                continue;
            }

            Runnable handler = new Runnable() {
                public void run() {
                    if (!server.isExist()) {
                        return;
                    }

                    final boolean result = server.ping();
                    server.setValid(result);
                    log.debug("[HealthCheck] Result {}", server);
                }
            };
            this.threadPool.execute(handler);
        }
    }

public void shutdown() {
        try {
            this.scheduler.shutdownNow();
        } catch (Exception ignored) {
        }

        for (final WaitingServer server : list) {
            try {
                server.destroy();
                log.info("[GatewayServerClear] Destroy gateway server {}", server);
            } catch (Exception ignored) {
            }
        }
        list.clear();
    }

public boolean ping() {
        try {
            return ping(getResource());
        } catch (Exception e) {
            log.error("[GatewayServer] Failed to health check " + toString(), e);
        }

        return false;
    }

public static void sendCommand(final RedisOutputStream os,
                                   final Command command, final byte[]... args) {
        sendCommand(os, command.raw, args);
    }

private static void processError(final RedisInputStream is) {
        String message = is.readLine();
        log.trace("[RedisProtocol] Reply error. -{}", message);
        throw new JedisDataException(message);
    }

private static Object process(final RedisInputStream is) {
        byte b = is.readByte();
        if (b == MINUS_BYTE) {
            processError(is);
            return null;
        } else if (b == ASTERISK_BYTE) {
            return processMultiBulkReply(is);
        } else if (b == COLON_BYTE) {
            return processInteger(is);
        } else if (b == DOLLAR_BYTE) {
            return processBulkReply(is);
        } else if (b == PLUS_BYTE) {
            return processStatusCodeReply(is);
        } else {
            throw new JedisConnectionException("Unknown reply: " + (char) b);
        }
    }

private static byte[] processStatusCodeReply(final RedisInputStream is) {
        final String statusCode = is.readLine();
        log.trace("[RedisProtocol] Reply status-code. +{}", statusCode);
        return SafeEncoder.encode(statusCode);
    }

private static byte[] processBulkReply(final RedisInputStream is) {
        int len = Integer.parseInt(is.readLine());
        log.trace("[RedisProtocol] Reply bulk-reply. ${}", len);
        if (len == -1) {
            return null;
        }
        byte[] read = new byte[len];
        int offset = 0;
        while (offset < len) {
            offset += is.read(read, offset, (len - offset));
        }
        // read 2 more bytes for the command delimiter
        is.readByte();
        is.readByte();

        return read;
    }

private static Long processInteger(final RedisInputStream is) {
        final String num = is.readLine();
        log.trace("[RedisProtocol] Reply integer. :{}", num);
        return Long.valueOf(num);
    }

private static List<Object> processMultiBulkReply(final RedisInputStream is) {
        int num = Integer.parseInt(is.readLine());
        log.trace("[RedisProtocol] Reply multi-bulk-reply. *{}", num);
        if (num == -1) {
            return null;
        }
        List<Object> ret = new ArrayList<Object>(num);
        for (int i = 0; i < num; i++) {
            try {
                ret.add(process(is));
            } catch (JedisDataException e) {
                ret.add(e);
            }
        }
        return ret;
    }

public Set<HV> get(H key, HK field, HK name) {
        final byte[] rawKey = rawKey(key);
        final byte[] rawHashKey = rawHashKey(field);
        final byte[] rawElementName = rawHashKey(name);

        Set<byte[]> rawElementValues = execute(new RedisCallback<Set<byte[]>>() {
            public Set<byte[]> doInRedis(RedisConnection connection) {
                return ((RedisClusterConnection) connection).ssGet(rawKey, rawHashKey, rawElementName);
            }
        }, true);

        return (Set<HV>) deserializeValues(rawElementValues);
    }

public Map<HK, Set<HV>> mulitGet(H key, HK field, Collection<HK> names) {
        if (names.isEmpty()) {
            return new HashMap<HK, Set<HV>>();
        }

        final byte[] rawKey = rawKey(key);
        final byte[] rawHashKey = rawHashKey(field);
        final byte[][] rawElementNames = new byte[names.size()][];
        int count = 0;
        for (HK name : names) {
            rawElementNames[count++] = rawHashKey(name);
        }

        Map<byte[], Set<byte[]>> rawElementValues = execute(new RedisCallback<Map<byte[], Set<byte[]>>>() {
            public Map<byte[], Set<byte[]>> doInRedis(RedisConnection connection) throws DataAccessException {
                return ((RedisClusterConnection) connection).ssMGet(rawKey, rawHashKey, rawElementNames);
            }
        }, true);

        return deserializeHashSet(rawElementValues);
    }

