private byte[][] toByteArrays(final byte[] keyspace, final byte[] uid, final byte[] serviceCode,
                                  final long expireMillis, final byte[][] keys) {
        final byte[][] allArgs = new byte[keys.length + 4][];

        int index = 0;
        allArgs[index++] = keyspace;
        allArgs[index++] = uid;
        allArgs[index++] = serviceCode;
        allArgs[index++] = RedisProtocol.toByteArray(expireMillis);

        for (int i = 0; i < keys.length; i++) {
            allArgs[index++] = keys[i];
        }

        return allArgs;
    }

private byte[][] toByteArrays(final byte[] keyspace, final byte[] uid, final byte[] serviceCode, final byte[][] key) {
        final byte[][] allArgs = new byte[key.length + 3][];
        int index = 0;
        allArgs[index++] = keyspace;
        allArgs[index++] = uid;
        allArgs[index++] = serviceCode;

        for (int i = 0; i < key.length; i++) {
            allArgs[index++] = key[i];
        }
        return allArgs;
    }

private boolean processError(ByteBuf in) {
        int length = lineLength(in);
        if (length == -1) {
            return false;
        }

        in.skipBytes(length);
        return true;
    }

private boolean processMultiBulkReply(ByteBuf in) {
        final int length = lineLength();
        if (length == 0) {
            return false;
        }
        in.skipBytes(length);

        int num = readInt(length - 2);
        if (num == -1) {
            return true;
        }

        for (int i = 0; i < num; i++) {
            if (hasFrame(in) == false) {
                return false;
            }
        }
        return true;
    }

private boolean processInteger(ByteBuf in) {
        int length = lineLength();
        if (length == 0) {
            return false;
        }

        in.skipBytes(length);
        return true;
    }

private boolean processBulkReply(ByteBuf in) {
        int length = lineLength();
        if (length == 0) {
            return false;
        }
        in.skipBytes(length);

        int numBytes = readInt(length - 2); // 2 == \r\n
        if (numBytes == -1) {
            return true;
        }

        if (in.readableBytes() < numBytes + 2) {
            return false;
        }

        in.skipBytes(numBytes + 2);

        return true;
    }

private boolean processStatusCodeReply(ByteBuf in) {
        int length = lineLength();
        if (length == 0) {
            return false;
        }

        in.skipBytes(length);
        return true;
    }

