        BuildInfo buildInfo = BuildInfo.load();
        LOGGER.info("Engine built {} ({})", buildInfo.getVersion(), buildInfo.getTimestampDate());
        LOGGER.debug("Engine configuration: {}",
                engine.getConfiguration().getInfo());
        isBuilt = true;
        return engine;
    }

