@SuppressWarnings("unchecked")
	public Map<String, String> getPartials() {
		final View view = this.getView();
		if (view != null && view instanceof MustacheView) {
			MustacheView mustacheView = (MustacheView) view;
			return mustacheView.getAliases();
		} else {
			final Object object = getModelMap().get(MustacheSettings.PARTIALS_KEY);

			if (object != null && !(object instanceof Map)) {
				throw new MustachePartialsMappingException();
			}

			final Map<String, String> map;

			if (object == null) {
				map = new HashMap<String, String>();
			} else {
				map = (Map<String, String>) object;
			}

			return map;
		}
	}

public void addPartial(final String key, final String name) {
		notNull(key);
		notNull(name);

		View view = this.getView();
		if (view != null && view instanceof MustacheView) {
			// First try to not pollute view model object
			final MustacheView mustacheView = (MustacheView) view;
			mustacheView.addAlias(key, name);
		} else {
			// Otherwise, add partials to model object
			final Map<String, String> currentPartials = getPartials();
			currentPartials.put(key, name);
			super.addObject(MustacheSettings.PARTIALS_KEY, currentPartials);
		}
	}

public void addPartials(final Map<String, String> partials) {
		notNull(partials);

		View view = this.getView();
		if (view != null && view instanceof MustacheView) {
			// First try to not pollute model object
			final MustacheView mustacheView = (MustacheView) view;
			mustacheView.addAliases(partials);
		} else {
			// Otherwise, add partials to model object
			final Map<String, String> currentPartials = getPartials();
			for (Map.Entry<String, String> entry : partials.entrySet()) {
				notNull(entry.getKey());
				notNull(entry.getValue());
				currentPartials.put(entry.getKey(), entry.getValue());
			}
			super.addObject(MustacheSettings.PARTIALS_KEY, currentPartials);
		}
	}

public static <T> T notNull(T object, String message) {
		if (object == null) {
			throw new NullPointerException(message);
		}
		return object;
	}

public static <T> Collection<T> notEmpty(Collection<T> array, String message) {
		if (array == null || array.size() == 0) {
			throw new IllegalArgumentException(message);
		}
		return array;
	}

public static String hasText(String value, String message) {
		if (value == null) {
			throw new IllegalArgumentException(message);
		}

		for (char c : value.toCharArray()) {
			if (!Character.isWhitespace(c)) {
				return value;
			}
		}

		// Found only whitespace characters...
		throw new IllegalArgumentException(message);
	}

public static ScriptEngine getEngine(Collection<InputStream> scripts) {
		ScriptEngine engine = getEngine();

		for (InputStream script : scripts) {
			evaluate(engine, script);
		}

		return engine;
	}

@Bean
	public MustacheViewResolver mustacheViewResolver() {
		String prefix = getPrefix();
		String suffix = getSuffix();
		int order = getOrder();
		boolean cache = getCache();
		String[] viewNames = getViewNames();
		String defaultLayout = getDefaultLayout();
		String layoutKey = getLayoutKey();
		Map<String, String> mappings = getLayoutMappings();

		log.info("Create mustache view resolver");
		log.trace("  => Cache: {}", cache);
		log.trace("  => Prefix: {}", prefix);
		log.trace("  => Suffix: {}", suffix);
		log.trace("  => Order: {}", order);
		log.trace("  => View Names: {}", viewNames);
		log.trace("  => Default layout: {}", defaultLayout);
		log.trace("  => Layout key: {}", layoutKey);
		log.trace("  => Mappings: {}", mappings);

		MustacheViewResolver resolver = new MustacheViewResolver(mustacheCompiler);
		resolver.setCache(cache);
		resolver.setPrefix(prefix);
		resolver.setSuffix(suffix);
		resolver.setOrder(order);
		resolver.setViewNames(viewNames);
		resolver.setLayoutKey(layoutKey);

		if (defaultLayout != null && !defaultLayout.isEmpty()) {
			resolver.setDefaultLayout(defaultLayout);
		}

		if (!mappings.isEmpty()) {
			resolver.setLayoutMappings(mappings);
		}

		return resolver;
	}

public String[] getViewNames() {
		String viewNames = environment.getProperty("mustache.viewNames", valueOf(MustacheSettings.VIEW_NAMES)).trim();
		String[] names = viewNames.split(",");
		for (int i = 0; i < names.length; i++) {
			names[i] = names[i].trim();
		}
		return names;
	}

public Map<String, String> getLayoutMappings() {
		String mappingsValues = environment.getProperty("mustache.layoutMappings", MustacheSettings.LAYOUT_MAPPINGS).trim();

		if (mappingsValues.isEmpty()) {
			return emptyMap();
		}

		Map<String, String> mappings = new HashMap<String, String>();
		String[] values = mappingsValues.split(";");
		if (values.length > 0) {
			for (String value : values) {
				String val = value == null ? "" : value.trim();
				if (val.isEmpty()) {
					continue;
				}

				String[] mapping = val.split(":");
				if (mapping.length != 2) {
					throw new IllegalArgumentException("Mapping must use [viewName]:[layout] format!");
				}

				mappings.put(mapping[0].trim(), mapping[1].trim());
			}
		}

		return unmodifiableMap(mappings);
	}

