      }
    }
  }

public List<AutoScalingPolicy> getTriggeredPolicies() {
    List<AutoScalingPolicy> triggeredPolicies = new ArrayList<>();
    for (AutoScalingPolicy policy : group.getScalingPolicies()) {
      List<TimePoint<Double>> metricValues = getMetricValues(policy.getMetricName());
      int triggerCount = 0;
      int triggerThreshold = 3;
      int inspectCount = 0;
      if (metricValues != null && metricValues.size() > 2) {
        List<TimePoint<Double>> reverse = new ArrayList<>(metricValues);
        Collections.reverse(reverse);
        for (TimePoint<Double> p : reverse) {
          ComparisonOperation op = ComparisonOperation.fromSymbol(policy.getMetricComparison());
          if (op.compare(p.getValue(), Double.valueOf(policy.getMetricThreshold()))) {
            triggerCount++;
          }
          inspectCount++;
          if (inspectCount >= 3) {
            break;
          }
        }
        if (triggerCount >= triggerThreshold) {
          triggeredPolicies.add(policy);
        }
      }
    }
    return triggeredPolicies;
  }

@Override
  public boolean isResolvable(String host) {
    try {
      InetAddress.getByName(host).getHostAddress();
      return true;
    } catch (UnknownHostException ex) {
      log.log(Level.FINE, "Hostname not resolveable {0}.", host);
    }
    return false;
  }

@Override
  public boolean isInNet(String host, String pattern, String mask) {
    host = dnsResolve(host);
    if (host == null || host.length() == 0) {
      return false;
    }
    long lhost = parseIpAddressToLong(host);
    long lpattern = parseIpAddressToLong(pattern);
    long lmask = parseIpAddressToLong(mask);
    return (lhost & lmask) == lpattern;
  }

private long parseIpAddressToLong(String address) {
    long result = 0;
    String[] parts = address.split("\\.");
    long shift = 24;
    for (String part : parts) {
      long lpart = Long.parseLong(part);

      result |= lpart << shift;
      shift -= 8;
    }
    return result;
  }

@Override
  public String dnsResolve(String host) {
    try {
      return InetAddress.getByName(host).getHostAddress();
    } catch (UnknownHostException e) {
      log.log(Level.FINE, "DNS name not resolvable {0}.", host);
    }
    return "";
  }

private String getLocalAddressOfType(Class<? extends InetAddress> cl) {
    try {
      String overrideIP = System.getProperty(OVERRIDE_LOCAL_IP);
      if (overrideIP != null && overrideIP.trim().length() > 0) {
        return overrideIP.trim();
      }
      Enumeration<NetworkInterface> interfaces = NetworkInterface
          .getNetworkInterfaces();
      while (interfaces.hasMoreElements()) {
        NetworkInterface current = interfaces.nextElement();
        if (!current.isUp() || current.isLoopback() || current.isVirtual()) {
          continue;
        }
        Enumeration<InetAddress> addresses = current.getInetAddresses();
        while (addresses.hasMoreElements()) {
          InetAddress adr = addresses.nextElement();
          if (cl.isInstance(adr)) {
            log.log(Level.FINER, "Local address resolved to {0}", adr);
            return adr.getHostAddress();
          }
        }
      }
      return "";
    } catch (IOException e) {
      log.log(Level.FINE, "Local address not resolvable.");
      return "";
    }
  }

