  public Set<String> getSupportedAnnotationTypes() {
    Set<String> set = new HashSet<>();
    // Analyze @SupportedAnnotationTypes
    SupportedAnnotationTypes sat = this.getClass().getAnnotation(SupportedAnnotationTypes.class);
    if (sat != null) {
      Arrays.stream(sat.value()).forEach(set::add);
    }
    // Analyze @SupportedAnnotation
    SupportedAnnotation sa = this.getClass().getAnnotation(SupportedAnnotation.class);
    if (sa != null) {
      Arrays.stream(sa.value()).map(Class::getCanonicalName).forEach(set::add);
    }
    if (set.isEmpty() && isInitialized()) {
      debug().log("No SupportedAnnotationTypes annotation found on " + this.getClass().getName()
          + ", returning an empty set.");
    }
    return Collections.unmodifiableSet(set);
  }

public static long checkGreaterLong(
    final long x,
    final String x_name,
    final long in_lower,
    final String lower_name)
  {
    Objects.requireNonNull(x_name, "Value name");
    Objects.requireNonNull(lower_name, "Lower bound name");

    if (x > in_lower) {
      return x;
    }

    @SuppressWarnings("boxing") final var message =
      String.format("%s (%d) <= %s (%d)", x_name, x, lower_name, in_lower);

    throw new RangeCheckException(message);
  }

