private void displayWorkflow(Workflow w) {
        Graph graph = new Graph(w.getWorkflowName(), Graph.DIGRAPH);
        nodes.clear();
        //Create the nodes
        w.getWorkflowStepList().forEach(step -> {
            addStep(step, graph);
            //Now add the links
            step.getSourceTransitions().forEach(t -> {
                addStep(t.getWorkflowStepSource(), graph);
                addStep(t.getWorkflowStepTarget(), graph);
                Subgraph.Edge edge
                        = graph.addEdge(nodes.get(t.getWorkflowStepSource()
                                .getWorkflowStepPK().getId()),
                                nodes.get(t.getWorkflowStepTarget()
                                        .getWorkflowStepPK().getId()));
                edge.setParam("label", TRANSLATOR.translate(t.getTransitionName()));
                //Workaround https://github.com/pontusbostrom/VaadinGraphvizComponent/issues/9
                edge.setDest(nodes.get(t.getWorkflowStepTarget()
                        .getWorkflowStepPK().getId()));
                edges.put(TRANSLATOR.translate(t.getTransitionName()),
                        new AbstractMap.SimpleEntry<>(
                                nodes.get(t.getWorkflowStepSource()
                                        .getWorkflowStepPK().getId()), edge));
            });
        });
        diagram.drawGraph(graph);
    }

private void refreshWorkflow() {
        Graph graph = new Graph(((Workflow) workflows.getValue())
                .getWorkflowName(), Graph.DIGRAPH);
        nodes.values().forEach(node -> {
            graph.addNode(node);
        });
        edges.values().forEach(edge -> {
            graph.addEdge(edge.getKey(), edge.getValue().getDest());
        });
        diagram.drawGraph(graph);
        selected = null;
        updateControls();
    }

public static void updateLocale(final HasComponents ui, final Locale locale,
            final ResourceBundle rb) {

        // locale may not be null, however the current UI Locale may be null!
        if (locale.equals(ui.getLocale())) {
            return;
        }
        final long time = System.currentTimeMillis();
        walkComponentTree(ui, (Component c) -> {
            String id = c.getId();
            String caption;
            if (c instanceof Property
                    && ((Property) c).getValue() instanceof String) {
                caption = (String) ((Property) c).getValue();
            } else {
                caption = c.getCaption();
            }
            if (id != null && !id.trim().isEmpty()) {
                if (rb.containsKey(id)) {
                    try {
                        c.setCaption(new String(rb.getString(id)
                                .getBytes("ISO-8859-1"), "UTF-8"));
                    }
                    catch (UnsupportedEncodingException ex) {
                        LOG.log(Level.SEVERE, null, ex);
                    }
                }
            } else if (caption != null && !caption.trim().isEmpty()) {
                /**
                 * This is a more complex scenario where the caption uses more
                 * than one key for translation. Sort the keys in reverse so
                 * substitutions are correct.
                 */
                final SortedSet<String> ss = new TreeSet<>(Collections.reverseOrder());
                for (Enumeration<String> e = rb.getKeys(); e.hasMoreElements();) {
                    try {
                        String key = e.nextElement();
                        ss.add(key);
                        caption = caption.replaceAll(key, new String(rb.getString(key)
                                .getBytes("ISO-8859-1"), "UTF-8"));
                    }
                    catch (UnsupportedEncodingException ex) {
                        LOG.log(Level.SEVERE, null, ex);
                    }
                }
                if (c instanceof Property) {
                    ((Property) c).setValue(caption);
                } else {
                    c.setCaption(caption);
                }
            }
        });
        LOG.log(Level.FINE, "Locale updated: {0} -> {1} in {2} ms.",
                new Object[]{ui.getLocale(), locale,
                    System.currentTimeMillis() - time});
    }

private static void walkComponentTree(Component c, Consumer<Component> visitor) {
        visitor.accept(c);
        if (c instanceof HasComponents) {
            for (Component child : ((HasComponents) c)) {
                walkComponentTree(child, visitor);
            }
        }
    }

