            byte[] data = keyMode == KeyMode.HASH
                    ? getJedis().hget(SafeEncoder.encode(getName()), SafeEncoder.encode(KEY))
                    : getJedis().get(SafeEncoder.encode(KEY));
            if (data != null) {
                CacheEntry ce = deserializeCacheEntry(data);
                if (ce != null && ce.touch()) {
                    /*
