private List<String> visibleFields(PersonAuth pAuth, SPFPersona persona, String[] fields) {
		SQLiteDatabase db = getReadableDatabase();
		String table = Contract.TABLE_VISIBILITY;
		String[] columns = { Contract.COLUMN_KEY, Contract.COLUMN_CIRCLE };
		String inClause = getInClause(fields);
		String selection = Contract.COLUMN_PERSONA + " = ? AND " + Contract.COLUMN_KEY + " IN " + inClause;
		String[] selectionArgs = { persona.getIdentifier() };
		String groupBy = null;
		String having = null;
		String orderBy = null;
		Cursor c = db.query(table, columns, selection, selectionArgs, groupBy, having, orderBy);

		List<String> fieldKeys = new ArrayList<String>();
		List<String> privateFields = new ArrayList<String>();
		boolean allCircles = pAuth.getCircles().contains(DefaultCircles.ALL_CIRCLE);

		while (c.moveToNext()) {
			String key = c.getString(c.getColumnIndex(Contract.COLUMN_KEY));
			String circle = c.getString(c.getColumnIndex(Contract.COLUMN_CIRCLE));
			if (circle.equals(DefaultCircles.PRIVATE)){
				privateFields.add(circle);
			} else if (allCircles || pAuth.getCircles().contains(circle)) {
				fieldKeys.add(key);
			}
		}
		c.close();
		fieldKeys.removeAll(privateFields);
		return fieldKeys;
	}

private String getInClause(String[] fields) {
		StringBuilder builder = new StringBuilder("( ");
		if (fields.length != 0) {
			for (int i = 0; i < fields.length; i++) {
				builder.append("'");
				builder.append(fields[i]);
				builder.append("'");
				if (i != fields.length - 1) {
					builder.append(" , ");
				}
			}
		}
		builder.append(" )");
		return builder.toString();
	}

public boolean registerService(SPFServiceDescriptor descriptor) {
		String appId = descriptor.getAppIdentifier();
		String serviceName = descriptor.getServiceName();

		for (String verb : descriptor.getConsumedVerbs()) {
			if (!registerServiceInternal(verb, serviceName, appId)) {
				return false;
			}

			Log.v(TAG, "Registered service as Activity consumer: " + descriptor.getServiceName());
		}

		return true;
	}

public Collection<ActivityVerb> getVerbSupport() {
		Map<String, ActivityVerb> entries = new HashMap<String, ActivityVerb>();

		String[] columns = { Contract.APP_ID, Contract.SERVICE_NAME, Contract.VERB };
		Cursor c = getReadableDatabase().query(true, Contract.TABLE_SERVICES, columns, null, null, null, null, null, null);

		int appIndex = c.getColumnIndexOrThrow(Contract.APP_ID);
		int verbIndex = c.getColumnIndexOrThrow(Contract.VERB);
		int svcIndex = c.getColumnIndexOrThrow(Contract.SERVICE_NAME);

		while (c.moveToNext()) {
			String verb = c.getString(verbIndex);
			String appId = c.getString(appIndex);
			String svcName = c.getString(svcIndex);

			ActivityVerb d = entries.get(verb);
			if (d == null) {
				d = new ActivityVerb(verb);
				entries.put(verb, d);
			}

			d.addSupportingService(new ServiceIdentifier(appId, svcName));
		}

		c.close();

		for (ActivityVerb d : entries.values()) {
			d.setDefaultApp(getServiceForInternal(d.getVerb()));
		}

		return entries.values();
	}

