public <E> E getFieldValue(ProfileField<E> field) {
        if (field == null) {
            throw new NullPointerException();
        }

        String val = mFields.getString(field.getIdentifier());
        return val == null ? null : ProfileFieldConverter.forField(field).fromStorageString(val);
    }

public <E> void setFieldValue(ProfileField<E> field, E value) {
        if (field == null || value == null) {
            throw new NullPointerException();
        }

        if (getStatus(field) == FieldStatus.UNACCESSIBLE) {
            throw new IllegalStateException("Cannot write an unaccessible field");
        }

        String newVal = ProfileFieldConverter.forField(field).toStorageString(value);
        String currentVal = mFields.getString(field.getIdentifier());

        if (newVal.equals(currentVal)) {
            return;
        }

        if (getStatus(field) == FieldStatus.ORIGINAL) {
            setStatus(field.getIdentifier(), FieldStatus.MODIFIED);
        }

        mFields.putString(field.getIdentifier(), newVal);
    }

public boolean isModified() {
        for (String key : mStatus.keySet()) {
            FieldStatus status = getStatus(key);
            if (status == FieldStatus.DELETED || status == FieldStatus.MODIFIED) {
                return true;
            }
        }

        return false;
    }

public void clearModified() {
        for (String field : mStatus.keySet()) {
            switch (getStatus(field)) {
                case DELETED:
                    mStatus.remove(field);
                    break;
                case MODIFIED:
                    setStatus(field, FieldStatus.ORIGINAL);
                    break;
                default:
                    continue;
            }
        }
    }

@Override
    public void writeToParcel(Parcel dest, int flags) {
        dest.writeBundle(mFields);
        dest.writeBundle(mStatus);
    }

@Override
	protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
		super.onMeasure(widthMeasureSpec, heightMeasureSpec);

		final int width = MeasureSpec.getSize(widthMeasureSpec);
		int height = MeasureSpec.getSize(heightMeasureSpec);

		// increment the x position as we progress through a line
		int xpos = getPaddingLeft();
		// increment the y position as we progress through the lines
		int ypos = getPaddingTop();
		// the height of the current line
		int line_height = 0;

		// go through children
		// to work out the height required for this view
		measureChildren(widthMeasureSpec, heightMeasureSpec);

		View child;
		MarginLayoutParams childMarginLayoutParams;
		int childWidth, childHeight, childMarginLeft, childMarginRight, childMarginTop, childMarginBottom;

		for (int i = 0; i < getChildCount(); i++) {
			child = getChildAt(i);

			if (child.getVisibility() != GONE) {
				childWidth = child.getMeasuredWidth();
				childHeight = child.getMeasuredHeight();

				if (child.getLayoutParams() != null
						&& child.getLayoutParams() instanceof MarginLayoutParams) {
					childMarginLayoutParams = (MarginLayoutParams) child
							.getLayoutParams();

					childMarginLeft = childMarginLayoutParams.leftMargin;
					childMarginRight = childMarginLayoutParams.rightMargin;
					childMarginTop = childMarginLayoutParams.topMargin;
					childMarginBottom = childMarginLayoutParams.bottomMargin;
				} else {
					childMarginLeft = 0;
					childMarginRight = 0;
					childMarginTop = 0;
					childMarginBottom = 0;
				}

				if (xpos + childMarginLeft + childWidth + childMarginRight
						+ getPaddingRight() > width) {
					// this child will need to go on a new line

					xpos = getPaddingLeft();
					ypos += line_height;

					line_height = childMarginTop + childHeight
							+ childMarginBottom;
				} else
					// enough space for this child on the current line
					line_height = Math.max(line_height, childMarginTop
							+ childHeight + childMarginBottom);

				xpos += childMarginLeft + childWidth + childMarginRight;
			}
		}

		ypos += line_height + getPaddingBottom();

		if (MeasureSpec.getMode(heightMeasureSpec) == MeasureSpec.UNSPECIFIED)
			// set height as measured since there's no height restrictions
			height = ypos;
		else if (MeasureSpec.getMode(heightMeasureSpec) == MeasureSpec.AT_MOST
				&& ypos < height)
			// set height as measured since it's less than the maximum allowed
			height = ypos;

		setMeasuredDimension(width, height);
	}

public void startSearch(final int tag,
			SPFSearchDescriptor searchDescriptor, final SearchCallback callback) {
		// replace equivalent query ( equivalent == same tag )
		if (mTagToId.get(tag) != null) {
			Log.d("start search", "mTagToId.get(tag) != null");
			String queryId = mTagToId.get(tag);
			Log.d("start search", "mTagToId.get(tag)= " + mTagToId.get(tag));
			mTagToId.delete(tag);
			SearchCallback state = mCallbacks.remove(queryId);
			if (queryId != null && state != null) {
				Log.d("start search", "queryId: " + queryId + ", state: " + state );
				mSearchInterface.stopSearch(queryId);
				Log.d("start search", "stopSearch");

			}
		}

		Log.d("start search", "startSearch");
		mSearchInterface.startSearch(searchDescriptor,
				new SPFSearchCallbackImpl(callback, tag));
	}

public void stopSearch(int tag) {
		String queryId = mTagToId.get(tag);
		mTagToId.delete(tag);
		if (queryId != null && mCallbacks.remove(queryId) != null) {
			mSearchInterface.stopSearch(queryId);
		}
	}

public void stopAllSearches() {
		mTagToId.clear();
		String[] queryIds = mCallbacks.keySet().toArray(new String[]{});
		mCallbacks.clear();
		for (String queryId : queryIds) {
			mSearchInterface.stopSearch(queryId);
		}
	}

