  }

public static Class forName(Class clazz, ClassLoader classLoader)
    throws ClassNotFoundException, LinkageError
  {
    if(clazz == null)
      return null;

    if(classLoader == null)
    {
      classLoader = getDefaultClassLoader();
    }

    if(clazz.getClassLoader() == null || clazz.getClassLoader().equals(classLoader))
      return clazz;
    else
      return forName(clazz.getName(), classLoader);
  }

public static <T> T executeWithClassLoader(ClassLoader classLoader,
                                             Callable<T> callable) throws Exception
  {
    ClassLoader previousClassLoader = Thread.currentThread().getContextClassLoader();
    try
    {
      Thread.currentThread().setContextClassLoader(classLoader);
      return callable.call();
    }
    finally
    {
      Thread.currentThread().setContextClassLoader(previousClassLoader);
    }
  }

@SuppressWarnings("unchecked")
  public static String computeSignature(Method m)
  {
    StringBuilder sb = new StringBuilder();

    sb.append(m.getName()).append('(');
    Class[] parameterTypes = m.getParameterTypes();

    for (int i = 0; i < parameterTypes.length; i++)
    {
      if(i > 0)
        sb.append(',');
      Class parameterType = parameterTypes[i];
      sb.append(parameterType.getName());
    }
    sb.append(')');

    return sb.toString();
  }

public static Class[] extractAllInterfaces(Object o)
  {
    Set<Class> interfaces = new LinkedHashSet<Class>();

    Class c = o.getClass();
    do
    {
      interfaces.addAll(Arrays.asList(c.getInterfaces()));
      c = c.getSuperclass();
    }
    while(c != null);

    return interfaces.toArray(new Class[interfaces.size()]);
  }

@SuppressWarnings("unchecked")
  public static <T> T createProxy(InvocationHandler handler, Class<T> itface)
  {
    if(handler instanceof ObjectProxy)
    {
      ObjectProxy proxy = (ObjectProxy) handler;
      if(!ReflectUtils.isSubClassOrInterfaceOf(proxy.getProxiedObject().getClass(), itface))
        throw new IllegalArgumentException(proxy.getProxiedObject().getClass() + " does not extend " + itface);
    }

    return (T) Proxy.newProxyInstance(itface.getClassLoader(),
                                      new Class<?>[] {itface},
                                      handler);
  }

public static Object createProxy(InvocationHandler handler, Class<?>... itfaces)
  {
    if(handler instanceof ObjectProxy)
    {
      ObjectProxy proxy = (ObjectProxy) handler;
      Class<?> proxyClass = proxy.getProxiedObject().getClass();
      for(Class<?> itface : itfaces)
      {
        if(!ReflectUtils.isSubClassOrInterfaceOf(proxyClass, itface))
          throw new IllegalArgumentException(proxyClass + " does not extend " + itface);
      }
    }

    List<ClassLoader> classLoaders = new ArrayList<ClassLoader>();
    for(Class<?> itface : itfaces)
    {
      classLoaders.add(itface.getClassLoader());
    }

    ClassLoader classLoader = ClassLoaderChain.createChain(classLoaders);

    return Proxy.newProxyInstance(classLoader,
                                  itfaces,
                                  handler);
  }

public static void awaitUntil(Condition condition, long endTime)
    throws InterruptedException, TimeoutException
  {
    awaitUntil(SystemClock.INSTANCE, condition, endTime);
  }

public static void awaitUntil(Clock clock, Condition condition, long endTime)
    throws InterruptedException, TimeoutException
  {
    if(endTime <= 0)
      condition.await();
    else
    {
      long now = clock.currentTimeMillis();
      if(now >= endTime)
        throw new TimeoutException("timeout reached while waiting on the lock: "
                                   + condition);

      if(!condition.await(endTime - now, TimeUnit.MILLISECONDS))
        throw new TimeoutException("timeout reached while waiting on the lock: "
                                   + condition);
    }
  }

public static void awaitUntil(Object lock, long endTime)
    throws InterruptedException, TimeoutException
  {
    awaitUntil(SystemClock.INSTANCE, lock, endTime);
  }

public static void awaitUntil(Clock clock, Object lock, long endTime)
    throws InterruptedException, TimeoutException
  {
    if(endTime <= 0)
      lock.wait();
    else
    {
      long now = clock.currentTimeMillis();
      if(now >= endTime)
        throw new TimeoutException("timeout reached while waiting on the lock: "
                                   + lock);
      lock.wait(endTime - now);
    }
  }

public static void joinUntil(Clock clock, Thread thread, long endTime)
    throws InterruptedException, TimeoutException
  {
    if(endTime <= 0)
      thread.join();
    else
    {
      while(thread.isAlive())
      {
        long now = clock.currentTimeMillis();
        if(now >= endTime)
          throw new TimeoutException("timeout reached while joining on: " + thread);
        thread.join(endTime - now);
      }
    }
  }

public static void joinFor(Clock clock, Thread thread, Object timeout)
    throws InterruptedException, TimeoutException
  {
    joinUntil(clock, thread, ClockUtils.toEndTime(timeout));
  }

