public void appendPath(String path, boolean encodePath)
  {
    if(path == null)
      return;

    if(encodePath)
      path = urlEncode(path);

    if(path.startsWith("/"))
      path = path.substring(1);

    if(_path == null || "".equals(_path))
    {
      StringBuilder sb = new StringBuilder("/");
      sb.append(path);
      _path = sb.toString();
    }
    else
    {
      StringBuilder sb = new StringBuilder(_path);

      if(_path.endsWith("/"))
        sb.append(path);
      else
        sb.append('/').append(path);

      _path = sb.toString();
    }
  }

