public List<String> splitAsList(String s)
  {
    if(s == null)
      return null;

    int len = s.length();

    if(len == 0)
    {
      return Collections.emptyList();
    }

    if(_blockIgnore == null)
      return splitNoBlockIgnore(s);
    else
      return splitBlockIgnore(s);
  }

