public static Random createRandom(String password)
  {
    if(password == null)
      return null;

    byte[] bytes;

    try
    {
      MessageDigest md = MessageDigest.getInstance("SHA-1");
      bytes = md.digest(password.getBytes("UTF-8"));
    }
    catch(NoSuchAlgorithmException e)
    {
      // should not happen
      throw new RuntimeException(e);
    }
    catch(UnsupportedEncodingException e)
    {
      // should not happen
      throw new RuntimeException(e);
    }

    int len = bytes.length;

    // we only take at most 6 bytes => 48 bits
    if(len > 6)
      len = 6;

    long seed = 0;

    if(len > 0)
    {
      seed = bytes[0];

      for(int i = 1; i < len; i++)
      {
        seed <<=  8;
        seed |= bytes[i];
      }
    }

    int k = 0;

    for(int i = len; i < bytes.length; i++)
    {
      seed ^= (((long) bytes[i]) << (k * 8));
      if(k++ == 5)
        k = 0;
    }

    return new Random(seed);
  }

public static String searchAndReplace(String s, String src, String dst)
  {
    if(s == null)
      return null;

    StringBuilder result = new StringBuilder();

    int i = 0;
    int len = s.length();
    int len2 = src.length();

    while(i < len)
    {
      int index = s.indexOf(src, i);
      if(index == -1)
      {
        if(i == 0)
          return s;

        result.append(s.substring(i));
        break;
      }

      result.append(s.substring(i, index));
      result.append(dst);

      i = index + len2;
    }

    return result.toString();
  }

public static ClassLoader createChain(List<ClassLoader> classLoaders, Boolean createNew)
  {
    List<ClassLoader> list = new ArrayList<ClassLoader>(classLoaders.size());

    for(ClassLoader classLoader : classLoaders)
    {
      // we skip null class loaders
      if(classLoader == null)
        continue;

      // we skip null class loaders
      if(classLoader instanceof NullClassLoader)
        continue;

      // we 'flatten' the chain... no need to have a chain of a chain...
      if(classLoader instanceof ClassLoaderChain)
      {
        ClassLoaderChain classLoaderChain = (ClassLoaderChain) classLoader;
        list.addAll(classLoaderChain._classLoaders);
      }
      else
      {
        list.add(classLoader);
      }
    }

    if(list.size() == 0)
      return NullClassLoader.instance();

    // remove duplicates
    ClassLoader previous = null;
    Iterator<ClassLoader> iter = list.iterator();
    while(iter.hasNext())
    {
      ClassLoader next = iter.next();

      if(next.equals(previous))
        iter.remove();

      previous = next;
    }

    //TODO: create a new entry point, and keeping old behavior unchanged. 
    if(list.size() == 1 && !createNew)
      return list.get(0);

    return new ClassLoaderChain(list);
  }

private synchronized void init()
  {
    // already initialized
    if(_resourceInfo != null)
      return;

    // make a local copy of the file
    try
    {
      InputStream is = _resource.getInputStream();
      try
      {
        File file = GCFile.createTempFile(LocalCacheLeafResource.class.getName(),
                                          _resource.getFilename());
        FileOutputStream fos = new FileOutputStream(file);
        try
        {
          BufferedOutputStream out = new BufferedOutputStream(fos);
          IOUtils.copy(new BufferedInputStream(is), out);
          out.flush();
        }
        finally
        {
          fos.close();
        }

        ResourceInfo info = _resource.getInfo();

        _localFile = file;
        _resourceInfo = new StaticInfo(info.getContentLength(), info.getLastModified());
        _ioException = null;
      }
      finally
      {
        is.close();
      }
    }
    catch(IOException e)
    {
      _localFile = null;
      _resourceInfo = new StaticInfo(0, 0);
      _ioException = e;
    }

  }

