  {
    StringBuilder sb = new StringBuilder();

    EnumMap<TimeUnit, Timespan> canonicalTimespans = getAsTimespans(timeUnits);
    for(TimeUnit timeUnit : TIME_UNIT_ORDER)
    {
      if(canonicalTimespans.containsKey(timeUnit))
      {
