@SuppressWarnings("unchecked") // use runtime checks to guarantee that 'T' is what it is
  private <T> ObjectConstructor<T> newDefaultImplementationConstructor(Class<? super T> rawType) {
    if (Collection.class.isAssignableFrom(rawType)) {
      if (SortedSet.class.isAssignableFrom(rawType)) {
        return new ObjectConstructor<T>() {
          public T construct() {
            return (T) new TreeSet<Object>();
          }
        };
      } else if (Set.class.isAssignableFrom(rawType)) {
        return new ObjectConstructor<T>() {
          public T construct() {
            return (T) new LinkedHashSet<Object>();
          }
        };
      } else if (Queue.class.isAssignableFrom(rawType)) {
        return new ObjectConstructor<T>() {
          public T construct() {
            return (T) new LinkedList<Object>();
          }
        };
      } else {
        return new ObjectConstructor<T>() {
          public T construct() {
            return (T) new ArrayList<Object>();
          }
        };
      }
    }

    if (Map.class.isAssignableFrom(rawType)) {
      return new ObjectConstructor<T>() {
        public T construct() {
          return (T) new LinkedHashMap<Object, Object>();
        }
      };
      // TODO: SortedMap ?
    }

    return null;
  }

@Override
	public SimpleNotificationMessage translate(Context context, NotificationMessage message) throws SocializeException {

		SimpleNotificationMessage msg = newSimpleNotificationMessage();
		StringBuilder titleBuilder = newStringBuilder();

		titleBuilder.append(message.getUser());

		switch (message.getActionType()) {
			case COMMENT:
				titleBuilder.append(" commented on ");
				break;
			case SHARE:
				titleBuilder.append(" shared ");
				break;
			case LIKE:
				titleBuilder.append(" liked ");
				break;
			case VIEW:
				titleBuilder.append(" viewed ");
				break;			
		}

		titleBuilder.append(message.getEntity());

		msg.setTitle(titleBuilder.toString());
		msg.setText(message.getText());

		return msg;
	}

@Override
	protected void toJSON(Propagation from, JSONObject to) throws JSONException {

		// Make params
		Map<String, String> extraParams = from.getExtraParams();

		if(extraParams != null && extraParams.size() > 0) {

			Set<Entry<String, String>> entrySet = extraParams.entrySet();

			if(entrySet != null && entrySet.size() > 0) {

				int count = 0;

				StringBuilder builder = new StringBuilder();

				for (Entry<String, String> entry : entrySet) {

					String key = entry.getKey();
					String value = entry.getValue();

					if(!StringUtils.isEmpty(key) && !StringUtils.isEmpty(value)) {
						if(count > 0) {
							builder.append("&");
						}			

						builder.append(URLEncoder.encode(key));
						builder.append("=");
						builder.append(URLEncoder.encode(value));

						count++;
					}
				}

				to.put("extra_params", builder.toString());
			}
		}

		JSONArray networks = new JSONArray();

		List<ShareType> thirdParties = from.getThirdParties();

		if(thirdParties != null && thirdParties.size() > 0) {
			for (ShareType socialNetwork : thirdParties) {
				networks.put(socialNetwork.name().toLowerCase());
			}
			to.put("third_parties", networks);
		}
	}

public static String replaceNewLines(String src, int from, int to) {
		if(src != null && from > 0 && to < from) {

			String strFrom = "";
			String strTo = "";

			for (int i = 0; i < from; i++) {
				strFrom+="\n";
			}
			for (int i = 0; i < to; i++) {
				strTo+="\n";
			}

			while (src.contains(strFrom)) {
				src = src.replaceAll(strFrom, strTo);
			}
		}
		return src;
	}

