		for (Class<?> cls : activityClasses) {
			if(appUtils.isActivityAvailable(context, cls)) {
				activityClass = cls;
				break;
			}
		}

		if(activityClass != null) {
			Intent intent = newIntent(context, activityClass);
			intent.putExtras(data);
