		if(o != null) {
			if (o.time > time) {
				return -1;
			}
			else if (o.time < time) {
				return 1;
			}
			else if(o.key != null) {
				return o.key.compareTo(key);
			}
			else {
				return 0;
			}
		}

		return 0;
	}

