		}
		if (wrap != null) {
			args.add(flagify(CowsayCli.Opt.WRAP_AT.toString()));
			args.add(wrap);
		}
		buildFaceArgs(args);
		args.add(message);
		return args.toArray(result);
	}

private void buildFaceArgs(final List<String> args) {
