                // if the implementation didn't respond to the Promise we mark it as a failure.
                if (!promise.isCompleted()) {
                    promise.failure(new IllegalStateException("No response was provided by the Promise"));
                }
            } catch (Exception ex) {
                promise.failure(ex);
            }
        });
    }

