    if (sequenceSize == 0 && listSize != 0) {
      failIfNotStartingWithSequence(sequence);
    }
    if (listSize < sequenceSize) {
      failIfNotStartingWithSequence(sequence);
    }
    for (int i = 0; i < sequenceSize; i++) {
