public static String enumerate(Integer number) {

		if (number == null || number <= 0) {
			return null;
		}

		int lastDigit = number % 10;

		switch (number) { // special case for first five
			case 1:
				return "first";
			case 2:
				return "second";
			case 3:
				return "third";
			case 4:
				return "fourth";
			case 5:
				return "fifth";

			default:
				switch (lastDigit) {
					case 1:
						return number + "st";
					case 2:
						return number + "nd";
					case 3:
						return number + "rd";

					default:
						return number + "th";
				}
		}
	}

