private void doRuleRow(ConfReference ref, CheckstyleResults results, String previousCategory) {
        Configuration checkerConfig = ref.configuration;
        ChainedItem<Configuration> parentConfiguration = ref.parentConfiguration;
        String ruleName = checkerConfig.getName();

        sink.tableRow();

        // column 1: rule category
        sink.tableCell();
        String category = ref.category;
        if (!category.equals(previousCategory)) {
            sink.text(category);
        }
        sink.tableCell_();

        // column 2: Rule name + configured attributes
        sink.tableCell();
        if (!"extension".equals(category)) {
            sink.link("http://checkstyle.sourceforge.net/config_" + category + ".html#" + ruleName);
            sink.text(ruleName);
            sink.link_();
        } else {
            sink.text(ruleName);
        }

        List<String> attribnames = new ArrayList<>(Arrays.asList(checkerConfig.getAttributeNames()));
        attribnames.remove("severity"); // special value (deserves unique column)
        if (!attribnames.isEmpty()) {
            sink.list();
            for (String name : attribnames) {
                sink.listItem();

                sink.text(name);

                String value = getConfigAttribute(checkerConfig, null, name, "");
                // special case, Header.header and RegexpHeader.header
                if ("header".equals(name) && ("Header".equals(ruleName) || "RegexpHeader".equals(ruleName))) {
                    String[] lines = StringUtils.split(value, "\\n");
                    int linenum = 1;
                    for (String line : lines) {
                        sink.lineBreak();
                        sink.rawText("<span style=\"color: gray\">");
                        sink.text(linenum + ":");
                        sink.rawText("</span>");
                        sink.nonBreakingSpace();
                        sink.monospaced();
                        sink.text(line);
                        sink.monospaced_();
                        linenum++;
                    }
                } else if ("headerFile".equals(name) && "RegexpHeader".equals(ruleName)) {
                    sink.text(": ");
                    sink.monospaced();
                    sink.text("\"");
                    if (basedir != null) {
                        // Make the headerFile value relative to ${basedir}
                        String path = siteTool.getRelativePath(value, basedir.getAbsolutePath());
                        sink.text(path.replace('\\', '/'));
                    } else {
                        sink.text(value);
                    }
                    sink.text("\"");
                    sink.monospaced_();
                } else {
                    sink.text(": ");
                    sink.monospaced();
                    sink.text("\"");
                    sink.text(value);
                    sink.text("\"");
                    sink.monospaced_();
                }
                sink.listItem_();
            }
            sink.list_();
        }

        sink.tableCell_();

        // column 3: rule violation count
        sink.tableCell();
        sink.text(String.valueOf(ref.violations));
        sink.tableCell_();

        // column 4: severity
        sink.tableCell();
        // Grab the severity from the rule configuration, this time use error as default value
        // Also pass along all parent configurations, so that we can try to find the severity there
        String severity = getConfigAttribute(checkerConfig, parentConfiguration, "severity", "error");
        iconTool.iconSeverity(severity, IconTool.TEXT_SIMPLE);
        sink.tableCell_();

        sink.tableRow_();
    }

public boolean matchRule(AuditEvent event, String ruleName, String expectedMessage, String expectedSeverity) {
        if (!ruleName.equals(RuleUtil.getName(event))) {
            return false;
        }

        // check message too, for those that have a specific one.
        // like GenericIllegalRegexp and Regexp
        if (expectedMessage != null) {
            // event.getMessage() uses java.text.MessageFormat in its implementation.
            // Read MessageFormat Javadoc about single quote:
            // http://java.sun.com/j2se/1.4.2/docs/api/java/text/MessageFormat.html
            String msgWithoutSingleQuote = StringUtils.replace(expectedMessage, "'", "");

            return expectedMessage.equals(event.getMessage()) || msgWithoutSingleQuote.equals(event.getMessage());
        }
        // Check the severity. This helps to distinguish between
        // different configurations for the same rule, where each
        // configuration has a different severity, like JavadocMetod.
        // See also http://jira.codehaus.org/browse/MCHECKSTYLE-41
        if (expectedSeverity != null) {
            return expectedSeverity.equals(event.getSeverityLevel().getName());
        }

        return true;
    }

public static String className(Class<?> clazz) { //todo: rename
        //todo: is that correct algorithm?
        final String naiveName = clazz.getName();
        if (!clazz.isArray()) { //todo: what about enum
            return naiveName;
        } else {
            int count = 0;
            String ending = "";
            while (clazz.isArray()) {
                count++;
                ending += "[]";
                clazz = clazz.getComponentType();
            }
            if (clazz.isPrimitive()) {
                String primitiveClassName;
                if (clazz == boolean.class) {
                    primitiveClassName = "boolean";
                } else if (clazz == byte.class) {
                    primitiveClassName = "byte";
                } else if (clazz == char.class) {
                    primitiveClassName = "char";
                } else if (clazz == short.class) {
                    primitiveClassName = "short";
                } else if (clazz == int.class) {
                    primitiveClassName = "int";
                } else if (clazz == long.class) {
                    primitiveClassName = "long";
                } else if (clazz == float.class) {
                    primitiveClassName = "float";
                } else if (clazz == double.class) {
                    primitiveClassName = "double";
                } else {
                    throw new RuntimeException("Never here! - You try to generate code for Void[]...[]: clazz = " + clazz);
                }
                return primitiveClassName + ending;
            } else {
                return naiveName.substring(count + 1, naiveName.length() - 1) + ending;
            }
        }
    }

private String createReceivedAtKey(String fromClusterName,
		String toClusterName) {

		return KEY_PREFIX + fromClusterName + "-" + toClusterName
			+ KEY_POSTFIX_DURATION;
	}

private void init() {
		try {
			debug("GuestNode#init(): Creating Cache");

			ClientCacheFactory clientCacheFactory = new ClientCacheFactory();

			Properties gemfireProperties = PropertiesHelper.filterProperties(
				System.getProperties(), GEMFIRE_PREFIX);

			for (Object keyObject : gemfireProperties.keySet()) {
				String key = (String) keyObject;
				String value = gemfireProperties.getProperty(key);

				String name = key.substring(GEMFIRE_PREFIX.length());

				debug("GuestNode#init(): Configuring ClientCacheFactory with key = "
					+ name + ", value = " + value);

				clientCacheFactory.set(name, value);
			}

			clientCacheFactory.setPoolSubscriptionEnabled(true);

			String locators = clustersProperties.getProperty(localClusterName);
			String[] locatorsArray = locators.split(",");
			for (String locator : locatorsArray) {
				String locatorHost = locator.substring(0, locator.indexOf("["));

				String locatorPortString = locator.substring(
					locator.indexOf("[") + 1, locator.indexOf("]"));
				int locatorPort = Integer.parseInt(locatorPortString);

				debug("GuestNode#init(): Adding locator to pool: locatorHost = "
					+ locatorHost + ", locatorPort = " + locatorPort);

				clientCacheFactory.addPoolLocator(locatorHost, locatorPort);
			}

			clientCache = clientCacheFactory.create();

			ClientRegionFactory<String, Long> clientRegionFactory = clientCache
				.createClientRegionFactory(ClientRegionShortcut.PROXY);

			region = clientCache.getRegion(regionName);

			debug("GuestNode#init(): Get region with name = " + regionName
				+ ": region = " + region);

			if (region == null) {
				region = clientRegionFactory.create(regionName);
			}
			debug("GuestNode#init(): Create region with name = " + regionName
				+ ": region = " + region);

		} catch (Throwable t) {
			debug(
				"GuestNode#init(): Throwable caught with message = "
					+ t.getMessage(), t);

		}
	}

private void waitForStarted() {
		debug("GuestNode#waitForStarted(): Waiting for other clusters started");

		while (true) {
			boolean othersStarted = true;

			for (Object key : clustersProperties.keySet()) {
				String clusterName = (String) key;

				Long startedAt = region.get(createStartedAtKey(clusterName));

				debug("GuestNode#waitForStarted(): Checking startedAt: startedAt = "
					+ startedAt
					+ ", processingStartedAt = "
					+ processingStartedAt);

				if ((startedAt == null)
					|| (startedAt.longValue() < processingStartedAt)) {

					othersStarted = false;
					break;

				}
			}

			if (othersStarted) {
				break;
			}

			try {
				TimeUnit.MILLISECONDS.sleep(CHECK_PERIOD);
			} catch (InterruptedException e) {
			}
		}

		debug("GuestNode#waitForStarted(): Other clusters started");
	}

private void waitForSent() {
		debug("GuestNode#waitForSent(): Waiting for other clusters sent");

		while (true) {
			boolean othersSent = true;

			Map<String, Long> clusterNameToReceivedAtMap = new HashMap<String, Long>();
			for (Object key : clustersProperties.keySet()) {
				String clusterName = (String) key;

				if (localClusterName.equals(clusterName)) {
					continue;
				}

				Long sentAt = region.get(createSentAtKey(clusterName));
				long receivedAt = System.currentTimeMillis();

				if ((sentAt != null)
					&& (sentAt.longValue() > processingStartedAt)) {

					clusterNameToReceivedAtMap.put(clusterName, receivedAt);
				}
			}

			for (Object key : clustersProperties.keySet()) {
				String clusterName = (String) key;

				if (localClusterName.equals(clusterName)) {
					continue;
				}

				Long receivedAt = clusterNameToReceivedAtMap.get(clusterName);

				if (receivedAt == null) {

					if (othersSent) {
						othersSent = false;
					}

				} else {
					region.put(
						createReceivedAtKey(clusterName, localClusterName),
						receivedAt);
				}
			}

			if (othersSent) {
				break;
			}

			try {
				TimeUnit.MILLISECONDS.sleep(CHECK_PERIOD);
			} catch (InterruptedException e) {
			}
		}

		debug("GuestNode#waitForSent(): Other clusters sent");
	}

private void waitForConnected() {
		debug("GuestNode#waitForConnected(): Waiting for all the clusters connected");

		while (true) {
			boolean connected = true;

			for (Object fromKey : clustersProperties.keySet()) {
				String fromClusterName = (String) fromKey;

				for (Object toKey : clustersProperties.keySet()) {
					String toClusterName = (String) toKey;

					if (fromClusterName.equals(toClusterName)) {
						continue;
					}

					Long receivedAt = region.get(createReceivedAtKey(
						fromClusterName, toClusterName));

					if (receivedAt == null) {
						connected = false;
						break;
					}
				}
			}

			if (connected) {
				break;
			}

			try {
				TimeUnit.MILLISECONDS.sleep(CHECK_PERIOD);
			} catch (InterruptedException e) {
			}
		}

		debug("GuestNode#waitForConnected(): All the clusters connected");
	}

public boolean waitFor(long timeout) {
		debug("GuestNode#waitFor(long): Waiting for task finish with timeout = "
			+ timeout);

		ProcessingTask connectionCheckTask = new ProcessingTask();

		Utils.execute(connectionCheckTask, timeout);

		boolean connected = connectionCheckTask.isConnected();

		debug("GuestNode#waitFor(long): Task finished connected = " + connected);

		return connected;
	}

public void close() {
		try {
			debug("GuestNode#close(): Closing the cache");

			clientCache.close();

			debug("GuestNode#close(): Cache closed = " + clientCache.isClosed());
		} catch (Throwable t) {
			debug(
				"GuestNode#close(): Throwable caught with message = "
					+ t.getMessage(), t);
		}
	}

public void printState(boolean connected) {
		if (!quiet) {

			StringBuilder sb = new StringBuilder();

			if (connected) {

				sb.append(localClusterName).append(" <= ");

				Iterator<Object> it = clustersProperties.keySet().iterator();
				while (it.hasNext()) {
					String clusterName = (String) it.next();

					if (localClusterName.equals(clusterName)) {
						continue;
					}

					Long sentAt = region.get(createSentAtKey(clusterName));
					Long receivedAt = region.get(createReceivedAtKey(
						clusterName, localClusterName));

					long duration = receivedAt - sentAt;

					sb.append("[").append(clusterName).append(", ")
						.append(duration).append("ms]");
				}

			} else {

				sb.append("Connection process is not finished for ").append(
					localClusterName);

			}

			System.out.println(sb.toString());

		}
	}

public static void main(String[] args) {
		try {
			if (args.length != 7) {
				Utils.exitWithFailure();
			}

			String cluster = args[0];
			Properties clustersProperties = PropertiesHelper
				.stringToProperties(args[1]);
			long timeout = Long.parseLong(args[2]);
			String regionName = args[3];
			boolean debugEnabled = ("true".equals(args[4]) ? true : false);
			boolean quiet = ("true".equals(args[5]) ? true : false);
			long processingStartedAt = Long.parseLong(args[6]);

			GuestNode guestNode = new GuestNode(cluster, clustersProperties,
				regionName, debugEnabled, quiet, processingStartedAt);

			boolean connected = guestNode.waitFor(timeout);

			guestNode.printState(connected);

			guestNode.close();

			if (connected) {
				Utils.exitWithSuccess();
			}

			Utils.exitWithFailure();
		} catch (Throwable t) {
			Utils.exitWithFailure();
		}
	}

private void debug(String message, Throwable t) {
		if (debugEnabled) {
			long currentTime = System.currentTimeMillis();
			long timeSinceProcessingStart = currentTime - processingStartedAt;
			System.err.println(timeSinceProcessingStart + " ["
				+ localClusterName + "] " + message);

			if (t != null) {
				t.printStackTrace(System.err);
			}
		}
	}

@Override
    @SuppressWarnings("PMD")
    protected String doRender(final RenderConfiguration config, final AbstractAttributes entity) {

        // Collect all non-null properties into a SortedMap using reflection.
        final SortedMap<String, String> dotAttributes = new TreeMap<>();

        for (Class<?> current = entity.getClass();
             current != null && current != Object.class;
             current = current.getSuperclass()) {

            for (Field currentField : current.getDeclaredFields()) {
                if (isConfigurationField(currentField)) {

                    String key = null;
                    Object value = null;

                    try {

                        // #1) Do we have a non-null value in the Field?
                        value = currentField.get(entity);
                        if (value == null) {
                            continue;
                        }

                        // #2) Do we have @DotProperty annotation on the Field?
                        final DotProperty dotPropertyAnnotation = currentField.getAnnotation(DotProperty.class);
                        if (dotPropertyAnnotation == null) {
                            continue;
                        }

                        // #3) Does this field need special treatment?
                        if (dotPropertyAnnotation.specialTreatment()) {

                            if ("labelSize".equals(currentField.getName())
                                    && PointOrRectangle.class.equals(currentField.getType())) {

                                final PointOrRectangle rect = (PointOrRectangle) value;
                                dotAttributes.put(quote("lwidth"),
                                        BigDecimal.valueOf(rect.getxOrWidth()).toPlainString());
                                dotAttributes.put(quote("lheight"),
                                        BigDecimal.valueOf(rect.getyOrHeight()).toPlainString());

                                // All Done for this Field.
                                continue;
                            }
                        }

                        // #4) Use the DotProperty "name" attribute, or fallback to the field name.
                        key = dotPropertyAnnotation.name();
                        if (key.isEmpty() || "##default".equalsIgnoreCase(key)) {
                            key = currentField.getName();
                        }

                        // #5) Transform the value if required, and add the key/value pair to the outbound Map.
                        dotAttributes.put(key, getDotConfigValueFor(value));

                    } catch (Exception e) {
                        throw new IllegalArgumentException("Could not add configuration for field ["
                                + currentField + "] --> [" + key + "] in class ["
                                + entity.getClass().getSimpleName() + "]", e);
                    }
                }
            }
        }

        // Check sanity
        if (dotAttributes.isEmpty()) {
            return "";
        }

        // Synthesize the required attribute List form.
        final StringBuilder builder = new StringBuilder(START_TOKEN);
        for (Map.Entry<String, String> current : dotAttributes.entrySet()) {
            builder.append(current.getKey() + SEPARATOR + "\"" + current.getValue() + "\"" + DELIMITER);
        }

        // Remove the last delimiter
        builder.delete(builder.length() - DELIMITER.length(), builder.length());

        // All Done.
        builder.append(END_TOKEN);
        return builder.toString();
    }

protected boolean initialize(final RootDoc rootDoc) {

        // #0) Don't initialize twice, unless required to.
        if (isInitializedOK) {
            return true;
        }

        // #1) Output the discovery log.
        for (String current : discoveryLog) {
            rootDoc.printNotice(current);
        }

        rootDoc.printNotice("GraphViz home: " + getHomeDirectory().getAbsolutePath());
        rootDoc.printNotice("Executable   : " + getExecutableNameOrPath());

        // #2) Create a ProcessBuilder which synthesizes a call to the executable and determine its version.
        //
        final ProcessBuilder pb = new ProcessBuilder(getExecutableNameOrPath(), "-V");
        pb.redirectErrorStream(true);
        if (homeDirectory != null) {
            pb.directory(homeDirectory);
        }

        Process p;
        try {

            // Launch the executable
            p = pb.start();
        } catch (IOException e) {

            rootDoc.printWarning(e.getMessage());
            return false;
        }

        try (BufferedReader in = new BufferedReader(new InputStreamReader(p.getInputStream()));
             OutputStream out = p.getOutputStream();) {

            // We don't need to send any more commands to the process, so close the output stream.
            out.close();

            // Read all input from the process, searching for the pattern "graphviz" ignoring case.
            String line = null;
            while ((line = in.readLine()) != null) {

                if (line.matches(GRAPHVIZ_EXECUTABLE_FIRST_LINE_CHECK)) {

                    // We found the expected output from the executable.
                    rootDoc.printNotice("GraphViz Version: " + line);
                    isInitializedOK = true;
                    return true;

                } else {

                    // Unknown output. Printout a warning and die.
                    rootDoc.printWarning("Unknown GraphViz output: " + line);
                }
            }

            // Cache the result.
            isInitializedOK = false;
            return false;

        } catch (IOException e) {

            // Nopes.
            rootDoc.printWarning("Problem detecting GraphViz: " + e.getMessage());
            isInitializedOK = false;
            return false;

        } finally {

            for (; ; ) {
                try {
                    p.waitFor();
                    break;
                } catch (InterruptedException e) {
                    // Ignore this
                }
            }
        }
    }

