public void writePngImageAndImageMap(final RootDoc rootDoc,
                                         final String dotDiagram,
                                         final File outputDirectory,
                                         final String filename) throws IOException {

        // Check sanity
        if (filename == null || filename.isEmpty()) {
            throw new IllegalArgumentException("Cannot handle null or empty 'filename' argument.");
        }
        if (rootDoc == null) {
            throw new IllegalArgumentException("Cannot handle null 'rootDoc' argument.");
        }

        // #0) Initialize
        if (!initialize(rootDoc)) {
            rootDoc.printWarning("Could not initialize DotFacade. Aborting writing PNG image and ImageMap files.");
        }

        // #1) Ensure that the PNG and MAP files can be written to.
        final File pngFile = new File(outputDirectory, filename + ".png");
        final File mapFile = new File(outputDirectory, filename + ".map");
        pngFile.delete();
        mapFile.delete();

        // #2) Compile the arguments used to launch Graphviz.
        final ProcessBuilder pb = new ProcessBuilder(
                getExecutableNameOrPath(),
                "-Tcmapx", "-o", mapFile.getAbsolutePath(),
                "-Tpng", "-o", pngFile.getAbsolutePath());
        pb.redirectErrorStream(true);
        if (getHomeDirectory() != null) {
            pb.directory(getHomeDirectory());
        }

        // #3) Launch Graphviz. Harvest output.
        final Process p = pb.start();
        try (final BufferedReader in = new BufferedReader(new InputStreamReader(p.getInputStream()));
             final Writer out = new OutputStreamWriter(p.getOutputStream(), AbstractExecutableFacade.UTF8_ENCODING)) {

            // Send the diagram to the process, and close the stream after that.
            out.write(dotDiagram);
            out.close();

            // Got error output?
            String line = null;
            while ((line = in.readLine()) != null) {
                System.err.println(line);
            }

        } finally {

            while (true) {
                try {
                    int result = p.waitFor();
                    if (result != 0) {
                        throw new IllegalStateException("GraphViz exited with a non-zero return value: " + result);
                    }
                    break;
                } catch (InterruptedException e) {
                    // Ignore
                }
            }
        }
    }

public List<XProperty> getOrderedProperties() {
        final List<XProperty> result = Introspector.getProperties(clazz);
        Collections.sort(result, new XProperty.NaturalOrder());
        return result;
    }

public short getVersionModelHashCode(int version) {
    	List<XProperty> classFields = getOrderedProperties();

        StringBuilder builder = new StringBuilder();
        for (XProperty field : classFields) {
            if (version == -1 || version >= field.getPropertyVersion()) {
                builder.append(field.getType()).append(field.getName());
            }
        }
        int hashCode = builder.toString().hashCode();
		return (short) ((hashCode & 0xFFFF ) ^ ((hashCode & 0xFFFF0000) >> 16)) ;
    }

public int getTotalNumberOfPages() throws QueryException {
		prepareResultData(false);
		if (isEmpty()) {
			return 1;
		}
		int total = totalNumberOfEntries / this.pageSize;
		if (totalNumberOfEntries % this.pageSize > 0) {
			total += 1;
		}
		return total;
	}

public List<V> page(int pageNumber) throws QueryException {
		List<Object> pageKeys = null;
		boolean firstTry = true;

		while (pageKeys == null) {
			prepareResultData(!firstTry);

			if (!pageExists(pageNumber)) {
				throw new IndexOutOfBoundsException("The page " + pageNumber
						+ "does not exists. " + +getTotalNumberOfPages()
						+ " pages available.");

			}

			PageKey pageKey = newKey(pageNumber);
			pageKeys = paginatedQueryInfoRegion.get(pageKey);

			if (pageKeys == null && firstTry) {
				firstTry = false;
			} else {
				break;
			}
		}

		if (pageKeys != null) {
			return getValues(pageKeys);
		} else {
			throw new RuntimeException(
					"Unable to load keys from cache. Too aggressive expiration policy?");
		}
	}

@SuppressWarnings("unchecked")
	private List<V> getValues(List<Object> entriesKeysForPage) {
		if (entriesKeysForPage.isEmpty()) {
			return Collections.emptyList();
		}
		Map<Object, V> entriesMap = queryRegion.getAll(entriesKeysForPage);

		List<V> entries = new ArrayList<V>(entriesKeysForPage.size());
		for (Object key : entriesKeysForPage) {
			entries.add(entriesMap.get(key));
		}
		return entries;
	}

@SuppressWarnings({ "unchecked" })
	private void prepareResultData(boolean force) throws QueryException {
		if (this.infoLoaded && !force) {
			return;
		}

		PageKey pageKey = newKey(PAGE_NUMBER_FOR_GENERAL_INFO);

		List<Object> queryInfo = null;
		if (!force) {
			queryInfo = paginatedQueryInfoRegion.get(pageKey);
		}

		if (queryInfo == null) {
			Query query = queryService.newQuery(this.queryString);
			SelectResults<Object> results = null;
			try {
				results = (SelectResults<Object>) query.execute(pageKey
						.getQueryParameters());
			} catch (FunctionDomainException e) {
				handleException(e);
			} catch (TypeMismatchException e) {
				handleException(e);
			} catch (NameResolutionException e) {
				handleException(e);
			} catch (QueryInvocationTargetException e) {
				handleException(e);
			}

			if (results.size() > queryLimit) {
				this.limitExceeded = true;
				this.totalNumberOfEntries = queryLimit;
				String msg = "Size of query results has exceeded limit ("
						+ queryLimit + "). Truncated.";
				logger.warn(msg);
			} else {
				limitExceeded = false;
				this.totalNumberOfEntries = results.size();
			}

			queryInfo = Arrays.asList(new Object[] { results.size(),
					limitExceeded });
			storePage(PAGE_NUMBER_FOR_GENERAL_INFO, queryInfo);

			List<Object> keys = extractKeys(results);
			storeResults(keys);
		} else {
			this.totalNumberOfEntries = (Integer) queryInfo.get(0);
			this.limitExceeded = (Boolean) queryInfo.get(1);
		}
		this.infoLoaded = true;
	}

private void storeResults(List<Object> resultKeys) {
		if (resultKeys.size() > queryLimit) {
			resultKeys = resultKeys.subList(0, queryLimit);
		}

		int keyNumber = 0;
		int pageNumber = 0;
		List<Object> page = new ArrayList<Object>();

		for (Object key : resultKeys) {
			if (keyNumber % getPageSize() == 0 && keyNumber != 0) {
				storePage(++pageNumber, page);
				page.clear();
			}
			page.add(key);
			keyNumber++;
		}

		if (page.size() > 0 || pageNumber == 0) {
			storePage(++pageNumber, page);
		}
	}

