public static Classifier consume(File file) throws PMMLConversionException {
        PMML pmml = null;
        try {
            if (isGzipped(file)) {
                logger.debug("Consuming GZipped PMML file '{}'.", file.getAbsolutePath());

                try (FileInputStream fis = new FileInputStream(file);
                     GZIPInputStream gzipInputStream = new GZIPInputStream(fis))
                {
                    pmml = JAXBUtil.unmarshalPMML(new StreamSource(gzipInputStream));
                }
            } else {
                logger.debug("Consuming PMML file '{}'.", file.getAbsolutePath());

                try (FileInputStream fis = new FileInputStream(file)) {
                    pmml = JAXBUtil.unmarshalPMML(new StreamSource(fis));
                }
            }
        } catch (Exception e) {
            throw new PMMLConversionException("Failed to unmarshal PMML file '" + file + "'. Make sure the file is a valid PMML.", e);
        }

        Algorithm algorithm = getAlgorithm(pmml);

        logger.debug("Consumed PMML file using algorithm {}.", algorithm);

        return algorithm.getPMMLConsumer().consume(pmml);
    }

private static boolean isGzipped(File file) throws IOException {
        FileInputStream fileInputStream = new FileInputStream(file);

        int head = (fileInputStream.read() & 0xff) | ((fileInputStream.read() << 8 ) & 0xff00 );

        return GZIPInputStream.GZIP_MAGIC == head;
    }

private static Algorithm getAlgorithm(PMML pmml) throws PMMLConversionException {
        for (Extension extension : pmml.getExtensions()) {
            if (ALGORITHM_EXTENSION_ELEMENT.equals(extension.getName())) {
                return Algorithm.valueOf(extension.getValue());
            }
        }

        throw new PMMLConversionException("Couldn't find '" + ALGORITHM_EXTENSION_ELEMENT + "' extension element in PMML.");
    }

public static Constructor pickSingletonConstructor(Class clazz) {
        Constructor<?>[] constructors = clazz.getConstructors();
        Constructor<?> constructor = null;
        // prefer a no-arg constructor
        int numParameters = 0;
        Constructor pick = null;
        boolean potentialConflict = false; // https://issues.jboss.org/browse/RESTEASY-645
        for (Constructor con : constructors) {
            if (Modifier.isPublic(con.getModifiers()) == false) {
                continue;
            }

            if (con.getParameterTypes().length >= numParameters) {
                if (con.getParameterTypes().length > numParameters) {
                    potentialConflict = false;
                }
                boolean noContextAnnotation = false;
                if (con.getParameterAnnotations() != null) {
                    for (Annotation[] ann : con.getParameterAnnotations()) {
                        if (FindAnnotation.findAnnotation(ann, Context.class) == null) {
                            noContextAnnotation = true;
                        }
                    }
                }
                if (noContextAnnotation)
                    continue;
                if (con.getParameterTypes().length == numParameters && numParameters != 0) {
                    potentialConflict = true;
                }
                numParameters = con.getParameterTypes().length;
                pick = con;

            }
        }
        if (potentialConflict) {
            // TODO logger.warn("Ambiguity constructors are found in " + clazz +
            // ". More details please refer to http://jsr311.java.net/nonav/releases/1.1/spec/spec.html");
        }
        return pick;
    }

