                return event.channel();
            }

            @Override
            public long id() {
                return event.id();
            }

            @Override
            public Object body() {
                return event.body();
            }

            @Override
            public boolean isSingleton() {
                return true;
            }

            @Override
            public MultiMap<String, String> params() {
                return event.params();
            }

            @Override
            public MultiMap<String, String> headers() {
                return event.headers();
            }

            /* Save a map lookup or building a header map. */
            @Override
