public List<Class<?>> enumerateClasses(URL propertiesFile, String prefix) {
    // find mapped service classes in service.properties
    Properties properties = new Properties();

    InputStream is = null;
    try {
      is = propertiesFile.openStream();

      if (is != null) {
        properties.load(is);
      }

    } catch (IOException e) {
      Log.warn(e.getMessage());

    } finally {
      if (is != null) {
        try {
          is.close();
        } catch (IOException ignore) {

        }
      }
    }

    List<Class<?>> classes = new ArrayList<Class<?>>();

    if (properties.size() > 0) {
      for (Object key : properties.keySet()) {
        if (key.toString().startsWith(prefix)) {
          try {
            // does the class resolve?
            Class<?> klass = Class.forName(properties.get(key).toString());

            // if so, add it
            classes.add(klass);

          } catch (ClassNotFoundException e) {
            Log.warn("Unable to find class [" + properties.get(key).toString() + "]");
          }
        }
      }
    }

    return classes;
  }

public void injectClasses(List<Class<?>> classes) {
    for (Class<?> klass : classes) {
      try {
        inject(klass);
      } catch (Exception e) {
        String msg = "Failed to inject: " + klass.getName().toString() + " - " + e.getMessage();
        Log.warn(msg);
        SystemUtils.trace("twine", msg);
      }
    }
  }

public void injectClasses(URL propertiesFile, String prefix) {
    List<Class<?>> classes = enumerateClasses(propertiesFile, prefix);
    injectClasses(classes);
  }

public int doFilter(Workspace ws, DataBinder binder, ExecutionContext ctx) throws DataException, ServiceException {

    Object returnVal = null;

    try {

      String methodID = (String) ctx.getCachedObject("filterParameter");

      Method m = MethodRegistry.getMethod(methodID);

      ParameterMarshaller marshaller = new ParameterMarshaller(m);

      Object[] params = marshaller.getValueArray(ws, binder, ctx);

      Object context = m.getDeclaringClass().newInstance();

      returnVal = m.invoke(context, params);

    } catch (IllegalArgumentException e) {

      throw new DataException(e.getMessage(), e);

    } catch (Exception e) {

      throw new ServiceException(e.getMessage(), e);
    }

    if (returnVal != null && returnVal instanceof Integer) {
      return ((Integer) returnVal).intValue();
    }

    return CONTINUE;
  }

public SQLiteDatabase getDatabaseConnection() {
		synchronized (LOCK) {
			if (dbConnection == null) {
				OPEN_CONNECTIONS.set(0);
				dbConnection = super.getWritableDatabase();
			}
			OPEN_CONNECTIONS.incrementAndGet();
			return dbConnection;
		}
	}

public void reduceDatabaseConnection() {
		synchronized (LOCK) {
			int numberOfOpenConnections = OPEN_CONNECTIONS.decrementAndGet();
			if (numberOfOpenConnections == 0 && dbConnection != null) {
				dbConnection.close();
				dbConnection = null;
			}
		}
	}

public <T> T functionOnDatabase(DbFunction<T> dbFunction) {
		SQLiteDatabase db = getDatabaseConnection();
		try {
			return dbFunction.apply(db);
		} finally {
			reduceDatabaseConnection();
		}
	}

public void consumeDatabase(DbConsumer dbConsumer) {
		SQLiteDatabase db = getDatabaseConnection();
		try {
			dbConsumer.consume(db);
		} finally {
			reduceDatabaseConnection();
		}
	}

