public boolean matches(String string) {
        String src = string;
        final boolean result;
        if (_compiledPattern.length == 1) {

            // Shortcut for pattern '*', '?' and patterns not containing any wildcard
            final GlobPattern pattern = _compiledPattern[0];
            if (pattern.getType() == GLOB_MULTIPLE) {
                result = true;
            } else if (pattern.getType() == GLOB_SINGLE) {
                result = src.length() == 1;
            } else {
                if (_caseInSensitive) {
                    result = src.equalsIgnoreCase(pattern.getText());
                } else {
                    result = src.equals(pattern.getText());
                }
            }

        } else if (_compiledPattern.length == 2) {

            // Shortcuts for common patterns '*something' and 'something*'
            final GlobPattern pattern1 = _compiledPattern[0];
            final GlobPattern pattern2 = _compiledPattern[1];
            if (_caseInSensitive) {
                src = src.toLowerCase();
            }
            if (pattern1.getType() == TEXT) {
                 result = src.startsWith(pattern1.getText()) && (pattern2.getType() == GLOB_MULTIPLE || src.length() == pattern1.getTextLength()+1);
            } else {
                result = src.endsWith(pattern2.getText()) && (pattern1.getType() == GLOB_MULTIPLE || src.length() == pattern2.getTextLength()+1);
            }

        } else {
            result = matches(src.toCharArray());
        }
        return result;
    }

private void compilePattern() throws ParseException {
        StringBuilder sb = new StringBuilder();
        boolean escaped = false;
        final List<GlobPattern> patterns = new ArrayList<>();
        for (int a = 0; a < _patternSource.length(); a++) {
            final char c = _patternSource.charAt(a);

            // Test escape-char
            if (c == '\\') {
                if (escaped) {
                    sb.append('\\');
                    escaped = false;
                } else {
                    escaped = true;
                }
            } else {
                if (escaped) {
                    if (c != GLOB_SINGLE && c != GLOB_MULTIPLE) {
                        sb.append("\\");
                    } else {

                        // Globbing chars escaped
                        sb.append(c);
                        escaped = false;
                    }
                } else {

                    // No escape character, test whether it matches on of the globbing characters.
                    if (c == GLOB_MULTIPLE || c == GLOB_SINGLE) {
                        if (sb.length() > 0) {
                            patterns.add(new GlobPattern(TEXT, sb.toString()));
                            sb = new StringBuilder();
                        }
                        patterns.add(new GlobPattern(c));
                    } else {
                        sb.append(c);
                    }
                }
            }
        }
        if (sb.length() > 0) {
            patterns.add(new GlobPattern(TEXT, sb.toString()));
        }

        // Add meta information and correct the elements
        addMetaInformation(patterns);

        _compiledPattern = new GlobPattern[patterns.size()];
        patterns.toArray(_compiledPattern);
    }

@Override
    @OverridingMethodsMustInvokeSuper
    protected void updateListAfterPut(CacheEntry<K, V> newEntry) {
        if (_last == null) {
            _last = newEntry;
            _first = newEntry;
        } else {
            _first.setPrevious(newEntry);
            newEntry.setNext(_first);
            setFirst(newEntry);
        }
    }

@Override
    protected void updateListAfterHit(CacheEntry<K, V> entry) {
        if (entry != null && !entry.equals(_first)) {
            if (entry.equals(_last)) {
                setLast(entry.getPrevious());
            } else {
                final CacheEntry<K, V> previous = entry.getPrevious();
                final CacheEntry<K, V> next = entry.getNext();

                previous.setNext(next);
                next.setPrevious(previous);
            }
            _first.setPrevious(entry);
            entry.setNext(_first);
            setFirst(entry);
        }
    }

protected void removeLast() {
        final CacheEntry<K, V> entry;
        synchronized (_lock) {
            if (_last != null) {
                entry = _entries.remove(_last.getKey());
                setLast(_last.getPrevious());
            } else {
                entry = null;
            }
            if (size() == 0) {
                _first = null;
                _last = null;
            }
        }
        if (entry != null) {
            handleRemove(entry);
        }
    }

@SuppressWarnings("UnnecessaryUnboxing")
    public void cleanUpLifetimeExpired() {
        final long currentTime = currentTimeMillis();
        // Test whether there could be an element that has to be removed
        if (_nearstExpiringTime > 0 && _nearstExpiringTime <= currentTime) {
            // Go through all elements and remove elements that are outdated
            final List<K> keysToRemove = new ArrayList<>();
            synchronized (_lock) {
                _nearstExpiringTime = 0;
                for (final CacheEntry<K, V> cacheEntry : _entries.values()) {
                    final Long expire = cacheEntry.getExpire();
                    if (expire != null) {
                        final long unboxedExpire = expire.longValue();
                        if (unboxedExpire <= currentTime) {
                            keysToRemove.add(cacheEntry.getKey());
                        } else if (_nearstExpiringTime == 0 || unboxedExpire < _nearstExpiringTime) {
                            _nearstExpiringTime = unboxedExpire;
                        }
                    }
                }
                for (final K key : keysToRemove) {
                    removeInternal(key);
                }
            }
        }
    }

byte[] generateReply(Message query, byte[] in, int length, Socket s)
        throws IOException {
        final Header header;
        final int maxLength;
        int flags = 0;

        header = query.getHeader();
        if (header.getFlag(Flags.QR)) {
            return null;
        }
        if (header.getRcode() != Rcode.NOERROR) {
            return errorMessage(query, Rcode.FORMERR);
        }
        if (header.getOpcode() != Opcode.QUERY) {
            return errorMessage(query, Rcode.NOTIMP);
        }

        final Record queryRecord = query.getQuestion();

        final TSIGRecord queryTSIG = query.getTSIG();
        TSIG tsig = null;
        if (queryTSIG != null) {
            tsig = _tsigs.get(queryTSIG.getName());
            if (tsig == null ||
                tsig.verify(query, in, length, null) != Rcode.NOERROR) {
                return formerrMessage(in);
            }
        }

        final OPTRecord queryOPT = query.getOPT();
        if (queryOPT != null && queryOPT.getVersion() > 0) {
        }

        if (s != null) {
            maxLength = 65535;
        } else if (queryOPT != null) {
            maxLength = Math.max(queryOPT.getPayloadSize(), 512);
        } else {
            maxLength = 512;
        }

        if (queryOPT != null && (queryOPT.getFlags() & ExtendedFlags.DO) != 0) {
            flags = FLAG_DNSSECOK;
        }

        final Message response = new Message(query.getHeader().getID());
        response.getHeader().setFlag(Flags.QR);
        if (query.getHeader().getFlag(Flags.RD)) {
            response.getHeader().setFlag(Flags.RD);
        }
        response.addRecord(queryRecord, Section.QUESTION);

        final Name name = queryRecord.getName();
        final int type = queryRecord.getType();
        final int dclass = queryRecord.getDClass();
        if (type == Type.AXFR && s != null) {
            return doAXFR(name, query, tsig, queryTSIG, s);
        }
        if (!Type.isRR(type) && type != Type.ANY) {
            return errorMessage(query, Rcode.NOTIMP);
        }

        final byte rcode = addAnswer(response, name, type, dclass, 0, flags);
        if (rcode != Rcode.NOERROR && rcode != Rcode.NXDOMAIN) {
            return errorMessage(query, rcode);
        }

        addAdditional(response, flags);

        if (queryOPT != null) {
            final int optflags = (flags == FLAG_DNSSECOK) ? ExtendedFlags.DO : 0;
            final OPTRecord opt = new OPTRecord((short) 4096, rcode, (byte) 0,
                optflags);
            response.addRecord(opt, Section.ADDITIONAL);
        }

        response.setTSIG(tsig, Rcode.NOERROR, queryTSIG);
        return response.toWire(maxLength);
    }

@Override
    protected void updateListAfterPut(CacheEntry<K, V> newEntry) {
        newEntry.setPrevious(_last);
        if (_last != null) {
            _last.setNext(newEntry);
        }
        setLast(newEntry);
    }

@Override
    protected void updateListAfterHit(CacheEntry<K, V> entry) {
        if (entry != null && !entry.equals(_first)) {
            if (entry.getHits() > entry.getPrevious().getHits()) {

                // Swap the positions
                final CacheEntry<K, V> beforePrevious = entry.getPrevious().getPrevious();
                final CacheEntry<K, V> previous = entry.getPrevious();
                final CacheEntry<K, V> next = entry.getNext();

                if (beforePrevious != null) {
                    beforePrevious.setNext(entry);
                } else {
                    _first = entry;
                }
                entry.setPrevious(beforePrevious);

                previous.setPrevious(entry);
                previous.setNext(next);

                entry.setNext(previous);

                if (next == null) {
                    setLast(previous);
                } else {
                    next.setPrevious(previous);
                }
            }
        }
    }

@Nonnull
    public static <K, V> Map<K, V> putAll(@Nonnull Map<K, V> original, @Nullable Object... a) {
        if (a != null) {
            final int length = a.length;
            if (length % 2 == 1) {
                throw new IllegalArgumentException("You must provide an even number of arguments.");
            }
            for (int i = 0; i < length; i += 2) {
                // noinspection unchecked
                original.put((K) a[i], (V) a[i + 1]);
            }
        }
        return original;
    }

@Nonnull
    public static <K, V> Map<K, V> asMap(@Nullable Object... a) {
        return putAll(new LinkedHashMap<K, V>(), a);
