public static boolean startsWith(char[] src, char[] find, int startAt) {
        int startPos = startAt;
        boolean result = true;

        // Check ranges
        if (src.length < startPos + find.length) {
            result = false;
        } else {
            final int max = find.length;
            for (int a = 0; a < max && result; a++) {
                if (src[startPos] != find[a]) {
                    result = false;
                }
                startPos++;
            }
        }
        return result;
    }

@SuppressWarnings({"MethodWithMultipleReturnPoints", "LabeledStatement", "ValueOfIncrementOrDecrementUsed", "ContinueStatement", "ContinueStatementWithLabel"})
    public static int indexOf(char[] src, char[] find, int startAt) {
        int startPos = startAt;
        final int max = src.length - find.length;
        if (startPos > max) {
            return -1;
        }
        final char find0 = find[0];
        final int len = find.length;
        int j;
        int k;

        // Find the first character
        startOver:
        while (startPos <= max) {
            if (src[startPos++] == find0) {
                // First character found - look for the rest
                j = startPos;
                k = 1;
                while (k < len) {
                    if (src[j++] != find[k++]) {
                        continue startOver;
                    }
                }
                return startPos - 1;
            }
        }
        return -1;
    }

public static void log(@Nonnull Logger logger, @Nonnull LogLevel level, @Nonnull String format, @Nullable Object arg) {
        if (logger instanceof LocationAwareLogger) {
            log((LocationAwareLogger) logger, level, FQCN, null, format, new Object[]{arg}, null);
        } else if (trace.equals(level)) {
            logger.trace(format, arg);
        } else if (debug.equals(level)) {
            logger.debug(format, arg);
        } else if (info.equals(level)) {
            logger.info(format, arg);
        } else if (warning.equals(level)) {
            logger.warn(format, arg);
        } else if (error.equals(level) || fatal.equals(level)) {
            logger.error(format, arg);
        } else {
            log(logger, normalize(level), format, arg);
        }
    }

public static boolean isEnabled(@Nonnull Logger logger, @Nonnull LogLevel level, @Nonnull Marker marker) {
        final boolean result;
        if (trace.equals(level)) {
            result = logger.isTraceEnabled(marker);
        } else if (debug.equals(level)) {
            result = logger.isDebugEnabled(marker);
        } else if (info.equals(level)) {
            result = logger.isInfoEnabled(marker);
        } else if (warning.equals(level)) {
            result = logger.isWarnEnabled(marker);
        } else if (error.equals(level) || fatal.equals(level)) {
            result = logger.isErrorEnabled(marker);
        } else {
            result = isEnabled(logger, normalize(level), marker);
        }
        return result;
    }

