public String toQueryString(Criteria criteria, CriteriaQueryBuilder queryBuilder) {

    // check whether list is empty
    if( projectionList.isEmpty() ) {
      throw new IllegalStateException("A projection list must have at least one child.");
    }

    // query builder
    StringBuilder builder = new StringBuilder();

    // iterate over all projections from the list
    Iterator<Projection> iter = projectionList.iterator();
    while( iter.hasNext() ) {
      Projection projection = iter.next();

      // call toQueryString() on child
      builder.append( projection.toQueryString(criteria, queryBuilder) );

      // append comma if more projections follow
      if(iter.hasNext()) {
        builder.append(",");
      }
    }

    // return result
    return builder.toString();
  }

public String toGroupByString(Criteria criteria, CriteriaQueryBuilder queryBuilder) {

    // query builder
    StringBuilder builder = new StringBuilder();

    // iterate over all projections from the list
    Iterator<Projection> iter = projectionList.iterator();
    while( iter.hasNext() ) {
      Projection projection = iter.next();

      // call toGroupByString() on child
      String groupBy = projection.toGroupByString(criteria, queryBuilder);

      // add only if result is not null
      if(groupBy != null && groupBy.trim().length() > 0) {

        // first add a comma if the builder already contains something
        if(builder.length() > 0) {
          builder.append(",");
        }

        // add group by expression of child
        builder.append(groupBy);

      }

    }

    // return result if something has been written to the builder
    String result = builder.toString().trim();
    if(result.length() > 0) {
      return result;
    }

    return null;
  }

public static String md5(String text) {
        if (text == null) {
            return null;
        }
        if (text.length() == 0) {
            return "";
        }
        try {
            md1.update(text.getBytes("UTF8"));
            return hex(md1.digest());
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

public static String sha(String text) {
        if (text == null) {
            return null;
        }
        if (text.length() == 0) {
            return "";
        }
        try {
            md2.update(text.getBytes("UTF8"));
            return hex(md2.digest());
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

private static String hex(byte[] arr) {
        StringBuffer sb = new StringBuffer();
        for (int i = 0; i < arr.length; ++i) {
            sb.append(Integer.toHexString((arr[i] & 0xFF) | 0x100).substring(1,
                    3));
        }
        return sb.toString();
    }

public static boolean hasNewVersion(String oldVersion, String newVersion) {
        //版本号有一个不正常就返回false
        if (CBStringUtil.isEmptyOrNull(oldVersion) || CBStringUtil.isEmptyOrNull(newVersion)) {
            return false;
        }

        boolean res = false;
        String[] oldVersionSnippet = oldVersion.split("\\.");
        String[] newVersionSnippet = newVersion.split("\\.");
        int maxComparePosition = Math.min(oldVersionSnippet.length, newVersionSnippet.length);

        int i = 0;
        for (; i < maxComparePosition; i++) {
            int newNumber = Integer.parseInt(newVersionSnippet[i]);
            int oldNumber = Integer.parseInt(oldVersionSnippet[i]);

            if (newNumber == oldNumber) {
                continue;
            }

            if (newNumber > oldNumber) {
                res = true;
                break;
            }

            if (newNumber < oldNumber) {
                res = false;
                break;
            }
        }

        //前面的都相等,比较长度
        if (i == maxComparePosition) {
            res = newVersionSnippet.length > oldVersionSnippet.length;
        }

        return res;
    }

