private static Properties getFilterInitParameters(final FilterConfig config) {

		Properties props = new Properties();

		Enumeration en = config.getInitParameterNames();

		while (en.hasMoreElements()) {

			String key = (String)en.nextElement();
			String value = config.getInitParameter(key);

			props.setProperty(key, value);
		}

		return props;
	}

public void init(final FilterConfig filterConfig)
		throws ServletException {

		// Get the init params
		Properties props = getFilterInitParameters(filterConfig);

		// Extract and parse all required CORS filter properties
		try {
			config = new CORSConfiguration(props);

		} catch (CORSConfigurationException e) {

			throw new ServletException(e);
		}

		handler = new CORSRequestHandler(config);
	}

private void printMessage(final HttpServletResponse response, final int sc, final String msg)
		throws IOException, ServletException {

		// Set the status code
		response.setStatus(sc);


		// Write the error message

		response.resetBuffer();

		response.setContentType("text/plain");

		PrintWriter out = response.getWriter();

		out.println("Cross-Origin Resource Sharing (CORS) Filter: " + msg);
	}

private void doFilter(final HttpServletRequest request, final HttpServletResponse response, final FilterChain chain)
		throws IOException, ServletException {

		// Tag
		handler.tagRequest(request);

		CORSRequestType type = CORSRequestType.detect(request);

		try {
			if (type == CORSRequestType.ACTUAL) {
				// Simple/actual CORS request
				handler.handleActualRequest(request, response);
				chain.doFilter(request, response);
			}
			else if (type == CORSRequestType.PREFLIGHT) {
				// Preflight CORS request, handle but don't pass
				// further down the chain
				handler.handlePreflightRequest(request, response);
			}
			else if (config.allowGenericHttpRequests) {
				// Not a CORS request, but allow it through
				request.setAttribute("cors.isCorsRequest", false); // tag
				chain.doFilter(request, response);
			}
			else {
				// Generic HTTP requests denied
				request.setAttribute("cors.isCorsRequest", false); // tag
				printMessage(response, HttpServletResponse.SC_FORBIDDEN, "Generic HTTP requests not allowed");
			}

		} catch (InvalidCORSRequestException e) {

			request.setAttribute("cors.isCorsRequest", false); // tag
			printMessage(response, HttpServletResponse.SC_BAD_REQUEST, e.getMessage());

		} catch (CORSOriginDeniedException e) {

			String msg = e.getMessage() + ": " + e.getRequestOrigin();
			printMessage(response, HttpServletResponse.SC_FORBIDDEN, msg);

		} catch (UnsupportedHTTPMethodException e) {

			String msg = e.getMessage();

			HTTPMethod method = e.getRequestedMethod();

			if (method != null)
				msg = msg + ": " + method.toString();

			printMessage(response, HttpServletResponse.SC_METHOD_NOT_ALLOWED, msg);

		} catch (UnsupportedHTTPHeaderException e) {

			String msg = e.getMessage();

			HeaderFieldName header = e.getRequestHeader();

			if (header != null)
				msg = msg + ": " + header.toString();

			printMessage(response, HttpServletResponse.SC_FORBIDDEN, msg);
		}
	}

public void created(final UUID createdByEntityId) {
		if (this.entityId != null) {
			throw new IllegalStateException("This entity has already been created: entityId = " + entityId);
		}
		this.entityId = UUID.randomUUID();
		this.entityVersion = 1;
		this.createdByEntityId = createdByEntityId;
		this.updatedByEntityId = createdByEntityId;
		this.entityCreatedOn = System.currentTimeMillis();
		this.entityUpdatedOn = this.entityCreatedOn;
	}

@SuppressWarnings("incomplete-switch")
	@Override
	public void init(InputStream json) throws IOException {
		try (final JsonParser parser = JsonUtils.createJsonParser(json)) {
			JsonToken tk;
			while ((tk = parser.nextToken()) != null) {
				switch (tk) {
				case FIELD_NAME:
					final String fieldName = parser.getCurrentName();
					if (fieldName.equals("entityId")) {
						setEntityId(UUID.fromString(parser.nextTextValue()));
					} else if (fieldName.equals("entityVersion")) {
						setEntityVersion(parser.nextLongValue(0));
					} else if (fieldName.equals("entityCreatedOn")) {
						setEntityCreatedOn(parser.nextLongValue(0));
					} else if (fieldName.equals("createdByEntityId")) {
						setCreatedBy(UUID.fromString(parser.nextTextValue()));
					} else if (fieldName.equals("entityUpdatedOn")) {
						setEntityUpdatedOn(parser.nextLongValue(0));
					} else if (fieldName.equals("updatedByEntityId")) {
						setUpdatedBy(UUID.fromString(parser.nextTextValue()));
					} else {
						init(parser);
					}
					break;
				}
			}
		}

	}

protected void init(JsonParser parser) throws IOException {
		LoggerFactory.getLogger(getClass()).warn("init(JsonParser parser) invoked to handle field: {}", parser.getCurrentName());
	}

public void updated(final UUID lastupdatedByEntityId) {
		if (this.entityId == null) {
			throw new IllegalStateException("The entity has not yet been created : entityId == null");
		}
		Assert.notNull(lastupdatedByEntityId, "lastupdatedByEntityId is required");
		entityVersion++;
		updatedByEntityId = lastupdatedByEntityId;
		entityUpdatedOn = System.currentTimeMillis();
	}

private Collection<DuplicateCode> convert(final List<Duplication> duplications, final String moduleName) {
        List<DuplicateCode> annotations = new ArrayList<DuplicateCode>();

        for (Duplication duplication : duplications) {
            List<DuplicateCode> codeBlocks = new ArrayList<DuplicateCode>();
            boolean isDerived = false;
            for (SourceFile file : duplication.getFiles()) {
                // TODO: check why PMD reports a length + 1
                DuplicateCode annotation = new DuplicateCode(getPriority(duplication.getLines()), file.getLine(), duplication.getLines(), file.getPath(), isDerived);
                annotation.setSourceCode(duplication.getCodeFragment());
                annotation.setModuleName(moduleName);
                codeBlocks.add(annotation);
                isDerived = true;
            }
            for (DuplicateCode block : codeBlocks) {
                block.linkTo(codeBlocks);

                block.setPackageName(PackageDetectors.detectPackageName(block.getFileName()));
            }
            annotations.addAll(codeBlocks);
        }
        return annotations;
    }

@Override
    public void registerService(ISemanticLocator packedServiceDescriptor) throws ServiceExecutionException
    {
        try
        {

            BSDFLogger.getLogger().info("Deploys service(s) from: " + packedServiceDescriptor.toString());

            Collection<ISemanticIdentifier> deployedServices = this.deploy(packedServiceDescriptor, bsdmServiceRegistry);

            for (ISemanticIdentifier deployedService : deployedServices)
            {
                this.messageBroker.registerService(
                        this.bsdmServiceRegistry.getService(deployedService).applyConnectorURL(this.urlContainer));
            }

        } catch (ModelException ex)
        {
            BSDFLogger.getLogger().debug("Cannot deploy service(s) from: " + packedServiceDescriptor.toString()
                    + " . Exception: " + ex.toString());
            throw new ServiceExecutionException(ex.getMessage(), ex);
        }
    }

@Transactional
	protected HashServiceConfiguration hashServiceConfiguration() {
		Exception exception = null;
		for (int i = 0; i < 3; i++) {
			final HashServiceConfiguration config = hashServiceConfigurationDAO.findByName(getHashServiceConfigurationName());
			if (config != null) {
				return config;
			}

			try {
				return hashServiceConfigurationDAO.create(newHashServiceConfiguration());
			} catch (Exception e) {
				exception = e;
				try {
					Thread.sleep((long) (Math.random() * 1000));
				} catch (InterruptedException e2) {
					// ignore
				}
			}
		}

		throw new RuntimeException("hashServiceConfiguration() failed", exception);
	}

public void close( int port ) {
    for (Iterator i = _listeners.keySet().iterator(); i.hasNext(); ) {
      Object k = i.next();
      Object s = _listeners.get(k);
      if (s instanceof SocketHandler) {
        SocketHandler sh = (SocketHandler)s;
        if (port == -1 || sh.isPort( port )) {
          sh.interrupt();
          sh.close();
          _transactions.remove( s );
          _listeners.remove( k );
        }
      }
    }
  }

protected void receive( Command c, Map h, String b, Authenticatable y ) {
    long id = (int)(Math.random() * 10000);
    try {
      // Convert to MESSAGE and distribute
      if (c == Command.COMMIT) {
        synchronized (_transactions) {
          List trans = (List)_transactions.remove(y);
          trans = new ArrayList( trans );
          for (Iterator i=trans.iterator(); i.hasNext(); ) {
            Message m = (Message)i.next();
            try {
              receive( m.command(), m.headers(), m.body(), y );
            } catch (Exception e) {
              // Don't allow listener code to break us
            }
          }
        }

      } else if (c == Command.ABORT) {
        synchronized (_transactions) {
          _transactions.remove(y);
        }

      } else if (_transactions.get( y ) != null) {
        synchronized (_transactions) {
          ((List)_transactions.get( y )).add( new Message( c, h, b ) );
        }

      } else {
        if (h == null) h = new HashMap();
        String destination = (String)h.get("destination");
        if (c == Command.SEND) {
          if (y instanceof IntraVMClient ||
              _authenticator.authorizeSend( y.token(), destination )) {
            synchronized( _listeners ) {
              List l = (List)_listeners.get( destination );
              if (l != null) {
                l = new ArrayList(l);
                for (Iterator i = l.iterator(); i.hasNext(); ) {
                  Listener sh = (Listener)i.next();
                  try {
                    sh.message( h, b );
                  } catch (Exception e) {
                    // Don't allow listener code to break us
                  }
                }
              } 
            }
          } else {
            Map error_headers = new HashMap();
            error_headers.put( "message:", "authorization refused");
            error_headers.put( "type:", "send");
            error_headers.put( "channel:", destination);
            y.error( error_headers, "The message:\n-----\n"+b+
                "\n-----\nAuthentication token refused for this channel");
          }

        } else if (c == Command.SUBSCRIBE) {
          if (y instanceof IntraVMClient ||
              _authenticator.authorizeSubscribe( y.token(), destination )) {
            synchronized (_listeners ) {
              List l = (List)_listeners.get( destination );
              if (l == null) {
                l = new ArrayList();
                _listeners.put( destination, l );
              }
              if (!l.contains(y)) l.add( y );
            }
          } else {
            Map error_headers = new HashMap();
            error_headers.put( "message:", "authorization refused");
            error_headers.put( "type:", "subscription");
            error_headers.put( "channel:", destination);
            y.error( error_headers, "The message:\n-----\n"+b+
                "\n-----\nAuthentication token refused for this channel");
          }

        } else if (c == Command.UNSUBSCRIBE) {
          synchronized (_listeners) {
            List l = (List)_listeners.get( destination );
            if (l != null) l.remove( y );
          }

        } else if (c == Command.BEGIN) {
          synchronized (_transactions) {
            List trans = new ArrayList();
            _transactions.put( y, trans );
          }

        } else if (c == Command.DISCONNECT) {
          synchronized (_listeners) {
            for (Iterator i=_listeners.values().iterator(); i.hasNext(); ) {
              List l = (List)i.next();
              l.remove( y );
            }
          }
        }
      }
      if (h != null) {
        String receipt = (String)h.get("receipt");
        if (receipt != null) {
          HashMap headers = new HashMap();
          headers.put( "receipt-id", receipt );
          y.receive( Command.RECEIPT, headers, null );
        }
      }
    } catch (Exception e) {
      // Don't allow listener code to break us
    }
  }

