                //而后再遍历lib/poms下面的pom.xml，把packaging = pom 的父pom预加载进来
                scanPomsJar(pomsJar);
            } catch (Exception e) {
                logger.error("Failed to scan poms.jar in {}: {}", poms, e.getMessage());
            }
        logger.info(banner("Scanned  jars"));
