public Set<ResourceSelection> checkDiff(final ResourceSelectionSet target) {
		// 更新信息列表
		Set<ResourceSelection> diffs = new HashSet<>();

		// 读取源版本
		Set<ResourceSelection> sourceEntrys = selections;
		if (LOG.isDebugEnabled()) {
			LOG.debug("源版本：{}", sourceEntrys);
		}

		// 读取目标版本
		Set<ResourceSelection> targetEntrys = target.selections;
		if (LOG.isDebugEnabled()) {
			LOG.debug("目标版本：{}", targetEntrys);
		}

		// 处理是否更新
		diffs.addAll(targetEntrys);
		diffs.removeAll(sourceEntrys);

		if (LOG.isDebugEnabled()) {
			LOG.debug("更新结果：{}", diffs);
		}
		return diffs;
	}

public static CodedMessageDefinition getDefinition(final String code) {
		Map<Locale, CodedMessageDefinition> definitions = DEFINITIONS.get(code);
		if (definitions == null) {
			return null;
		}

		CodedMessageDefinition definition = definitions.get(Locales.current());
		if (definition == null) {
			definition = definitions.get(Locale.ROOT);
		}
		return definition;
	}

public static void define(final CodedMessageDefinition definition) {
		String code = definition.getCode();
		Locale locale = definition.getLocale();

		Map<Locale, CodedMessageDefinition> definitions = DEFINITIONS.get(code);
		if (definitions == null) {
			definitions = new HashMap<>();
			DEFINITIONS.put(code, definitions);
		}
		definitions.put(locale, definition);
	}

