public Resource getResource(final ResourceSelection selection) {
		if (LOG.isTraceEnabled()) {
			LOG.trace("定位资源：{}", selection);
		}
		String catalog = selection.getCatalog();
		String version = selection.getVersion();
		String name = selection.getName();

		String path = catalog;
		if (StringUtils.isNotBlank(version)) {
			path = path + '/' + version;
		}
		while (true) {
			try {
				Resource resource = root.createRelative(path + '/' + name);
				if (resource.exists()) {
					if (LOG.isTraceEnabled()) {
						LOG.trace("定位资源到：{}", resource);
					}
					return resource;
				}
			} catch (IOException e) {
				LOG.warn(root.toString() + '/' + path + '/' + name + " 解析失败", e);
				return null;
			}
			if (path.length() <= catalog.length()) {
				break;
			}
			path = path.substring(0, path.lastIndexOf('/'));
		}
		if (LOG.isDebugEnabled()) {
			LOG.debug("未找到资源：{}", selection);
		}
		return null;
	}

public boolean hasLevel(final CodedMessageLevel targetLevel) {
		if (level == targetLevel) {
			return true;
		}
		for (CodedMessage message : messages) {
			if (message.hasLevel(targetLevel)) {
				return true;
			}
		}
		return false;
	}

private void format(final StringBuilder sb) {
		CodedMessageDefinition def = CodedMessageDefinition.getDefinition(code);
		if (def == null) {
			sb.append(MessageFormats.formatFallback(code, arguments.toArray()));
		} else {
			sb.append(MessageFormats.format(def.getTemplate(), def.getLocale(), arguments.toArray()));
		}
		for (String unformattedArgument : unformattedArguments) {
			sb.append('，');
			sb.append(unformattedArgument);
		}
	}

public String formatAll() {
		StringBuilder sb = new StringBuilder();
		formatAll(sb, 0);
		sb.deleteCharAt(sb.length() - 1);
		return sb.toString();
	}

private void formatAll(final StringBuilder sb, final int depth) {
		for (int i = 0; i < depth; i++) {
			sb.append('\t');
		}
		format(sb);
		sb.append('\n');
		for (CodedMessage message : messages) {
			message.formatAll(sb, depth + 1);
		}
	}

