public static ObjectName getObjectName(Class interfaceClass, String key, String value) {

        // Set the table.
        Hashtable<String,String> table = new Hashtable<String,String>();
        table.put(key, value);

        return getObjectName(interfaceClass, table);
    }

public static ObjectName getObjectName(Class interfaceClass, Hashtable<String,String> table) {



        // Check if the interface class is valid.
        if (interfaceClass == null) {
            throw new IllegalArgumentException("The interface class is invalid.");
        }

        ObjectName objectName;

        try {

            // Check if the table is null.
            if (table == null) {

                // Initialize the table.
                table = new Hashtable<String,String>();
            }

            // Add the "type" to the table.
            table.put("type", interfaceClass.getSimpleName());

            // Get the MBean object name.
            objectName = ObjectName.getInstance(interfaceClass.getPackage().getName(), table);
        } catch (MalformedObjectNameException e) {
            throw new IllegalArgumentException(
                    "Unable to get the MBean object name for "
                    + interfaceClass.getName() + ".", e);
        }

        return objectName;
    }

public static <T> ObjectName register(Class<T> interfaceClass) throws MBeanException {
        return register(interfaceClass, getObjectName(interfaceClass));
    }

public static <T> ObjectName register(Class<T> interfaceClass, String key, String value) throws MBeanException {
        return register(interfaceClass, getObjectName(interfaceClass, key, value));
    }

public static <T> ObjectName register(Class<T> interfaceClass, Hashtable<String,String> table) throws MBeanException {
        return register(interfaceClass, getObjectName(interfaceClass, table));
    }

public static <T> ObjectName register(Class<T> interfaceClass, ObjectName objectName) throws MBeanException {

        // Check if the interface class is valid.
        if (interfaceClass == null) {
            throw new IllegalArgumentException("The interface class is invalid.");
        }

        try {

            // Get the MBean server.
            MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();

            // Check if the MBean is not registered with the MBean server.
            if (!mBeanServer.isRegistered(objectName)) {

                // Register the MBean with the MBean server.
                ObjectInstance objectInstance = mBeanServer.registerMBean(createObject(interfaceClass), objectName);

                // Get the object name for the registered MBean.
                objectName = objectInstance.getObjectName();
            }
        } catch (Exception e) {
            throw new MBeanException(e, "Unable to register the MBean.");
        }

        return objectName;
    }

public static void unregister(ObjectName objectName) throws MBeanException {

        try {

            // Get the MBean server.
            MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();

            // Check if the MBean is registered with the MBean server.
            if (mBeanServer.isRegistered(objectName)) {

                // Unregister the MBean with the MBean server.
                mBeanServer.unregisterMBean(objectName);
            }
        } catch (Exception e) {
            throw new MBeanException(e, 
                    "Unable to unregister the MBean " +
                    objectName.getCanonicalName() + ".");
        }
    }

protected static void validateMBean(Class interfaceClass, ObjectName objectName, MBeanServerConnection mBeanServerConnection)  throws MBeanException {

        try {

            // Check if the interface class is null.
            if (interfaceClass == null) {
                throw new IllegalArgumentException(
                        "The interface class is null.");
            }

            // Check if the interface class is not a MXBean interface.
            if (!JMX.isMXBeanInterface(interfaceClass)) {
                throw new IllegalArgumentException(
                        "The interface class " + interfaceClass.getName() +
                        " is not a MXBean interface.");
            }

            // Check if the object name is not registered.
            if (!mBeanServerConnection.isRegistered(objectName)) {
                throw new IllegalArgumentException(
                        "The object name " + objectName.getCanonicalName() +
                        " is not registered.");
            }

            // Check if the object name is not an instance of the interface class.
            if (!mBeanServerConnection.isInstanceOf(objectName, interfaceClass.getName())) {
                throw new IllegalArgumentException(
                        "The object name " + objectName.getCanonicalName() +
                        " is not an instance of the interface class " +
                        interfaceClass.getName() + ".");
            }
        } catch (InstanceNotFoundException e) {
            throw new IllegalArgumentException(
                    "The object name " + objectName.getCanonicalName() +
                    " is not found.");
        } catch (IOException e) {
            throw new MBeanException(e,
                    "Unable to validate the MBean represented by the interface class " +
                    interfaceClass.getName() + " and object name " +
                    objectName.getCanonicalName() + ".");
        }
    }

@Override
    public void initialize(Bootstrap<PlatformConfiguration> bootstrap) {
        for (Initializer initializer : wrapper.getInitializers()) {
            initializer.initialize(bootstrap);
            LOGGER.debug("Registered Initializer: {}", initializer.getClass().getCanonicalName());
        }

        for (Bundle bundle : wrapper.getBundles()) {
            bootstrap.addBundle(bundle);
            LOGGER.debug("Registered Bundle: {}", bundle.getClass().getCanonicalName());
        }

        for (Command command : wrapper.getCommands()) {
            bootstrap.addCommand(command);
            LOGGER.debug("Registered Command: {}", command.getClass().getCanonicalName());
        }
    }

@Override
    public void run(PlatformConfiguration configuration, Environment environment) throws Exception {
        dropwizardModule.setup(configuration, environment);

        for (Configurator configurator : wrapper.getConfigurators()) {
            configurator.configure(configuration, environment);
            LOGGER.debug("Registered Configurator: {}", configurator.getClass().getCanonicalName());
        }

        for (Object jerseyComponent : wrapper.getJerseyComponents()) {
            environment.jersey().register(jerseyComponent);
            LOGGER.debug("Registered Jersey Component: {}", jerseyComponent.getClass().getCanonicalName());
        }

        for (Managed managed : wrapper.getManaged()) {
            environment.lifecycle().manage(managed);
            LOGGER.debug("Registered Managed Object: {}", managed.getClass().getCanonicalName());
        }

        for (HealthCheck healthCheck : wrapper.getHealthChecks()) {
            environment.healthChecks().register(healthCheck.toString(), healthCheck);
            LOGGER.debug("Registered Health Check: {}", healthCheck.getClass().getCanonicalName());
        }

        for (Task task : wrapper.getTasks()) {
            environment.admin().addTask(task);
            LOGGER.debug("Registered Task: {}", task.getClass().getCanonicalName());
        }

        for (FilterSpec filterSpec : wrapper.getFilterSpecs()) {
            registerFilterSpec(environment, filterSpec);

            LOGGER.debug("Registered Filter {}: {}",
                    filterSpec.getName(),
                    filterSpec.getFilter().getClass().getCanonicalName());
        }
    }

@Override
    public String get() {

        try (final Timer.Context context = timer.time()) {
            final String s = randomUUID().toString();

            if (length == 0 || count == 0) {
                return s;
            }

            final StringJoiner joiner = new StringJoiner("/", "", "/" + s);
            IntStream.rangeClosed(0, count - 1)
                     .forEach(x -> joiner.add(s.substring(x * length, (x + 1) * length)));

            return joiner.toString();
        }
    }

public static void loadDefinitions(final ResourcePatternResolver resolver, final String locationPattern) {
		try {
			Resource[] resources = resolver.getResources(locationPattern);
			for (Resource resource : resources) {
				String filename = resource.getFilename();
				Locale locale = Locale.ROOT;
				String filenamePrefix = "codedMessageDefinition_";
				if (filename.startsWith(filenamePrefix)) {
					locale = LocaleUtils.toLocale(filename.substring(filenamePrefix.length(), filename.lastIndexOf(".xml")));
				}
				loadDefinitions(locale, resource);
			}
		} catch (IOException e) {
			LOG.error("加载失败", e);
		}
	}

public static void loadDefinitions(final Locale locale, final Resource resource) {
		try {
			XMLConfiguration config = new XMLConfiguration();
			config.setDelimiterParsingDisabled(true);
			config.load(resource.getInputStream());
			for (HierarchicalConfiguration definitionConfig : config.configurationsAt("definition")) {
				String code = definitionConfig.getString("[@code]");
				String template = definitionConfig.getString("[@template]");
				CodedMessageDefinition.define(new CodedMessageDefinition(code, locale, template));
			}
		} catch (IOException e) {
			LOG.error("加载失败", e);
		} catch (ConfigurationException e) {
			LOG.error("加载失败", e);
		}
	}

