@SuppressWarnings("unchecked")
    public ImmutableSet<Object> getJerseyComponents() {
        Set<Object> components = getSetSafely(Keys.JerseyComponents);

        ImmutableSet.Builder<Object> builder = ImmutableSet.builder();

        for (Object classOrInstance : components) {
            if (classOrInstance instanceof Class) {
                Object instance = injector.getInstance((Class<Object>) classOrInstance);
                builder.add(instance);

            } else {
                builder.add(classOrInstance);
            }
        }

        return builder.build();
    }

public void addValue(String value, boolean isDefault) {
        p("Adding " + (isDefault ? "default " : "") + "value:" + value + " to parameter:" + m_field.getName());
        String name = m_wrappedParameter.names()[0];
        if (m_assigned && !isMultiOption()) {
            throw new ParameterException("Can only specify option " + name + " once.");
        }

        validateParameter(name, value);

        Class<?> type = m_field.getType();

        Object convertedValue = m_jCommander.convertValue(this, value);
        boolean isCollection = Collection.class.isAssignableFrom(type);

        try {
            if (isCollection) {
                @SuppressWarnings("unchecked") Collection<Object> l = (Collection<Object>) m_field.get(m_object);
                if (l == null || fieldIsSetForTheFirstTime(isDefault)) {
                    l = newCollection(type);
                    m_field.set(m_object, l);
                }
                if (convertedValue instanceof Collection) {
                    l.addAll((Collection) convertedValue);
                } else { // if (isMainParameter || m_parameterAnnotation.arity() > 1) {
                    l.add(convertedValue);
//        } else {
//          l.
                }
            } else {
                m_wrappedParameter.addValue(m_field, m_object, convertedValue);
            }
            if (!isDefault) m_assigned = true;
        } catch (IllegalAccessException ex) {
            ex.printStackTrace();
        }
    }

public Set<T> resolve(Matcher<T> matcher) throws IOException {
		Set<T> classes = new HashSet<T>();

		for (URL url : paths) {
			if (url.toString().endsWith(".jar")) {
//				System.out.println(url);
				JarFile jarFile = new JarFile(URLDecoder.decode(url.getPath(), "UTF-8"));
				Manifest manifest = jarFile.getManifest();

				if (manifest != null) {
//					System.out.println(manifest);
					Attributes mainAttributes = manifest.getMainAttributes();

					if (mainAttributes != null) {
//						System.out.println(mainAttributes);
						String classpath = mainAttributes.getValue(Name.CLASS_PATH);

						if (classpath != null) {
//							System.out.println(classpath);
							StringTokenizer stringTokenizer = new StringTokenizer(classpath);

							while (stringTokenizer.hasMoreTokens()) {
								String token = stringTokenizer.nextToken();
								URL entry = new URL(url, token);

								if (entry.toString().endsWith("/")) {
//									System.out.println(entry);
									classes.addAll(getMatchedClasses(matcher, new File(URLDecoder.decode(entry.getPath(), "UTF-8"))));
								} else {
//									System.out.println(entry);
									classes.addAll(getMatchedClasses(matcher, new JarFile(URLDecoder.decode(entry.getPath(), "UTF-8"))));
								}
							}
						}
					}
				}

				classes.addAll(getMatchedClasses(matcher, jarFile));
			} else {
				File base = new File(URLDecoder.decode(url.getPath(), "UTF-8"));
				classes.addAll(getMatchedClasses(matcher, base));
			}
		}

		return classes;
	}

