public long stop() {
		if (isRunning()) {
			stop = System.nanoTime();
			total += stop - start;
			running = false;
		}

		return Math.round(total * getPrecision().value);
	}

public long getTime() {
		long time = (isRunning()) ? total + System.nanoTime() - start : total;
		return Math.round(time * getPrecision().value);
	}

