@Override
	public Set<Class<?>> resolveByName(final String name) throws IOException {
		Matcher<Class<?>> matcher = new Matcher<Class<?>>() {

			public boolean matches(Class<?> clazz) {
				return clazz.getName().contains(name);
			}

		};
		return resolve(matcher);
	}

@Override
	public Set<Class<?>> resolveBySuperclass(final Class<?> superclass)
			throws IOException {
		Matcher<Class<?>> matcher = new Matcher<Class<?>>() {

			public boolean matches(Class<?> clazz) {
				if (clazz.getSuperclass() != null) {
					if (clazz.getSuperclass().equals(superclass)) {
						return true;
					} else {
						return matches(clazz.getSuperclass());
					}

				} else {
					return false;
				}
			}

		};
		return resolve(matcher);
	}

@Override
	public Set<Class<?>> resolveByInterface(final Class<?> interfaceClass)
			throws IOException {
		Matcher<Class<?>> matcher = new Matcher<Class<?>>() {

			public boolean matches(Class<?> clazz) {
				Class<?>[] interfaces = clazz.getInterfaces();

				for (Class<?> c : interfaces) {
					if (c.equals(interfaceClass)) {
						return true;
					}
				}

				if (clazz.getSuperclass() != null) {
					return matches(clazz.getSuperclass());
				} else {
					return false;
				}
			}

		};
		return resolve(matcher);
	}

@Override
	public Set<Class<?>> resolveByAnnotation(
			final Class<? extends Annotation> annotation) throws IOException {
		Matcher<Class<?>> matcher = new Matcher<Class<?>>() {

			public boolean matches(Class<?> clazz) {
				Annotation[] annotations = clazz.getAnnotations();

				for (Annotation a : annotations) {
					if (a.annotationType().equals(annotation)) {
						return true;
					}
				}

				return false;
			}

		};
		return resolve(matcher);
	}

protected void initialize(Class<T> mappedClass) {
        this.mappedClass = mappedClass;
        this.mappedFields = new HashMap<String, Field>();

        Field fields[] = mappedClass.getFields();
        for (Field field : fields) {
            int mod = field.getModifiers();
            if (Modifier.isPublic(mod) && !Modifier.isStatic(mod)) {
                for(Annotation a: field.getAnnotations()) {
                    if (a.annotationType().isAssignableFrom(Column.class)) {
                        Column c = (Column)a;
                        String columnName = c.name();
                        mappedFields.put(columnName, field);
                    }
                }
            }
        }
    }

@Override
    public T mapRow(ResultSet rs, int rowNumber) throws SQLException {
        Assert.state(this.mappedClass != null, "Mapped class was not specified");

        T mappedObject;
        try {
            mappedObject = mappedClass.newInstance();
        }
        catch(Exception ex) {
            throw new RuntimeException(ex);
        }

        ResultSetMetaData rsmd = rs.getMetaData();
        int columnCount = rsmd.getColumnCount();

        for (int index = 1; index <= columnCount; index++) {
            String column = JdbcUtils.lookupColumnName(rsmd, index);
            Field field = this.mappedFields.get(column.replaceAll(" ", ""));
            if (field != null) {
                Object value = getColumnValue(rs, index, field);
                if (logger.isTraceEnabled() && rowNumber == 0) {
                    logger.trace("Mapping column '" + column + "' to property '" +
                            field.getName() + "' of type " + field.getType());
                }
                try {
                    field.set(mappedObject, value);
                }
                catch (IllegalArgumentException e) {
                    if (value == null && primitivesDefaultedForNullValue) {
                        logger.debug("Intercepted IllegalArgumentException for row " + rowNumber +
                                " and column '" + column + "' with value " + value +
                                " when setting property '" + field.getName() + "' of type " + field.getType() +
                                " on object: " + mappedObject);
                    }
                    else {
                        throw e;
                    }
                } catch (IllegalAccessException e) {
                    e.printStackTrace();
                }
            }
        }

        return mappedObject;
    }

public static <T> RecordMapper<T> newInstance(Class<T> mappedClass) {
        RecordMapper<T> newInstance = new RecordMapper<T>();
        newInstance.setMappedClass(mappedClass);
        return newInstance;
    }

